// The signed-in member's display name + initials, from the same source as the
// Me page (profiles.full_name, which the edit-profile flow writes + mirrors to
// the auth cache). Falls back to the demo identity when signed out, so the
// header avatars always read sensibly. Keeps every "your own" avatar in sync
// with the account's real name instead of a hardcoded "A".
function bsMyName() {
  const st = (typeof window !== 'undefined' && window.ShapeAuth && window.ShapeAuth.getCachedState && window.ShapeAuth.getCachedState()) || {};
  const p = st.profile || {};
  const fromProfile = p.full_name && String(p.full_name).trim();
  if (fromProfile) return fromProfile;
  // Signed in but the profile row has no name yet (e.g. just after confirming a
  // new account) → derive the name from the signup metadata, then the email
  // local-part. NEVER fall back to the demo persona while signed in — that's
  // what made a fresh account show "Quinn Harper" + demo initials.
  if (st.user) {
    const meta = st.user.user_metadata && st.user.user_metadata.full_name && String(st.user.user_metadata.full_name).trim();
    if (meta) return meta;
    const email = (st.user.email && String(st.user.email).trim()) || '';
    if (email.includes('@')) return email.split('@')[0];
    return 'Shape member';
  }
  return 'Quinn Harper'; // signed-out demo / preview only
}
// Up-to-two-letter initials from a display name (drops a leading "# " for channels).
function bsInitials(name) {
  return String(name || '').replace(/^#\s*/, '').split(/\s+/).filter(Boolean).map(w => w[0]).slice(0, 2).join('').toUpperCase();
}
// A photo source only counts if it's a real, non-empty image URL — so a blank/
// stale stored value ('', 'null', a bodyless data: URI) is ignored and the avatar
// falls back to initials instead of rendering an invisible/blank image over them.
function bsValidPhoto(p) {
  const s = (p == null ? '' : String(p)).trim();
  if (!s || s === 'null' || s === 'undefined') return null;
  if (/^data:/i.test(s)) return /^data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]{16,}/i.test(s) ? s : null;
  if (/^(https?:|blob:|\/)/i.test(s)) return s;
  return null;
}
function bsMyInitials() {
  // A custom override (set in edit-profile, cached on window.ShapeIdentity) wins;
  // otherwise derive from the display name.
  const custom = (typeof window !== 'undefined' && window.ShapeIdentity && window.ShapeIdentity.initials) || '';
  const c = String(custom).trim().toUpperCase().slice(0, 2);
  return c || bsInitials(bsMyName()) || 'A';
}
// My avatar photo: the real saved profile photo when signed in. In the
// signed-out demo/preview, the demo identity (Quinn Harper) gets the dedicated
// demo headshot (`demo-avatar.png`, served at /m/) so the avatars demonstrate
// the photo treatment. A signed-in account with no photo stays on initials —
// never a stranger's face.
function bsMyPhotoRaw() {
  const real = bsValidPhoto(typeof window !== 'undefined' && window.ShapeIdentity && window.ShapeIdentity.photo);
  if (real) return real;
  const signedIn = !!(typeof window !== 'undefined' && window.ShapeAuth?.getCachedState?.()?.user?.id);
  return signedIn ? null : `${import.meta.env.BASE_URL}demo-avatar.png`;
}
function bsMyPhoto() {
  // Avatar-source preference (set in profile settings): 'initials' forces the
  // initials gem everywhere, even when a photo is stored (the photo is kept, just
  // not shown). Applies app-wide since every self avatar reads through here.
  if (typeof window !== 'undefined' && window.ShapeIdentity && window.ShapeIdentity.avatarMode === 'initials') return null;
  return bsMyPhotoRaw();
}
// Load THIS account's identity doc (custom initials / accent / name / photo /
// avatarMode) into the global cache, REPLACING — never merging — so a fresh
// account can't inherit a prior session's or the demo's override (empty doc →
// reset to {}). Window-exposed so the coach bundles hydrate the same way (they
// share these avatar helpers); fires shape:identity so on-screen avatars re-render.
function bsHydrateIdentity() {
  if (typeof window === 'undefined' || !(window.shapeDb && window.shapeDb.getUserGoals)) return Promise.resolve();
  return window.shapeDb.getUserGoals('client_identity').then((d) => {
    try { window.ShapeIdentity = (d && typeof d === 'object' && Object.keys(d).length) ? { ...d } : {}; } catch (e) {}
    try { window.dispatchEvent(new Event('shape:identity')); } catch (e) {}
  }).catch(() => {});
}
// Serialized identity writer — both the edit form and the photo picker call this,
// so concurrent saves can't race: each merges its patch over the FRESHEST stored
// doc (never dropping a sibling field like avatarMode or photo), persists, and
// reconciles the cache. Chained so writes apply in order.
let _bsIdentitySaveChain = Promise.resolve();
function bsSaveIdentity(patch) {
  _bsIdentitySaveChain = _bsIdentitySaveChain.then(async () => {
    let existing = {};
    try { const p = window.shapeDb?.getUserGoals?.('client_identity'); existing = (p && p.then ? await p : p) || {}; } catch (e) {}
    const merged = { ...(existing || {}), ...(patch || {}) };
    let res = null;
    try { res = await window.shapeDb?.saveUserGoals?.('client_identity', merged); } catch (e) {}
    try { window.ShapeIdentity = merged; window.dispatchEvent(new Event('shape:identity')); } catch (e) {}
    return res;
  }).catch(() => null);
  return _bsIdentitySaveChain;
}
// My current Shape Score tier (cached on window.ShapeScore from /api/client/score)
// and its color. Avatars across the app fill with my tier color — Base/steel until
// I earn points — so the avatar reflects standing, not a chosen accent.
function bsMyTier() {
  const s = (typeof window !== 'undefined' && window.ShapeScore) || null;
  if (s && s.tier) return s.tier; // live tier (signed in, score loaded)
  // Signed in but no live score yet (e.g. a brand-new account) → real accounts
  // start at Base/steel, NOT the demo persona's tier. Only the signed-out
  // preview falls back to the demo client tier.
  const signedIn = !!(typeof window !== 'undefined' && window.ShapeAuth?.getCachedState?.()?.user?.id);
  if (signedIn) return 'Base';
  return (SHAPE_SCORE_PROFILES.client && SHAPE_SCORE_PROFILES.client.tier) || 'Base';
}
function bsMyTierColor() {
  return bsTierColor(bsMyTier());
}

// Am I live on Shape right now? Signed in + the app open = online, unless I've
// turned off "show when I'm online" (window.ShapeOnlineVisible, default true).
// Drives the pulsing outer ring on my own avatar everywhere.
function bsAmLive() {
  try {
    const signedIn = !!(window.ShapeAuth && window.ShapeAuth.getCachedState && window.ShapeAuth.getCachedState().user && window.ShapeAuth.getCachedState().user.id);
    return signedIn && window.ShapeOnlineVisible !== false;
  } catch (e) { return false; }
}
// Is a specific member online right now? Reads the live Supabase presence set
// (ShapePresence), which only contains people currently broadcasting (so it
// already respects each person's "show when I'm online" toggle).
function bsIsUserOnline(uid) {
  try { return !!(uid && window.ShapePresence && window.ShapePresence.isOnline && window.ShapePresence.isOnline(uid)); } catch (e) { return false; }
}
// What is a member doing right now? 'workout' | 'cooking' | null — drives the
// corner activity dot (teal = in a workout, amber = cooking). Live via presence.
function bsUserActivity(uid) {
  try { return (uid && window.ShapePresence && window.ShapePresence.activityOf && window.ShapePresence.activityOf(uid)) || undefined; } catch (e) { return undefined; }
}
// My own current activity (so my avatars' dot reflects what I'm doing).
function bsMyActivity() {
  try { return (window.ShapePresence && window.ShapePresence.myActivity && window.ShapePresence.myActivity()) || undefined; } catch (e) { return undefined; }
}
// Broadcast that I started/stopped a live activity. Pass null to clear.
function bsSetMyActivity(kind) {
  try { window.ShapePresence && window.ShapePresence.setActivity && window.ShapePresence.setActivity(kind || null); } catch (e) {}
}
// Re-render hook: bumps whenever the online presence set changes.
function useBSPresence() {
  const [v, setV] = useStateBSC(0);
  React.useEffect(() => {
    const bump = () => setV(x => x + 1);
    let off = null;
    try { off = window.ShapePresence && window.ShapePresence.onChange && window.ShapePresence.onChange(bump); } catch (e) {}
    try { window.addEventListener('shape:presence', bump); } catch (e) {}
    return () => { try { off && off(); } catch (e) {} try { window.removeEventListener('shape:presence', bump); } catch (e) {} };
  }, []);
  return v;
}

const BS_HEADER_AVATAR = 34; // canonical top-header avatar (+ paired search/pencil/gear) size

// Monochrome ⌕ — opens the universal search screen via a window event
// (handled in BSClientAppInner / the coach shells), so any header can drop it
// in without prop-threading. Always sits to the LEFT of the profile avatar.
function BSSearchCorner({ size = BS_HEADER_AVATAR, ink = null }) {
  const t = useBS();
  // `ink` matches the profile mastheads' pencil/gear chrome (0.3-alpha border +
  // 14px glyph) so the corner buttons read as one set. Fill stays transparent —
  // paper ground, same as every other page's corners (owner call 2026-07-14).
  const g = ink ? 14 : Math.max(13, Math.round(size * 0.44));
  return (
    <button onClick={() => { try { window.dispatchEvent(new CustomEvent('shape:openSearch')); } catch (e) {} }} aria-label="Search Shape"
      style={{ width: size, height: size, flexShrink: 0, borderRadius: 999, border: `1px solid ${ink ? bsTHexA(ink, 0.3) : t.RULE}`, background: 'transparent', color: ink || t.INK, cursor: 'pointer', display: 'grid', placeItems: 'center', padding: 0 }}>
      <svg width={g} height={g} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={ink ? 2.2 : 2.4} strokeLinecap="round"><circle cx="10.5" cy="10.5" r="6.2" /><path d="m15.3 15.3 5.2 5.2" /></svg>
    </button>
  );
}

// Header tool cluster — universal search + the profile avatar. Used as the
// `trailing` of every main page header.
// Re-render whenever identity changes (profile save / sign-in resolve), so a
// "self" avatar always reflects the latest name/initials/photo even if a parent
// didn't re-render. Belt-and-suspenders alongside the app-level identityVersion.
function useBSIdentityTick() {
  const [, force] = useStateBSC(0);
  React.useEffect(() => {
    const f = () => force((v) => v + 1);
    window.addEventListener('shape:identity', f);
    return () => window.removeEventListener('shape:identity', f);
  }, []);
}
function BSHeaderTools({ onProfile, size = BS_HEADER_AVATAR }) {
  useBSIdentityTick();
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 9 }}>
      <BSSearchCorner size={size} />
      <BSFacetAvatar size={size} c={bsMyTierColor()} initial={bsMyInitials()} name={bsMyName()} photo={bsMyPhoto() || undefined} live={bsAmLive()} activity={bsMyActivity()} showRank={false} onClick={onProfile} />
    </span>
  );
}

// Top-right tools for sub-pages — search + the profile avatar (taps through to
// Settings/profile via a window event, handled in BSClientAppInner), so a page
// needn't thread props. Drop it into a page's back-button row, right-aligned.
function BSMeCorner({ size = BS_HEADER_AVATAR }) {
  useBSIdentityTick();
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      <BSSearchCorner size={size} />
      <BSFacetAvatar size={size} c={bsMyTierColor()} initial={bsMyInitials()} name={bsMyName()} photo={bsMyPhoto() || undefined} live={bsAmLive()} activity={bsMyActivity()} showRank={false} onClick={() => { try { window.dispatchEvent(new CustomEvent('shape:openProfile')); } catch (e) {} }} />
    </span>
  );
}
// The chrome's pinned condensed masthead (BSPage) renders this as its trailing
// corner — window-exposed because the chrome module can't import client components.
window.BSMastCorner = BSMeCorner;

// The fx color pick → the tint RadioEffects pins every layer to. 'cycle'
// (default) returns null = the drifting palette; 'accent' follows the app
// accent on the CURRENT paper; a hex is itself.
function bsFxTint(fxColor, t) {
  if (!fxColor || fxColor === 'cycle') return null;
  if (fxColor === 'accent') return t.ACCENT;
  return /^#[0-9a-fA-F]{6}$/.test(fxColor) ? fxColor : null;
}

// Renders the music-reactive overlay (edge glow / bloom / hologram DJ)
// only while radio is on, not paused, and fxMode != 'off'.
function BSRadioFx() {
  const r = useBSRadio();
  const t = useBS();
  if (bsSdReduced()) return null; // the OS reduced-motion signal outranks the fx opt-in
  if (!r.radioOn || r.paused) return null;
  if (!r.fxMode || r.fxMode === 'off') return null;
  if (typeof RadioEffects !== 'function') return null;
  const label = `${r.LIVE.show.toUpperCase()} · ${r.LIVE.bpm} BPM`;
  return <RadioEffects mode={r.fxMode} label={label} tint={bsFxTint(r.fxColor, t)} />;
}

