// First-launch "How Shape Score works" explainer — a one-time full-screen panel
// shown as soon as a new account opens the app (before the app tour). Explains the
// one-number idea, the tier ladder, the main ways to earn, that consistency
// compounds, that points are spendable, and (gently) that lapsing dips the number.
function BSScoreIntro({ onClose, onOpenScore }) {
  const t = useBS();
  const tr = useShapeTr();
  const accent = t.isLight ? '#0a8f87' : '#34d6c5';
  const rust = t.RUST || '#c0533b';
  _bsScrollTopOnMount();
  const tierColor = (n) => (typeof bsTierColor === 'function' ? bsTierColor(n) : accent);
  // onClose(skipped): "Got it" passes false, SKIP passes true — the shell chains the
  // app tour only after an engaged (non-skip) dismissal.
  const dismiss = (skipped) => { bsMarkScoreIntroSeen(); onClose && onClose(!!skipped); };
  const eyebrow = { fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: accent };
  const sec = (label, color) => (
    <div style={{ marginTop: 18, marginBottom: 8 }}>
      <div style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: color || t.INK70 }}>{label}</div>
      <div style={{ marginTop: 3, height: 2, borderRadius: 2, background: `linear-gradient(90deg, ${bsTHexA(t.INK, 0.45)}, ${color || accent})` }} />
    </div>
  );
  // A curated subset of the REAL earn catalog (the Score page's `activities` list —
  // keep in sync with it, never invent a row). Ordered daily loop first: what a new
  // member actually does tomorrow. The footnote below points at the full list, so
  // showing a subset stays honest. Point values stay literal (numerals, not prose).
  // [stableId, label, pts] — the React key rides the id, NEVER the translated
  // label: two labels can collide in some locale, and a localized key is unstable
  // across a language switch.
  const earn = [
    ['workout', tr('onboarding:score.earn.workout', { defaultValue: 'Log a workout' }), '+10'],
    ['meal', tr('onboarding:score.earn.meal', { defaultValue: 'Log a meal' }), '+10'],
    ['habit', tr('onboarding:score.earn.habit', { defaultValue: 'Complete a habit' }), '+3'],
    ['checkin', tr('onboarding:score.earn.checkin', { defaultValue: 'Weekly check-in' }), '+15'],
    ['steps', tr('onboarding:score.earn.steps', { defaultValue: 'Daily steps' }), '+1 / 5k'],
    ['prPost', tr('onboarding:score.earn.prPost', { defaultValue: 'New PR · community post' }), '+12 · +5'],
    ['goal', tr('onboarding:score.earn.goal', { defaultValue: 'Goal milestone' }), '+50-200'],
    ['momentum', tr('onboarding:score.earn.momentum', { defaultValue: 'Momentum (hold 80+)' }), '+25-100'],
  ];
  // Tier NAMES + ranges stay literal (brand rungs / numerals); the perk is prose, so
  // it's keyed by rung. SHAPE_SCORE_TIERS is shared with the Score page — and so are
  // the perk STRINGS: both surfaces read `score:tierPerk.*`, so a perk can never say
  // one thing here and another on the Score page. Never mutate the shared data.
  const tierPerk = (name) => tr('score:tierPerk.' + String(name).toLowerCase(), { defaultValue: (SHAPE_SCORE_TIERS.find((x) => x.name === name) || {}).perk || '' });
  return (
    <div style={{ position: 'absolute', inset: 0, background: t.PAPER, zIndex: 70, overflowY: 'auto', WebkitOverflowScrolling: 'touch' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 18px 6px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {typeof BSLogo !== 'undefined' && BSLogo && <BSLogo size={16} color={t.INK} />}
          <div style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK70 }}>Vol. 1 · No. 1</div>
        </div>
        {/* Uppercase via CSS, never JS: String.toUpperCase() is locale-insensitive
            (Turkish i → I, should be İ). text-transform honors the document locale. */}
        <button onClick={() => dismiss(true)} aria-label={tr('onboarding:score.skip', { defaultValue: 'Skip' })} style={{ background: 'none', border: 'none', cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>{tr('onboarding:score.skip', { defaultValue: 'Skip' })}</button>
      </div>
      <div style={{ padding: '0 18px 28px' }}>
        <div style={eyebrow}>{tr('onboarding:score.eyebrow', { defaultValue: 'Welcome · Shape Score' })}</div>
        {/* pre / accent / post: the accent word sits MID-sentence in English, and its
            position moves per language — so each locale distributes the words across
            the three keys (leaving post empty where it falls last). */}
        <div style={{ fontFamily: t.DISPLAY, fontSize: 29, fontWeight: 700, color: t.INK, letterSpacing: '-0.025em', margin: '6px 0 10px', lineHeight: 1.05 }}>{tr('onboarding:score.titlePre', { defaultValue: 'How your Shape' })} <span style={{ fontStyle: 'italic', color: accent }}>{tr('onboarding:score.titleAccent', { defaultValue: 'Score' })}</span>{tr('onboarding:score.titlePost', { defaultValue: ' works.' })}</div>
        <div style={{ fontFamily: t.BODY, fontSize: 14, color: t.INK70, lineHeight: 1.5 }}>{tr('onboarding:score.intro', { defaultValue: 'One number for showing up. Everything you log feeds it — and it climbs as you stay consistent. Here’s the gist.' })}</div>

        {sec(tr('onboarding:score.tiers.head', { defaultValue: 'Climb the tiers' }))}
        <div style={{ fontFamily: t.BODY, fontSize: 12.5, color: t.INK70, lineHeight: 1.45, marginBottom: 10 }}>{tr('onboarding:score.tiers.body', { defaultValue: 'Earn points to climb — and your tier never goes down once you reach it.' })}</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
          {/* NOTE: this callback param was named `tr` — it SHADOWED the translator
              inside the map (the tr-shadow crash class, and a variant the documented
              `const tr =` grep can't see because it's a parameter). Renamed to `rung`;
              don't reintroduce a `tr` binding here. */}
          {SHAPE_SCORE_TIERS.map((rung) => (
            <div key={rung.name} style={{ display: 'grid', gridTemplateColumns: 'auto 1fr auto', gap: 9, alignItems: 'center' }}>
              <span style={{ width: 9, height: 9, borderRadius: 3, background: tierColor(rung.name) }} />
              <span style={{ fontFamily: t.DISPLAY, fontSize: 14, fontWeight: 700, color: t.INK }}>{rung.name}<span style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 700, color: t.INK50, marginLeft: 7 }}>{rung.range}</span></span>
              <span style={{ fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.04em', textTransform: 'uppercase', color: t.INK50, textAlign: 'right' }}>{tierPerk(rung.name)}</span>
            </div>
          ))}
        </div>

        {sec(tr('onboarding:score.earn.head', { defaultValue: 'Ways to earn' }))}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {earn.map(([id, k, p]) => (
            <div key={id} style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
              <span style={{ fontFamily: t.BODY, fontSize: 13.5, color: t.INK }}>{k}</span>
              <span style={{ fontFamily: t.MONO, fontSize: 11, fontWeight: 800, letterSpacing: '0.06em', color: accent }}>{p}</span>
            </div>
          ))}
        </div>
        {/* The bold lead is its own key: a phrase most languages can front. The rest
            is one sentence — never split prose AROUND a bold span, word order moves. */}
        <div style={{ fontFamily: t.BODY, fontSize: 12.5, color: t.INK70, lineHeight: 1.45, marginTop: 9 }}><b style={{ color: t.INK }}>{tr('onboarding:score.earn.compoundsLead', { defaultValue: 'Consistency compounds' })}</b> {tr('onboarding:score.earn.compoundsBody', { defaultValue: '— hold your momentum and the weekly bonus grows. Your Score page lists every way to earn.' })}</div>

        {sec(tr('onboarding:score.spend.head', { defaultValue: 'Spend what you earn' }))}
        <div style={{ fontFamily: t.BODY, fontSize: 12.5, color: t.INK70, lineHeight: 1.45 }}>{tr('onboarding:score.spend.body', { defaultValue: 'Turn points into real rewards — session credit, gear and more — in the Shape Store. Spending never lowers your rank.' })}</div>

        {sec(tr('onboarding:score.protect.head', { defaultValue: 'Protect your points' }), rust)}
        <div style={{ fontFamily: t.BODY, fontSize: 12.5, color: t.INK70, lineHeight: 1.45 }}>{tr('onboarding:score.protect.body', { defaultValue: 'Stay consistent to keep them. Skip a committed check-in or workout and the number dips a little — a coach can always waive it, and you never drop below 0.' })}</div>

        <button onClick={() => dismiss(false)} style={{ marginTop: 24, width: '100%', borderRadius: 6, border: 0, background: accent, color: '#04201d', cursor: 'pointer', padding: '13px', fontFamily: t.MONO, fontSize: 11, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>{tr('onboarding:score.gotIt', { defaultValue: 'Got it' })}</button>
        <button onClick={() => { bsMarkScoreIntroSeen(); if (onOpenScore) onOpenScore(); }} style={{ marginTop: 9, width: '100%', background: 'none', border: 'none', cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: accent }}>{tr('onboarding:score.seeScore', { defaultValue: 'See my score →' })}</button>
      </div>
    </div>
  );
}

function BSClientAppInner({ onLogout, tweaks, setTweak, initialTab = 'home' }) {
  const sheet = useBSSheet();
  const tr = useShapeTr(); // i18n — re-renders the shell (tab bar labels) on locale change
  const [tab, setTab] = useStateBSC(initialTab);
  const [showSettings, setShowSettings] = useStateBSC(false);
  const [settingsStart, setSettingsStart] = useStateBSC('');
  const [showCalendar, setShowCalendar] = useStateBSC(false);
  const [pendingTrainStart, setPendingTrainStart] = useStateBSC(false); // one-shot: auto-launch the live session, then cleared so it doesn't re-fire on remount
  const [storeView, setStoreView] = useStateBSC('store');
  const [marketRole, setMarketRole] = useStateBSC(null); // 'trainer' | 'nutritionist' | null
  const [marketCoach, setMarketCoach] = useStateBSC(null); // { role, providerId } — deep-open a coach's Listing (e.g. a chat coach_invite card)
  const [identityVersion, setIdentityVersion] = useStateBSC(0); // bumped on profile save → re-render avatars now
  const [showTour, setShowTour] = useStateBSC(false); // first-run app tour overlay
  const [showScoreIntro, setShowScoreIntro] = useStateBSC(false); // first-run "how Shape Score works" explainer
  const scoreProfile = SHAPE_SCORE_PROFILES.client;
  // ── Nav history (spec 2026-07-09): replay targets for popped descriptors ──
  const [eatStart, setEatStart] = useStateBSC('');
  const [meStart, setMeStart] = useStateBSC('');
  // THE CYCLE (spec 2026-07-19) — the calendar rides the takeover pattern so
  // back returns to wherever the member opened it from.
  const [showCycle, setShowCycle] = useStateBSC(false);
  // The shell-visible location. Child-owned sub-state (Settings' active
  // sub-page, Eat's view, Me's sub-page, Chat's open thread) rides in via the
  // announce register at compose time — see bsNavCompose.
  const navLoc = () => {
    if (showSettings) return { tab, overlay: 'settings', sub: settingsStart || '' };
    if (showCalendar) return { tab, overlay: 'calendar' };
    if (showSearch) return { tab, overlay: 'search' };
    if (showCycle) return { tab, overlay: 'cycle' };
    if (tab === 'store') return { tab: 'store', sub: storeView };
    if (tab === 'market') return { tab: 'market', detail: marketRole ? { role: marketRole } : undefined };
    return { tab };
  };
  // Replay a popped descriptor onto the existing entry points. NEVER pushes.
  const navResolve = (loc) => {
    if (!loc) return;
    setShowSearch(loc.overlay === 'search');
    setShowCalendar(loc.overlay === 'calendar');
    setShowCycle(loc.overlay === 'cycle');
    if (loc.overlay === 'settings') { setSettingsStart(loc.sub || ''); setShowSettings(true); }
    else { setShowSettings(false); setSettingsStart(''); }
    if (loc.tab === 'store') setStoreView(loc.sub === 'score' ? 'score' : 'store');
    if (loc.tab === 'market') { setMarketRole((loc.detail && loc.detail.role) || null); setMarketCoach(null); }
    if (loc.tab === 'chat' && loc.detail) setChatRequest({ ...loc.detail, nonce: Date.now() });
    if (loc.tab === 'eat') setEatStart(loc.sub || '');
    if (loc.tab === 'me') setMeStart(loc.sub || '');
    if (loc.tab) setTab(loc.tab);
  };
  const { navPush, navBack } = useBSNavHistory({ navLoc, navResolve });
  const goSettings = () => { navPush(); setSettingsStart(''); setShowSettings(true); };
  const goEditProfile = () => { navPush(); setSettingsStart('edit-profile'); setShowSettings(true); };
  const goIntegrations = () => { navPush(); setSettingsStart('integrations'); setShowSettings(true); };
  const goCycle    = () => { navPush(); setShowSettings(false); setShowCycle(true); };
  const goRadio    = () => { navPush(); setTab('radio'); };
  const goTrain    = () => { navPush(); setTab('train'); };
  const goMarket   = (role) => { navPush(); setMarketRole(typeof role === 'string' ? role : null); setMarketCoach(null); setTab('market'); };
  const goScore    = () => { navPush(); setStoreView('score'); setTab('store'); };
  // Open the chat tab on a specific coach's DM (Team → Coaches).
  const [chatRequest, setChatRequest] = useStateBSC(null);
  const goChat = (coach, role) => { navPush(); setChatRequest({ coach: coach || null, role: role || null, nonce: Date.now() }); setTab('chat'); };
  // The shape:* event effects below register ONCE ([] deps), so their handlers
  // must read the CURRENT render's jump closures at fire time — a mount-render
  // goSettings/goIntegrations would be frozen at that render's state. (navPush
  // itself is safe: useBSNavHistory reads navLoc through a per-render ref. The
  // goX helpers below still close over state directly, so they need this.)
  const navJumpRef = React.useRef({});
  // Swipe judgment (PR C): the chrome's BSNavGestures classifies raw touches
  // and dispatches shape:navGesture; THIS shell decides what an intent means.
  // 'back' = the stack, else close the top takeover (mirrors the smart-backs).
  // Tab swipes step the ROOT order only — never while a takeover is open, and
  // never from jump-destination screens (radio/market/store aren't tab stops).
  const [navSlideCls, navSlide] = useBSNavSlide(tab);
  const onNavGesture = (intent) => {
    if (intent === 'back') {
      if (navBack()) return;
      if (showSearch) { setShowSearch(false); return; }
      if (showSettings) { setShowSettings(false); setSettingsStart(''); return; }
      if (showCalendar) { setShowCalendar(false); return; }
      if (showCycle) setShowCycle(false);
      return;
    }
    if (showSettings || showCalendar || showSearch || showCycle) return;
    const next = bsNavStepTab(['home', 'train', 'eat', 'chat', 'me'], tab, intent);
    if (!next) return;
    navSlide(intent === 'next-tab' ? 'l' : 'r');
    setTab(next);
  };
  navJumpRef.current = { navPush, goSettings, goEditProfile, goIntegrations, goCycle, onNavGesture };
  useBSNavGestureHandler(navJumpRef);

  React.useEffect(() => {
    window.__shapeActiveTab = tab;
    window.dispatchEvent?.(new CustomEvent('shape:activeTabChanged', { detail: { tab } }));
  }, [tab]);

  // Let any deep component (e.g. a playlist card's "Connect Spotify" prompt)
  // jump to Settings → Connected apps without prop-threading.
  React.useEffect(() => {
    const open = () => navJumpRef.current.goIntegrations();
    window.addEventListener('shape:openIntegrations', open);
    return () => window.removeEventListener('shape:openIntegrations', open);
  }, []);

  // THE CYCLE — Settings' "Open cycle calendar", the Today chip and the
  // Progress card all fire this one event, so no prop threading.
  React.useEffect(() => {
    const open = () => navJumpRef.current.goCycle();
    window.addEventListener('shape:openCycle', open);
    return () => window.removeEventListener('shape:openCycle', open);
  }, []);

  // Tapping the top-right profile avatar on any screen opens Settings/profile
  // — fired as an event so sub-pages don't need an onProfile prop threaded in.
  React.useEffect(() => {
    const open = () => navJumpRef.current.goSettings();
    window.addEventListener('shape:openProfile', open);
    return () => window.removeEventListener('shape:openProfile', open);
  }, []);

  // The Goal page's "Primary goal · Edit" card (and anywhere else that wants the
  // profile editor itself, not just the Settings landing) deep-links straight
  // into the edit-profile pane where the Primary goal field lives.
  React.useEffect(() => {
    const open = () => navJumpRef.current.goEditProfile();
    window.addEventListener('shape:editProfile', open);
    return () => window.removeEventListener('shape:editProfile', open);
  }, []);

  // Jump to the marketplace from anywhere (e.g. the Pricing page's "Browse all
  // coaches"). Settings is a full-screen takeover, so close it first.
  React.useEffect(() => {
    // Honor the dispatcher's detail.role (e.g. a waitlist-invite notification, or
    // the Pricing "browse coaches" link) so the marketplace opens pre-filtered —
    // and detail.coachId (a chat coach_invite card) so it opens that coach's
    // Listing directly once the live providers load.
    const open = (e) => {
      navJumpRef.current.navPush(); setShowSettings(false); setSettingsStart('');
      setMarketRole(typeof e?.detail?.role === 'string' ? e.detail.role : null);
      setMarketCoach((typeof e?.detail?.role === 'string' && e?.detail?.coachId != null)
        ? { role: e.detail.role, providerId: Number(e.detail.coachId) }
        : null);
      setTab('market');
    };
    window.addEventListener('shape:openMarket', open);
    return () => window.removeEventListener('shape:openMarket', open);
  }, []);

  // About-page CTA — "Join the community." lands on the chat tab's community
  // feed. Clears EVERY takeover that early-returns above the tab body (Settings
  // can be opened from the Calendar takeover via onProfile, so closing settings
  // alone would land back on the calendar) plus any stale chat deep-link
  // (Codex catches on #1797 — the class, applied to this shell too).
  React.useEffect(() => {
    const open = () => {
      navJumpRef.current.navPush(); setShowSettings(false); setSettingsStart('');
      setShowCalendar(false); setShowSearch(false); setShowCycle(false);
      setChatRequest(null); setTab('chat');
    };
    window.addEventListener('shape:goCommunity', open);
    return () => window.removeEventListener('shape:goCommunity', open);
  }, []);

  // Universal search — the ⌕ in every header opens it (no prop-threading).
  const [showSearch, setShowSearch] = useStateBSC(false);
  React.useEffect(() => {
    const open = () => { navJumpRef.current.navPush(); setShowSearch(true); };
    window.addEventListener('shape:openSearch', open);
    return () => window.removeEventListener('shape:openSearch', open);
  }, []);

  // Inline ✉ on a search row → the real 1:1 thread; a channel result → that
  // channel's thread; Nora → the Support tab. All land in the Chat tab.
  React.useEffect(() => {
    const open = (e) => {
      const d = (e && e.detail) || {};
      if (!d.conversationId && !d.channel && !d.support) return;
      navJumpRef.current.navPush();
      setShowSearch(false);
      setChatRequest({ conversationId: d.conversationId || null, channel: d.channel || null, support: !!d.support, coach: d.name || null, nonce: Date.now() });
      setTab('chat');
    };
    window.addEventListener('shape:openConversation', open);
    return () => window.removeEventListener('shape:openConversation', open);
  }, []);

  // Hydrate the global identity cache (custom avatar initials / accent / name) and
  // the Shape Score tier at startup, so every avatar — header + feed — reflects the
  // right initials + tier color before the Me page is ever opened.
  React.useEffect(() => {
    // Shared hydrator (also called by the coach shells) — loads this account's
    // identity doc into window.ShapeIdentity and fires shape:identity, which the
    // bump listener below turns into a re-render.
    bsHydrateIdentity();
    fetch('/api/client/score', { credentials: 'same-origin' })
      .then(r => (r.ok ? r.json() : null))
      .then(d => { if (d && typeof d.points_total === 'number') { try { window.ShapeScore = { points: d.points_total || 0, tier: d.current_tier ? d.current_tier.name : 'Base' }; } catch (e) {} setIdentityVersion(v => v + 1); } })
      .catch(() => {});
  }, []);

  // A profile save (or score load) fires `shape:identity` → re-render so the avatars
  // on the CURRENT screen pick up new initials / tier color without navigating.
  React.useEffect(() => {
    const bump = () => setIdentityVersion(v => v + 1);
    window.addEventListener('shape:identity', bump);
    return () => window.removeEventListener('shape:identity', bump);
  }, []);

  // "Start session" from the calendar event sheet → close calendar, jump to the
  // Train tab, and auto-launch the live session there.
  React.useEffect(() => {
    const onStart = () => { navJumpRef.current.navPush(); setShowCalendar(false); setTab('train'); setPendingTrainStart(true); };
    window.addEventListener('shape:startWorkout', onStart);
    return () => window.removeEventListener('shape:startWorkout', onStart);
  }, []);

  // First-run Shape Score explainer: auto-show ONCE for newly-created accounts that
  // haven't seen it (its own seen-flag) — shown before the app tour so a new member
  // understands the scoring system as soon as they're in.
  React.useEffect(() => {
    let alive = true;
    let done = false;
    try { done = localStorage.getItem('shape.scoreIntroSeen') === '1'; } catch (e) {}
    if (done) return undefined;
    const NEW_MS = 24 * 60 * 60 * 1000;
    const decide = () => {
      if (!alive || done) return;
      const u = window.ShapeAuth?.getCachedState?.().user;
      if (!u) return;
      const created = u.created_at ? Date.parse(u.created_at) : NaN;
      if (!(Number.isFinite(created) && Date.now() - created < NEW_MS)) return;
      done = true;
      if (window.shapeDb?.getUserGoals) {
        window.shapeDb.getUserGoals('client_score_intro')
          .then(d => { if (!alive) return; if (d && d.seen) { try { localStorage.setItem('shape.scoreIntroSeen', '1'); } catch (e) {} } else setShowScoreIntro(true); })
          .catch(() => { if (alive) setShowScoreIntro(true); });
      } else { setShowScoreIntro(true); }
    };
    decide();
    const tid = setTimeout(decide, 1200);
    return () => { alive = false; clearTimeout(tid); };
  }, []);

  // First-run app tour — the PRIMARY path is chaining: the Score intro's "Got it"
  // calls chainTourAfterIntro() below, so a new member flows intro → tour in ONE
  // launch (the old later-launch handoff meant anyone who didn't relaunch inside the
  // 24h new-account window never saw the tour at all). Checks the same seen flags as
  // the mount effect; no new-account check needed — the intro only auto-shows for
  // <24h accounts, so chaining inherits that gate.
  const chainTourAfterIntro = () => {
    try { if (localStorage.getItem('shape.tourSeen') === '1') return; } catch (e) {}
    if (window.shapeDb?.getUserGoals) {
      window.shapeDb.getUserGoals('client_onboarding')
        .then(d => { if (d && d.tourSeen) { try { localStorage.setItem('shape.tourSeen', '1'); } catch (e) {} } else setShowTour(true); })
        .catch(() => setShowTour(true));
    } else setShowTour(true);
  };
  // Mount-time auto-show — now the FALLBACK for paths chaining doesn't cover (the
  // intro was skipped or exited via "See my score", then a relaunch inside the 24h
  // new-account window). localStorage fast-path + cloud user_goals so it doesn't
  // re-appear across devices. Replayable anytime via `shape:startTour`.
  React.useEffect(() => {
    let alive = true;
    let done = false;
    try { done = localStorage.getItem('shape.tourSeen') === '1'; } catch (e) {}
    if (done) return undefined;
    const NEW_MS = 24 * 60 * 60 * 1000; // "new account" window
    const decide = () => {
      if (!alive || done) return;
      const u = window.ShapeAuth?.getCachedState?.().user;
      if (!u) return; // signed out / not resolved yet — the tour is for new accounts
      const created = u.created_at ? Date.parse(u.created_at) : NaN;
      if (!(Number.isFinite(created) && Date.now() - created < NEW_MS)) return; // existing account
      // Let the one-time Shape Score intro go first — its "Got it" chains the tour
      // directly (chainTourAfterIntro above); this mount path only fires on a later
      // launch, so the two never stack.
      try { if (localStorage.getItem('shape.scoreIntroSeen') !== '1') return; } catch (e) {}
      done = true; // guard the retry below from double-firing
      if (window.shapeDb?.getUserGoals) {
        window.shapeDb.getUserGoals('client_onboarding')
          .then(d => { if (!alive) return; if (d && d.tourSeen) { try { localStorage.setItem('shape.tourSeen', '1'); } catch (e) {} } else setShowTour(true); })
          .catch(() => { if (alive) setShowTour(true); });
      } else { setShowTour(true); }
    };
    decide();
    const tid = setTimeout(decide, 1200); // auth may resolve just after first paint
    return () => { alive = false; clearTimeout(tid); };
  }, []);
  React.useEffect(() => {
    const start = () => { setShowSettings(false); setShowCalendar(false); setShowTour(true); };
    window.addEventListener('shape:startTour', start);
    return () => window.removeEventListener('shape:startTour', start);
  }, []);

  // Capture the device timezone once per login so coach-side SQL can bucket each
  // member's Sat/Sun in their own zone (weekend-vs-weekday adherence split).
  // identityVersion bumps on shape:identity (login / profile save), so this fires
  // once on mount and again when the auth state settles — the `signedIn` guard
  // ensures we only post for a real account, never for a signed-out preview.
  const signedIn = !!(window.ShapeAuth?.getCachedState?.()?.user?.id);
  React.useEffect(() => {
    if (!signedIn) return;            // only persist for a real account
    // Persist the device's RESOLVED zone — including a genuine 'UTC' (London/
    // Reykjavik); only skip when detection fails, so real-UTC members aren't
    // permanently suppressed on the coach path.
    let tz = null;
    try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || null; } catch { tz = null; }
    if (tz) { window.ShapeProfile?.setTimezone?.(tz); }
  }, [signedIn]);

  // Required one-time health profile (PAR-Q screening) for signed-in clients —
  // checked after auth resolves; 'unknown' renders the app normally so the
  // gate never flashes for members who already completed it.
  const [healthGate, setHealthGate] = useStateBSC('unknown'); // unknown | needed | ok
  React.useEffect(() => {
    let on = true;
    const check = async () => {
      const uid = window.ShapeAuth?.getCachedState?.()?.user?.id;
      if (!uid) { if (on) setHealthGate('ok'); return; } // signed-out preview skips
      try {
        const doc = await window.ShapeHealthProfile?.get?.();
        if (on) setHealthGate(doc && doc.consentAt ? 'ok' : 'needed');
      } catch (e) { if (on) setHealthGate('ok'); } // never lock out on a fetch error
    };
    check();
    const tid = setTimeout(check, 1600); // auth may resolve after first paint
    return () => { on = false; clearTimeout(tid); };
  }, []);

  // One-time identity-intent step ("What brings you here?") — shown once, BEFORE
  // the health screen, so Day 1 reflects what the member is here for. Keyed off
  // client_onboarding.intentSeen (NOT the goal field, which has a silent default).
  const [intentGate, setIntentGate] = useStateBSC('unknown'); // unknown | needed | ok
  React.useEffect(() => {
    let on = true;
    const check = async () => {
      const uid = window.ShapeAuth?.getCachedState?.()?.user?.id;
      if (!uid) { if (on) setIntentGate('ok'); return; } // signed-out preview skips
      try {
        const onb = await window.shapeDb?.getUserGoals?.('client_onboarding');
        if (on) setIntentGate(onb && onb.intentSeen ? 'ok' : 'needed');
      } catch (e) { if (on) setIntentGate('ok'); } // never lock out on a fetch error
    };
    check();
    const tid = setTimeout(check, 1600); // auth may resolve after first paint
    return () => { on = false; clearTimeout(tid); };
  }, []);

  if (intentGate === 'needed') {
    return <BSIntentStep onDone={() => setIntentGate('ok')} />;
  }
  if (healthGate === 'needed') {
    return <BSHealthIntake onDone={() => setHealthGate('ok')} />;
  }
  if (showSettings) {
    return (
      <BSSettings
        initialPage={settingsStart}
        onBack={() => { if (!navBack()) { setShowSettings(false); setSettingsStart(''); } }}
        onLogout={onLogout}
        tweaks={tweaks}
        setTweak={setTweak}
      />
    );
  }
  if (showCalendar) {
    return (
      <div style={{ position: 'absolute', inset: 0 }}>
        <BSCalendarScreen role="client" onProfile={goSettings} onBack={() => { if (!navBack()) setShowCalendar(false); }} />
        <BSRadioFx />
      </div>
    );
  }
  if (showCycle) {
    return (
      <div style={{ position: 'absolute', inset: 0 }}>
        <BSCycleCalendarPage onBack={() => { if (!navBack()) setShowCycle(false); }} />
        <BSRadioFx />
      </div>
    );
  }
  const screens = {
    home:    <BSClientHome     onProfile={goSettings} sheet={sheet} goCalendar={() => { navPush(); setShowCalendar(true); }} goRadio={goRadio} goTrain={goTrain} goEat={() => { navPush(); setTab('eat'); }} goMarket={goMarket} goScore={goScore} goChat={goChat} goIntegrations={goIntegrations} tweaks={tweaks} setTweak={setTweak} />,
    train:   <BSClientTrain    onProfile={goSettings} sheet={sheet} goCalendar={() => { navPush(); setShowCalendar(true); }} goRadio={goRadio} goMarket={goMarket} autoStart={pendingTrainStart} onAutoStartConsumed={() => setPendingTrainStart(false)} />,
    eat:     <BSClientEat      onProfile={goSettings} sheet={sheet} goRadio={goRadio} goMarket={goMarket} initialView={eatStart} onStartConsumed={() => setEatStart('')} />,
    chat:    <BSClientFeed     onProfile={goSettings} role={tweaks.role || 'client'} openRequest={chatRequest} />,
    radio:   <BSRadioScreen    onBack={() => { if (!navBack()) setTab('home'); }} />,
    market:  <BSMarketplaceScreen initialRole={marketRole} initialCoach={marketCoach} onCoachConsumed={() => setMarketCoach(null)} onBack={() => { if (!navBack()) setTab('home'); }} onProfile={goSettings} goChat={goChat} />,
    store:   storeView === 'score'
      ? <BSShapeScorePage profile={scoreProfile} onBack={() => setStoreView('store')} onOpenStore={() => setStoreView('store')} />
      : <BSShapeStorePage profile={scoreProfile} onBack={() => { if (!navBack()) setTab('home'); }} onOpenScore={() => setStoreView('score')} />,
    me:      <BSClientMe       onProfile={goSettings} onLogout={onLogout} onIntegrations={goIntegrations} goMarket={goMarket} goRadio={goRadio} goChat={goChat} goHome={() => setTab('home')} sheet={sheet} tweaks={tweaks} setTweak={setTweak} initialPage={meStart} onStartConsumed={() => setMeStart('')} />,
  };
  // navSlideCls (from useBSNavSlide): one-shot on a tab SWIPE, cleared in an
  // effect after commit; a tab TAP renders instantly; reduced-motion in CSS.
  return (
    <div style={{ position: 'absolute', inset: 0 }} data-identity-version={identityVersion}>
      <div key={tab} className={navSlideCls} style={{ position: 'absolute', inset: 0 }}>
        {screens[tab]}
      </div>
      <BSRadioFx />
      {/* Pinned message composers (chat feed + DM threads) portal into this
          slot so they're positioned against the phone-frame container — not
          the browser viewport. A viewport-fixed composer overhangs the frame
          in the desktop preview where the frame is narrower than the window. */}
      <div id="bs-composer-slot" style={{
        position: 'absolute', left: 0, right: 0,
        bottom: 72,
        zIndex: 60, pointerEvents: 'none',
      }} />
      <BSTabBar
        active={tab}
        onChange={setTab}
        tabs={[
          { key: 'home',  label: tr('common:nav.home',  { defaultValue: 'Home' }),  emoji: '🏠' },
          { key: 'train', label: tr('common:nav.train', { defaultValue: 'Train' }), emoji: '🏋️' },
          { key: 'eat',   label: tr('common:nav.eat',   { defaultValue: 'Eat' }),   emoji: '🍎' },
          { key: 'chat',  label: tr('common:nav.chat',  { defaultValue: 'Chat' }),  emoji: '💬' },
          { key: 'me',    label: tr('common:nav.me',    { defaultValue: 'Me' }),    emoji: '👤' },
        ]}
      />
      <BSRadioPrompt />
      {showSearch && <BSUniversalSearch onClose={() => { if (!navBack()) setShowSearch(false); }} />}
      {showScoreIntro && <BSScoreIntro onClose={(skipped) => { setShowScoreIntro(false); if (!skipped) chainTourAfterIntro(); }} onOpenScore={() => { setShowScoreIntro(false); goScore(); }} />}
      {showTour && <BSOnboardingTour onClose={() => setShowTour(false)} onNavigate={setTab} />}
    </div>
  );
}

function BSClientApp({ onLogout, tweaks, setTweak, initialTab = 'home' }) {
  // BSRadioProvider is provided by the entry-point shell (iosAppHub.jsx →
  // BroadsheetSlot, or iosAppBroadsheetMain.jsx → BroadsheetApp), HOISTED
  // ABOVE the stage switch so radio state survives logout → re-login.
  // Without that hoisting, BSRadioProvider would remount on login and fire
  // its 600ms auto-prompt — making Home flash before the overlay.
  return (
    <BSSheetProvider>
      {/* Gesture layer mounts HERE (never early-returns), so edge-swipe back
          keeps working while a takeover has replaced the Inner's main render. */}
      {typeof window !== 'undefined' && window.BSNavGestures ? React.createElement(window.BSNavGestures) : null}
      <BSClientAppInner onLogout={onLogout} tweaks={tweaks} setTweak={setTweak} initialTab={initialTab} />
    </BSSheetProvider>
  );
}

// ═══════════════════════════════════════════════════════════
// HOME CARDS — customizable stack (pin / customize / remove / add)
// ═══════════════════════════════════════════════════════════
// One component, many card types, each speaking the same one-statement
// language: KICKER · HERO · meta · caption. Pin (⌃) locks a card to the top
// with its accent outline; unpinned cards auto-order by "most alive today"
// (a per-card aliveness score from live signals). Customize (⋯) swaps a slot's
// focus; Remove (×) drops it; + Add a card appends one. Layout persists to
// client_ui_prefs so it syncs across devices.

const BS_CARD_TYPES = ['training', 'recovery', 'energy', 'consistency', 'protein', 'mood'];
const BS_CARD_LABEL = { training: 'Training', recovery: 'Recovery', energy: 'Energy', consistency: 'Consistency', protein: 'Protein', mood: 'Mood' };
const BS_CARD_DEFAULTS = ['training', 'recovery', 'energy'];

// Build a card's display model from live signals (ticker + analytics + energy).
// Returns { kicker, hero, sub, caption, accent, alive } — `alive` (0..100) is
// the "most alive today" score used to auto-order unpinned cards.
function _bsBuildCard(type, ctx) {
  const { t, ticker, analytics, energy, energyAccent } = ctx;
  const tk = ticker || {};
  const k = analytics && analytics.kpis ? analytics.kpis : {};
  const dash = '—';
  switch (type) {
    case 'training': {
      const wk = analytics && typeof analytics.workouts_this_week === 'number' ? analytics.workouts_this_week : null;
      const adher = typeof k.workout_adherence_pct === 'number' ? k.workout_adherence_pct : null;
      const dist = typeof tk.today_distance_km === 'number' ? tk.today_distance_km : null;
      const mins = typeof tk.today_activity_min === 'number' ? tk.today_activity_min : null;
      const actType = tk.today_activity_type || null;
      const cap = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
      // Today's real activity leads (miles or minutes); else workouts this week.
      if (dist != null && dist > 0) {
        const mi = Math.round((dist / 1.609) * 10) / 10;
        return {
          accent: t.AMBER, kicker: 'Training', hero: String(mi), heroUnit: `mi · ${cap(actType) || 'logged'}`,
          sub: [cap(actType) || 'Activity', mins ? `${mins} min` : 'today', wk != null ? `${wk} this wk` : 'logged'],
          caption: 'Distance in the bank today. Nice work.',
          alive: 85,
        };
      }
      if (mins != null && mins > 0) {
        return {
          accent: t.AMBER, kicker: 'Training', hero: String(mins), heroUnit: `min · ${cap(actType) || 'trained'}`,
          sub: [cap(actType) || 'Trained', 'today', wk != null ? `${wk} this wk` : 'logged'],
          caption: 'Session logged today. Stay on the program.',
          alive: 82,
        };
      }
      const has = wk != null;
      return {
        accent: t.AMBER,
        kicker: 'Training',
        hero: has ? String(wk) : dash,
        heroUnit: has ? (wk === 1 ? 'workout this wk' : 'workouts this wk') : 'this week',
        sub: ['This week', adher != null ? `${adher}% adherence` : 'log a workout', 'keep moving'],
        caption: has && wk > 0 ? 'Sessions in the bank. Get today in too.' : 'Nothing logged yet — get one in today.',
        alive: has && wk > 0 ? 60 : 38,
      };
    }
    case 'recovery': {
      const sleep = typeof tk.sleep_hours === 'number' ? tk.sleep_hours : null;
      const hrv = typeof tk.hrv_ms === 'number' ? tk.hrv_ms : null;
      const rec = typeof tk.recovery_score === 'number' ? tk.recovery_score : null;
      // Prefer a real recovery score; fall back to a sleep heuristic.
      const ready = rec != null ? rec >= 66 : (sleep == null ? null : sleep >= 7);
      const mid = rec != null && rec >= 40 && rec < 66;
      const sleepLabel = sleep != null ? `${Math.floor(sleep)}h ${Math.round((sleep % 1) * 60)}m` : dash;
      const heroWord = (rec == null && sleep == null) ? dash : (ready ? 'Ready' : mid ? 'Steady' : 'Low');
      return {
        accent: t.BLUE,
        kicker: 'Recovery',
        hero: heroWord,
        heroUnit: rec != null ? `${Math.round(rec)}%` : '',
        sub: ['Sleep', sleepLabel, hrv != null ? `HRV ${Math.round(hrv)}` : 'HRV —'],
        caption: (rec == null && sleep == null) ? 'Connect a wearable or log sleep to see readiness.'
          : ready ? "Recovered. Body's good to push tomorrow." : mid ? 'Middling — train, but listen to the body.' : 'Under-recovered — keep today easy.',
        // Poor recovery is highly "alive" — it should bubble up.
        alive: (rec == null && sleep == null) ? 30 : (ready ? 52 : mid ? 72 : 92),
      };
    }
    case 'energy': {
      return {
        accent: energyAccent || t.BLUE,
        kicker: energy ? energy.kicker.replace('Energy · ', 'Energy · ') : 'Energy',
        hero: energy ? energy.hero : dash,
        heroUnit: '',
        sub: energy ? energy.meta : ['Goal', dash, ''],
        caption: ctx.energyCaption || '',
        // Off-target energy is alive; on-target / empty is calmer.
        alive: ctx.noLiveToday ? 40 : 60,
      };
    }
    case 'consistency': {
      const pts = typeof k.weekly_points === 'number' ? k.weekly_points : null;
      const has = pts != null;
      return {
        accent: t.GREEN,
        kicker: 'Consistency',
        hero: has ? `+${pts}` : dash,
        heroUnit: has ? 'pts this wk' : 'this week',
        sub: ['Shape Score', has ? 'this week' : 'log to earn', 'streaks compound'],
        caption: has && pts > 0 ? 'Showing up. Every log adds to the score.' : 'Log a habit or workout to start the week.',
        alive: has && pts > 0 ? 50 : 25,
      };
    }
    case 'protein': {
      const p = typeof tk.protein_g === 'number' ? tk.protein_g : null;
      const target = typeof tk.protein_target === 'number' ? tk.protein_target : 150;
      const has = p != null;
      const pct = has ? Math.round((p / target) * 100) : null;
      const hit = has && p >= target * 0.9;
      return {
        accent: t.RUST,
        kicker: 'Protein',
        hero: has ? String(p) : dash,
        heroUnit: has ? `/ ${target} g` : 'g today',
        sub: ['Today', has ? `${pct}% of target` : 'not logged', 'muscle fuel'],
        caption: !has ? 'Log meals to track protein.' : hit ? 'On target — protein locked in.' : `Behind on protein — ${target - p}g to go.`,
        alive: !has ? 35 : (hit ? 45 : 75),
      };
    }
    case 'mood': {
      const m = typeof tk.mood === 'number' ? tk.mood : null;
      const word = m == null ? dash : m >= 8 ? 'Great' : m >= 6 ? 'Good' : m >= 4 ? 'Okay' : 'Low';
      return {
        accent: t.ACCENT,
        kicker: 'Mood',
        hero: word,
        heroUnit: m != null ? `${m}/10` : 'check in',
        sub: ['Today', m != null ? 'logged' : 'tap to log', '1–10'],
        caption: m == null ? 'How are you feeling? A quick check-in keeps your coach in the loop.'
          : m >= 6 ? 'Feeling good today — keep the momentum.' : 'Off day — be kind to yourself, log a note.',
        // Unlogged or low mood is more "alive" (worth surfacing).
        alive: m == null ? 30 : (m < 4 ? 80 : 22),
      };
    }
    default:
      return { accent: t.INK, kicker: BS_CARD_LABEL[type] || type, hero: dash, heroUnit: '', sub: [], caption: '', alive: 0 };
  }
}

function BSHomeCardItem({ slot, model, t, pinned, onPin, onRemove, onOpen, draggable, dragHandlers, dragging, dragOver }) {
  const tr = useShapeTr();
  const acc = model.accent;
  const _clip = (n) => `polygon(0 0, calc(100% - ${n}px) 0, 100% ${n}px, 100% 100%, 0 100%)`;
  return (
    <div
      draggable={draggable}
      {...(dragHandlers || {})}
      style={{
        position: 'relative', margin: `0 ${t.padX}px 6px`,
        opacity: dragging ? 0.5 : 1,
        transition: 'opacity 0.15s ease',
      }}>
      {/* Instrument plate chrome — pinned cards get the full-strength frame. */}
      <div aria-hidden style={{ position: 'absolute', inset: 0, clipPath: _clip(10), background: pinned ? acc : `${acc}55` }} />
      <div aria-hidden style={{ position: 'absolute', inset: 1.25, clipPath: _clip(9), background: `linear-gradient(165deg, ${acc}14, ${acc}05 45%, ${t.PAPER2} 90%), ${t.PAPER}` }} />
      <div aria-hidden style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 2.5, background: acc }} />
      {dragOver && <div aria-hidden style={{ position: 'absolute', inset: -2.5, border: `1.5px dashed ${acc}`, borderRadius: 7, pointerEvents: 'none' }} />}
      <div style={{ position: 'relative' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '7px 12px 0 14px' }}>
        <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: model.accent, display: 'inline-flex', alignItems: 'center', gap: 8 }}>
          {draggable && <span title={tr('home:cards.dragToReorder', { defaultValue: 'Drag to reorder' })} style={{ cursor: 'grab', color: t.INK50, fontSize: 12, letterSpacing: 0 }}>⠿</span>}
          {model.kicker}{pinned ? ` · ${tr('home:cards.pinned', { defaultValue: 'pinned' })}` : ''}
        </span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <button onClick={onPin} title={pinned ? tr('home:cards.unpin', { defaultValue: 'Unpin' }) : tr('home:cards.pinToTop', { defaultValue: 'Pin to top' })} style={_bsCardBtn(t, pinned ? model.accent : t.INK50)}>⌃</button>
          <button onClick={onRemove} title={tr('home:cards.hide', { defaultValue: 'Hide' })} style={_bsCardBtn(t, t.INK50)}>×</button>
        </div>
      </div>
      <button onClick={onOpen} style={{ width: '100%', textAlign: 'left', background: 'transparent', border: 0, cursor: onOpen ? 'pointer' : 'default', padding: '1px 12px 9px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 7, flexWrap: 'wrap' }}>
          <span style={{ fontFamily: t.DISPLAY, fontWeight: t.W.display, fontSize: 22, lineHeight: 0.92, letterSpacing: '-0.04em', color: t.INK }}>{model.hero}</span>
          {model.heroUnit ? <span style={{ fontFamily: t.MONO, fontSize: 9.5, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{model.heroUnit}</span> : null}
        </div>
        {model.sub && model.sub.length > 0 && (
          <div style={{ marginTop: 4, display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap', fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>
            {model.sub.filter(Boolean).map((s, i) => (
              <React.Fragment key={i}>
                {i > 0 && <span style={{ opacity: 0.5 }}>·</span>}
                <span>{s}</span>
              </React.Fragment>
            ))}
          </div>
        )}
        {model.caption ? <div style={{ marginTop: 5, fontFamily: t.DISPLAY, fontSize: 12.5, fontWeight: 500, color: t.INK70, letterSpacing: '-0.01em', lineHeight: 1.3, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{model.caption}</div> : null}
      </button>
      </div>
    </div>
  );
}
function _bsCardBtn(t, color) {
  return { width: 26, height: 26, borderRadius: 7, border: 0, background: 'transparent', color, fontFamily: t.MONO, fontSize: 13, fontWeight: 800, lineHeight: 1, cursor: 'pointer', padding: 0 };
}

// The stack: header, ordered cards, + Add, footer note. Layout {order[], pinned[]}
// persists to client_ui_prefs. onOpenEnergy etc. let cards deep-link.
function BSHomeCards({ t, todayLabel, ctx, openers = {} }) {
  const tr = useShapeTr();
  // Localized card label — the registry (BS_CARD_LABEL) is the English default.
  const cardLabel = (type) => tr(`home:card.${type}`, { defaultValue: BS_CARD_LABEL[type] || type });
  // manual: once the user drags, we respect their explicit order (and stop
  // auto-sorting by aliveness) so a deliberate arrangement sticks.
  const defaultLayout = { order: BS_CARD_DEFAULTS.slice(), pinned: [], manual: false, hidden: false };
  // Synchronous localStorage mirror so a removed/reordered card sticks across
  // remounts (tab switches) even when signed-out / the backend no-ops.
  const LS_CARDS = 'bs_home_cards';
  const readCardsLS = () => {
    try {
      const v = JSON.parse(window.localStorage.getItem(LS_CARDS) || 'null');
      if (v && Array.isArray(v.order)) {
        const order = v.order.filter(x => BS_CARD_TYPES.includes(x));
        return { order, pinned: Array.isArray(v.pinned) ? v.pinned.filter(x => order.includes(x)) : [], manual: !!v.manual, hidden: !!v.hidden };
      }
    } catch (e) {}
    return null;
  };
  const [layout, setLayout] = useStateBSC(() => readCardsLS() || defaultLayout);
  const [menuOpen, setMenuOpen] = useStateBSC(false);
  const [menuPos, setMenuPos] = useStateBSC(null);
  const [dragType, setDragType] = useStateBSC(null);
  const [overType, setOverType] = useStateBSC(null);
  const cardsBtnRef = React.useRef(null);
  const cardsMenuRef = React.useRef(null);
  const openCardsMenu = () => {
    const el = cardsBtnRef.current;
    if (el && el.getBoundingClientRect) {
      const r = el.getBoundingClientRect();
      // Position relative to the phone surface so the menu stays inside the
      // frame in desktop preview (a fixed/viewport menu overhangs the chrome).
      const surf = document.getElementById('bs-phone-surface');
      const sr = surf ? surf.getBoundingClientRect() : { top: 0, right: window.innerWidth, bottom: window.innerHeight };
      const top = r.bottom - sr.top + 6;
      const right = Math.max(8, sr.right - r.right);
      const maxH = Math.max(140, sr.bottom - r.bottom - 84); // clear the footer nav
      setMenuPos({ top, right, maxH });
    }
    setMenuOpen(true);
  };
  // While the menu is open, any scroll closes it — a fixed-position menu would
  // otherwise detach from the button, and the page would feel "stuck".
  React.useEffect(() => {
    if (!menuOpen) return undefined;
    // Close on PAGE scroll (the absolute menu would detach from the button), but
    // NOT when scrolling inside the menu itself.
    const close = (e) => { const m = cardsMenuRef.current; if (m && e && e.target && m.contains(e.target)) return; setMenuOpen(false); };
    window.addEventListener('scroll', close, true);
    window.addEventListener('wheel', close, { passive: true });
    window.addEventListener('touchmove', close, { passive: true });
    return () => {
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('wheel', close);
      window.removeEventListener('touchmove', close);
    };
  }, [menuOpen]);

  // Load saved layout (best-effort); persist on change.
  React.useEffect(() => {
    let cancelled = false;
    if (!(window.shapeDb && window.shapeDb.getUserGoals)) return undefined;
    window.shapeDb.getUserGoals('client_home_cards').then((saved) => {
      if (cancelled || !saved || !Array.isArray(saved.order)) return;
      const order = saved.order.filter(x => BS_CARD_TYPES.includes(x));
      const pinned = Array.isArray(saved.pinned) ? saved.pinned.filter(x => order.includes(x)) : [];
      setLayout({ order, pinned, manual: !!saved.manual, hidden: !!saved.hidden });
    }).catch(() => {});
    return () => { cancelled = true; };
  }, []);
  const persist = (next) => {
    setLayout(next);
    try { window.localStorage.setItem(LS_CARDS, JSON.stringify(next)); } catch (e) {}
    try { window.shapeDb && window.shapeDb.saveUserGoals && window.shapeDb.saveUserGoals('client_home_cards', next); } catch (e) {}
  };
  // Whole-section visibility — toggled from this section (Cards ▾ menu → Hide;
  // a slim restore chip brings it back). Persisted in the same doc.
  const setSectionHidden = (v) => { persist({ ...layout, hidden: !!v }); setMenuOpen(false); };

  // Build models, then order: pinned first (in pin order), then unpinned —
  // either the user's manual order, or auto by aliveness desc (stable on ties).
  const models = {};
  layout.order.forEach(type => { models[type] = _bsBuildCard(type, ctx); });
  const pinnedOrder = layout.pinned.filter(x => layout.order.includes(x));
  const unpinned = layout.order.filter(x => !layout.pinned.includes(x));
  if (!layout.manual) {
    unpinned.sort((a, b) => (models[b].alive - models[a].alive) || (layout.order.indexOf(a) - layout.order.indexOf(b)));
  }
  const ordered = [...pinnedOrder, ...unpinned];

  // Drag-to-reorder: dropping b before/after a rewrites `order` and locks it
  // to manual so the deliberate arrangement sticks.
  const onDrop = (target) => {
    if (!dragType || dragType === target) { setDragType(null); setOverType(null); return; }
    const next = layout.order.filter(x => x !== dragType);
    const idx = next.indexOf(target);
    next.splice(idx < 0 ? next.length : idx, 0, dragType);
    persist({ ...layout, order: next, manual: true });
    setDragType(null); setOverType(null);
  };
  const dragHandlersFor = (type) => ({
    onDragStart: () => setDragType(type),
    onDragEnd: () => { setDragType(null); setOverType(null); },
    onDragOver: (e) => { e.preventDefault(); if (overType !== type) setOverType(type); },
    onDrop: (e) => { e.preventDefault(); onDrop(type); },
  });

  const togglePin = (type) => {
    const pinned = layout.pinned.includes(type) ? layout.pinned.filter(x => x !== type) : [...layout.pinned, type];
    persist({ ...layout, pinned });
  };
  const hideCard = (type) => {
    persist({ ...layout, order: layout.order.filter(x => x !== type), pinned: layout.pinned.filter(x => x !== type) });
  };
  // Dropdown toggles which cards are visible on the home. Keeps BS_CARD_TYPES
  // order when re-adding so the stack stays stable.
  const toggleVisible = (type) => {
    if (layout.order.includes(type)) { hideCard(type); return; }
    const order = BS_CARD_TYPES.filter(x => layout.order.includes(x) || x === type);
    persist({ ...layout, order });
  };

  // Collapsed — the section is hidden from home; show a slim restore chip so
  // it can be brought back without leaving the home page.
  if (layout.hidden) {
    return (
      <div style={{ padding: `2px ${t.padX}px 6px` }}>
        <button onClick={() => setSectionHidden(false)} style={{
          display: 'inline-flex', alignItems: 'center', gap: 6,
          padding: '7px 13px', borderRadius: 4, border: `1px dashed ${t.RULE}`, background: 'transparent',
          color: t.INK50, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase',
        }}>▸ {tr('home:cards.showHomeCards', { defaultValue: 'Show home cards' })}</button>
      </div>
    );
  }

  return (
    <>
      <div style={{ padding: `2px ${t.padX}px 8px`, display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 12 }}>
        <div>
          <div style={{ fontFamily: t.DISPLAY, fontWeight: t.W.display, fontSize: 24, letterSpacing: '-0.03em', color: t.INK, lineHeight: 1 }}>{todayLabel}.</div>
          <div style={{ marginTop: 4, fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{tr('home:cards.stackSub', { defaultValue: 'Your stack · pin or choose cards' })}</div>
        </div>
        {/* Compact dropdown to choose which cards are visible */}
        <div>
          <button ref={cardsBtnRef} onClick={() => (menuOpen ? setMenuOpen(false) : openCardsMenu())} style={{
            padding: '8px 12px', borderRadius: 4, border: `1px solid ${t.ACCENT}66`, borderLeft: `3px solid ${t.ACCENT}`, background: menuOpen ? `${t.ACCENT}33` : `${t.ACCENT}14`,
            color: t.INK, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', cursor: 'pointer', whiteSpace: 'nowrap',
          }}>{tr('home:cards.cardsMenu', { defaultValue: 'Cards ▾' })}</button>
          {menuOpen && menuPos && createPortal(
            <>
              <div onClick={() => setMenuOpen(false)} style={{ position: 'absolute', inset: 0, zIndex: 9998 }} />
              <div ref={cardsMenuRef} className="bs-scroll" style={{
                position: 'absolute', top: menuPos.top, right: menuPos.right, zIndex: 9999, width: 210,
                maxHeight: menuPos.maxH, overflowY: 'auto',
                background: t.PAPER, border: `1px solid ${t.INK}`, borderRadius: 12,
                boxShadow: '0 16px 40px rgba(0,0,0,0.3)',
              }}>
                <div style={{ padding: '10px 12px', borderBottom: `1px solid ${t.RULE}`, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.18em', textTransform: 'uppercase', color: t.INK50, fontWeight: 700 }}>{tr('home:cards.showOnHome', { defaultValue: 'Show on home' })}</div>
                {BS_CARD_TYPES.map((type) => {
                  const on = layout.order.includes(type);
                  const m = models[type] || _bsBuildCard(type, ctx);
                  return (
                    <button key={type} onClick={() => toggleVisible(type)} style={{
                      width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10,
                      padding: '11px 12px', border: 0, borderTop: `1px solid ${t.HAIR}`, background: 'transparent', cursor: 'pointer', textAlign: 'left',
                    }}>
                      <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={{ width: 8, height: 8, borderRadius: 2, background: m.accent }} />
                        <span style={{ fontFamily: t.DISPLAY, fontSize: 14, fontWeight: 600, color: t.INK }}>{cardLabel(type)}</span>
                      </span>
                      <span style={{
                        width: 34, height: 20, borderRadius: 999, padding: 2, flexShrink: 0,
                        border: `1px solid ${on ? m.accent : t.RULE}`, background: on ? m.accent : 'transparent',
                        display: 'flex', alignItems: 'center', justifyContent: on ? 'flex-end' : 'flex-start',
                      }}>
                        <span style={{ width: 14, height: 14, borderRadius: 999, background: on ? t.PAPER : t.INK50, display: 'block' }} />
                      </span>
                    </button>
                  );
                })}
                <button onClick={() => setSectionHidden(true)} style={{
                  width: '100%', padding: '11px 12px', border: 0, borderTop: `1px solid ${t.RULE}`, background: 'transparent', cursor: 'pointer', textAlign: 'left',
                  fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.INK50,
                }}>✕ {tr('home:cards.hideSection', { defaultValue: 'Hide section from home' })}</button>
              </div>
            </>,
            document.getElementById('bs-phone-surface') || document.body
          )}
        </div>
      </div>

      {ordered.length === 0 && (
        <div style={{ margin: `0 ${t.padX}px 12px`, padding: '18px 16px', borderRadius: 5, border: `1px dashed ${t.RULE}`, borderLeft: `3px solid ${t.RULE}`, fontFamily: t.DISPLAY, fontSize: 14, color: t.INK50, lineHeight: 1.4 }}>
          {tr('home:cards.emptyPre', { defaultValue: 'No cards on your home. Tap' })} <span style={{ fontWeight: 700, color: t.INK70 }}>{tr('home:cards.cardsMenu', { defaultValue: 'Cards ▾' })}</span> {tr('home:cards.emptyPost', { defaultValue: 'to choose what to show.' })}
        </div>
      )}

      {ordered.map((type) => {
        const isPinned = layout.pinned.includes(type);
        return (
          <BSHomeCardItem
            key={type}
            slot={type}
            model={models[type]}
            t={t}
            pinned={isPinned}
            onPin={() => togglePin(type)}
            onRemove={() => hideCard(type)}
            onOpen={openers[type]}
            draggable={!isPinned}
            dragHandlers={!isPinned ? dragHandlersFor(type) : null}
            dragging={dragType === type}
            dragOver={overType === type && dragType && dragType !== type}
          />
        );
      })}
    </>
  );
}

// ═══════════════════════════════════════════════════════════
// HOME — "The Shape Daily" front page
// ═══════════════════════════════════════════════════════════
// Home ticker metrics — keys match the labels built in BSClientHome; the
// Settings editor toggles/reorders these (saved to user_goals 'client_ticker').
const BS_TICKER_METRICS = [
  { key: 'CAL', name: 'Calories' },
  { key: 'PRO', name: 'Protein' },
  { key: 'HAB', name: 'Habits' },
  { key: 'SLP', name: 'Sleep' },
  { key: 'HRV', name: 'HRV' },
  { key: 'RHR', name: 'Resting HR' },
  { key: 'WGT', name: 'Weight' },
];

// Full read-only preview of an upcoming workout — opened from the home
// "Up next" workout card's Preview button.
// Program week — weeks since a fixed program start, so page eyebrows ("Week 6")
// advance over real time. Shared by the Eat / Train / home headers.
function bsProgramWeek() {
  const start = new Date(2026, 3, 6); // Apr 6 2026 — program start (mock anchor)
  const w = Math.floor((Date.now() - start.getTime()) / 6048e5) + 1;
  return Math.min(52, Math.max(1, w));
}
// Program phase per client — training block + nutrition phase, shown in the
// Eat / Train / home eyebrows. Cached on window so headers read it synchronously;
// persisted in client_settings (Settings → Preferences), so a coach-set value
// from the same store flows through here too.
if (typeof window !== 'undefined' && !window.ShapeProgram) {
  let _prog = { trainingPhase: 'Build', nutritionPhase: 'Cut', detail: {} };
  window.ShapeProgram = {
    get: () => _prog,
    set: (p) => { if (p && typeof p === 'object') { _prog = { ..._prog, ...p, detail: { ...(_prog.detail || {}), ...(p.detail || {}) } }; try { window.dispatchEvent(new Event('bs-program')); } catch (e) {} } },
  };
}
function useBSProgram() {
  const [p, setP] = useStateBSC(() => (window.ShapeProgram?.get?.() || { trainingPhase: 'Build', nutritionPhase: 'Cut', detail: {} }));
  React.useEffect(() => {
    let alive = true;
    // Prefer the real per-client store (coach-writable); fall back to the
    // self-only client_settings mirror for older data / offline.
    const hydrate = (next) => { if (alive && next && (next.trainingPhase || next.nutritionPhase || next.detail)) { window.ShapeProgram?.set?.(next); setP({ ...(window.ShapeProgram?.get?.() || {}) }); } };
    if (window.ShapeProgramApi?.get) {
      window.ShapeProgramApi.get().then(hydrate).catch(() => {});
    }
    if (window.shapeDb?.getUserGoals) {
      window.shapeDb.getUserGoals('client_settings').then(s => {
        if (!s || typeof s !== 'object') return;
        hydrate({ trainingPhase: s.trainingPhase, nutritionPhase: s.nutritionPhase });
      }).catch(() => {});
    }
    const onEvt = () => setP({ ...(window.ShapeProgram?.get?.() || {}) });
    window.addEventListener('bs-program', onEvt);
    return () => { alive = false; window.removeEventListener('bs-program', onEvt); };
  }, []);
  return p;
}

// Coach-set program/plan adjustment, surfaced to the client on Train (training)
// and Eat (nutrition). Driven by client_programs.detail (coach-writable), so it
// only appears once a coach has pressed Apply on their Adjust page.
function BSCoachAdjustBanner({ detail, kind }) {
  const t = useBS();
  const d = kind === 'nutrition' ? detail?.nutrition : detail?.training;
  if (!d || !d.updatedAt) return null;
  let when = '';
  try { when = new Date(d.updatedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }); } catch (e) {}
  const cap = (s) => (typeof s === 'string' && s ? s[0].toUpperCase() + s.slice(1) : s);
  const chips = (kind === 'nutrition'
    ? [d.calories != null ? `${d.calories} kcal` : null, d.protein != null ? `${d.protein}P` : null, d.carbs != null ? `${d.carbs}C` : null, d.fat != null ? `${d.fat}F` : null, d.meals != null ? `${d.meals} meals` : null]
    : [d.intensity ? ({ deload: 'Deload', maintain: 'Maintain', progress: 'Progress' }[d.intensity] || cap(d.intensity)) : null, d.sessions != null ? `${d.sessions}×/week` : null, ...(Array.isArray(d.focus) ? d.focus.slice(0, 2).map(cap) : [])]
  ).filter(Boolean);
  const roleC = kind === 'nutrition' ? '#a07a2e' : '#c0533b';
  return (
    <div style={{ margin: `12px ${t.padX}px 0`, borderLeft: `3px solid ${roleC}`, padding: '2px 0 2px 10px' }}>
      <span style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.16em', color: roleC, textTransform: 'uppercase' }}>From your coach{when ? ` · ${when}` : ''}</span>
      <div style={{ marginTop: 7, display: 'flex', flexWrap: 'wrap', gap: 6 }}>
        {chips.map((c, i) => <span key={i} style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.06em', color: t.INK, border: `1px solid ${t.RULE}`, borderRadius: 3, padding: '4px 9px' }}>{c}</span>)}
      </div>
      {d.note ? <div style={{ marginTop: 8, fontFamily: t.DISPLAY, fontSize: 13.5, fontStyle: 'italic', color: t.INK70, lineHeight: 1.45 }}>“{d.note}”</div> : null}
    </div>
  );
}

// Live "online now" count via Supabase Realtime presence (hook below).
function useBSOnline() {
  const [n, setN] = useStateBSC(() => (window.ShapePresence?.count?.() || 0));
  React.useEffect(() => {
    if (!window.ShapePresence) return undefined;
    window.ShapePresence.start?.();
    setN(window.ShapePresence.count?.() || 0);
    return window.ShapePresence.onChange?.((c) => setN(c)) || undefined;
  }, []);
  return n;
}

// Shape membership status (drives the member-gated Shape Store + its Me-row
// hint). `allowed` = an active subscription OR a coach account (providers).
// Result cached on window.ShapeMembership so repeat reads don't re-fetch/flash.
function useBSMembership() {
  const initial = () => {
    const auth = window.ShapeAuth?.getCachedState?.() || {};
    const role = auth.profile?.role;
    const isCoach = role === 'trainer' || role === 'nutritionist';
    const signedIn = !!auth.user?.id;
    if (!signedIn) return { loading: false, allowed: false, signedIn: false };
    if (isCoach) return { loading: false, allowed: true, signedIn: true };
    if (window.ShapeMembership && typeof window.ShapeMembership.active === 'boolean') return { loading: false, allowed: window.ShapeMembership.active, signedIn: true };
    return { loading: true, allowed: false, signedIn: true };
  };
  const [m, setM] = useStateBSC(initial);
  React.useEffect(() => {
    if (!m.loading) return undefined;
    let cancelled = false;
    fetch('/api/stripe/subscription', { credentials: 'same-origin', cache: 'no-store' })
      .then(r => (r.ok ? r.json() : null))
      .then(d => { const active = !!(d && d.active === true); try { window.ShapeMembership = { active }; } catch (e) {} if (!cancelled) setM({ loading: false, allowed: active, signedIn: true }); })
      .catch(() => { if (!cancelled) setM({ loading: false, allowed: false, signedIn: true }); });
    return () => { cancelled = true; };
  }, []);
  return m;
}

// ── THE CYCLE — shared member settings state (spec 2026-07-19) ───────────────
// ONE resolved truth for every cycle consumer (Settings pane · calendar page ·
// Today chip · Progress card · the neutral Home lever): fetched once, cached on
// window.ShapeCycleState, and re-broadcast on 'shape:cycleSettings' after any
// write so every mounted consumer flips together. Signed-out, pre-migration,
// and never-opted-in all resolve to { optIn:false, share:false } — absence,
// never a fabricated opt-in (the doctrine's absence-not-a-padlock rule starts
// here: a member who never opted in has NO cycle surfaces at all).
// ⚠ Both cycle caches are keyed by the AUTH USER ID (review: Codex P1). A
// logout→login without a full reload leaves the window globals in place, so an
// unscoped cache let the NEXT account inherit the previous member's opt-in /
// share state — and briefly her period dates through ShapeCycleDerived. That is
// the most sensitive data in the app leaking across accounts, the same class as
// the _followCache/_avatarCache leak fixed 2026-06-29. A cache whose uid does
// not match the CURRENT uid is treated as absent, so the new account always
// re-reads its own state; signed-out (uid null) is a distinct key, never a
// wildcard that matches a signed-in cache.
function bsCycleUid() {
  try { return (window.ShapeAuth?.getCachedState?.()?.user?.id) || null; } catch (e) { return null; }
}
function bsCycleStatePut(next, uid) {
  const clean = { uid: uid === undefined ? bsCycleUid() : uid, optIn: next?.optIn === true, share: next?.share === true };
  try { window.ShapeCycleState = clean; } catch (e) {}
  try { window.dispatchEvent(new CustomEvent('shape:cycleSettings', { detail: clean })); } catch (e) {}
  return clean;
}
function useBSCycleSettings() {
  const uid = bsCycleUid();
  const [s, setS] = useStateBSC(() => {
    const cached = (typeof window !== 'undefined' && window.ShapeCycleState) || null;
    return (cached && cached.uid === uid) ? { ...cached, loading: false } : { loading: true, optIn: false, share: false, uid };
  });
  // Account switch mid-session: drop straight back to loading so the previous
  // member's state can never render for even one frame.
  React.useEffect(() => {
    if (s.uid !== uid) setS({ loading: true, optIn: false, share: false, uid });
  }, [uid, s.uid]);
  // Sync every mounted consumer on a write from any other surface — but only
  // when the write belongs to the account this hook is rendering for.
  React.useEffect(() => {
    const onChange = (e) => {
      const d = (e && e.detail) || (typeof window !== 'undefined' ? window.ShapeCycleState : null);
      if (d && d.uid === uid) setS({ optIn: d.optIn === true, share: d.share === true, loading: false, uid });
    };
    window.addEventListener('shape:cycleSettings', onChange);
    return () => window.removeEventListener('shape:cycleSettings', onChange);
  }, [uid]);
  React.useEffect(() => {
    if (!s.loading) return undefined;
    let cancelled = false;
    (async () => {
      let next = { optIn: false, share: false };
      try {
        const r = await window.ShapeCycle?.settings?.();
        if (r && typeof r === 'object') next = { optIn: r.optIn === true, share: r.share === true };
      } catch (e) { /* absent doc / pre-migration → the false/false default */ }
      // The account can change WHILE this read is in flight (logout mid-fetch):
      // a response resolved for the previous uid must never be cached or
      // rendered under the new one.
      if (cancelled || bsCycleUid() !== uid) return;
      bsCycleStatePut(next, uid);
      setS({ ...next, loading: false, uid });
    })();
    return () => { cancelled = true; };
  }, [s.loading, uid]);
  return s;
}

// One reader for the phase words and the surface heat (review: CodeRabbit) —
// the calendar page and the Progress card had hand-copied maps, so a fifth
// phase or a key rename meant editing them in lockstep.
function bsCyclePhaseLabel(tr, phase) {
  return {
    menstrual: tr('cycle:phase.menstrual', { defaultValue: 'Menstrual' }),
    follicular: tr('cycle:phase.follicular', { defaultValue: 'Follicular' }),
    ovulatory: tr('cycle:phase.ovulatory', { defaultValue: 'Ovulatory' }),
    luteal: tr('cycle:phase.luteal', { defaultValue: 'Luteal' }),
  }[phase] || '';
}
function bsCycleHeat(t) {
  return (typeof bsMyTierColor === 'function' && bsMyTierColor()) || (t.isLight ? '#0a8f87' : '#34d6c5');
}

// The not-medical-advice disclaimer is legally material and VERBATIM (spec
// doctrine). One reader, so the string a member consents to is byte-identical
// to the string she was shown — the consent receipt records exactly this, in
// her own language.
function bsCycleDisclaimer(tr) {
  return tr('cycle:disclaimer', { defaultValue: 'The Cycle is for training and recovery context only. It is not medical advice, not a diagnostic tool, and must never be used for contraception or fertility planning. Predictions are estimates from the dates you log.' });
}

// ── Client Library — saved coach content (workouts, programs, meals) ─────────
// Persists to localStorage immediately, mirrored to window.shapeDb (user_goals)
// for cross-device sync. Screens subscribe via the `bs-library` window event.
const BS_LIB_KEY = 'shape.library';
function bsLibRead() {
  try { const raw = window.localStorage && window.localStorage.getItem(BS_LIB_KEY); const a = raw ? JSON.parse(raw) : []; return Array.isArray(a) ? a : []; } catch (e) { return []; }
}
function bsLibWrite(items) {
  try { window.localStorage && window.localStorage.setItem(BS_LIB_KEY, JSON.stringify(items)); } catch (e) {}
  try { window.shapeDb && window.shapeDb.saveUserGoals && window.shapeDb.saveUserGoals('client_library', items); } catch (e) {}
  try { window.dispatchEvent(new Event('bs-library')); } catch (e) {}
}
function bsLibToggle(item) {
  const items = bsLibRead();
  const exists = items.some(x => x.id === item.id);
  const next = exists ? items.filter(x => x.id !== item.id) : [{ ...item, savedAt: Date.now() }, ...items];
  bsLibWrite(next);
  window.__bsToast && window.__bsToast(exists ? 'Removed from library' : 'Saved to your library', exists ? 'info' : 'ok');
  return !exists;
}
function useBSLibrary() {
  const [items, setItems] = useStateBSC(() => bsLibRead());
  React.useEffect(() => {
    const sync = () => setItems(bsLibRead());
    window.addEventListener('bs-library', sync);
    // One-time merge with any cloud-saved library (union by id; never drop a save).
    try {
      window.shapeDb && window.shapeDb.getUserGoals && window.shapeDb.getUserGoals('client_library').then((saved) => {
        if (!Array.isArray(saved) || !saved.length) return;
        const byId = new Map();
        for (const it of [...saved, ...bsLibRead()]) if (it && it.id && !byId.has(it.id)) byId.set(it.id, it);
        const merged = [...byId.values()].sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
        try { window.localStorage && window.localStorage.setItem(BS_LIB_KEY, JSON.stringify(merged)); } catch (e) {}
        setItems(merged);
      }).catch(() => {});
    } catch (e) {}
    // Plans you BOUGHT from a coach land in your Library automatically (owned).
    try {
      if (window.ShapeCoachPlans && window.ShapeCoachPlans.purchased) {
        window.ShapeCoachPlans.purchased().then((plans) => {
          if (!Array.isArray(plans) || !plans.length) return;
          const owned = plans.map((p) => ({ id: 'plan-' + p.id, kind: 'plan', title: p.name, meta: p.meta || 'Purchased plan', owned: true, planId: p.id, planKind: p.kind, detail: p.detail || {}, savedAt: p.purchasedAt ? new Date(p.purchasedAt).getTime() : Date.now() }));
          setItems((cur) => {
            const byId = new Map();
            for (const it of [...owned, ...cur]) if (it && it.id && !byId.has(it.id)) byId.set(it.id, it);
            return [...byId.values()].sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
          });
        }).catch(() => {});
      }
    } catch (e) {}
    return () => window.removeEventListener('bs-library', sync);
  }, []);
  return items;
}

// Reusable "Save to library" toggle — reflects saved state live.
function BSSaveButton({ item, full = false }) {
  const t = useBS();
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  const lib = useBSLibrary();
  const saved = lib.some(x => x.id === item.id);
  return (
    <button onClick={() => bsLibToggle(item)} style={{
      ...(full ? { flex: 1 } : {}), padding: '14px', borderRadius: 5, cursor: 'pointer',
      border: `1px solid ${saved ? teal : t.RULE}`,
      borderLeft: saved ? `3px solid ${teal}` : `1px solid ${t.RULE}`,
      background: saved ? (t.isLight ? `${teal}14` : `${teal}22`) : 'transparent',
      color: saved ? teal : t.INK,
      fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', whiteSpace: 'nowrap',
    }}>{saved ? '✓ Saved' : '♡ Save'}</button>
  );
}

// Client Library screen — saved workouts / programs / meals.
const BS_LIB_KINDS = {
  workout: { label: 'Workout', color: '#c0533b' },
  plan:    { label: 'Program', color: '#a07a2e' },
  meal:    { label: 'Meal',    color: '#5fae7e' },
  recipe:  { label: 'Recipe',  color: '#0a8f87' },
  grocery: { label: 'Groceries', color: '#3b74b8' },
};

function BSLibraryDetail({ item, onBack }) {
  const t = useBS();
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  const km = BS_LIB_KINDS[item.kind] || { label: item.kind || 'Saved', color: t.INK50 };
  const lib = useBSLibrary();
  const saved = lib.some(x => x.id === item.id);
  // A PURCHASED training plan can be scheduled onto the calendar (Start-this-plan).
  const canStart = !!(item.owned && item.kind === 'plan' && item.planKind !== 'meal_plan' && item.planId != null && window.ShapeSelfTraining?.startPurchasedPlan);
  const [startSheet, setStartSheet] = useStateBSC(false);
  // Default start = next Monday, as YYYY-MM-DD.
  const nextMonISO = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() + ((8 - ((d.getDay() + 6) % 7 + 1)) % 7 || 7)); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; })();
  const [startISO, setStartISO] = useStateBSC(nextMonISO);
  const [startWeeks, setStartWeeks] = useStateBSC(4);
  const [starting, setStarting] = useStateBSC(false);
  const [startErr, setStartErr] = useStateBSC('');
  const doStart = async () => {
    if (starting) return;
    setStarting(true); setStartErr('');
    try {
      await window.ShapeSelfTraining.startPurchasedPlan({ plan: { id: item.planId, name: item.title, detail: item.detail || {} }, startISO, weeks: startWeeks });
      window.__bsToast && window.__bsToast('On your Train tab', 'ok');
      setStartSheet(false); onBack();
    } catch (e) { setStartErr(String(e?.message || 'Could not start the plan.')); }
    setStarting(false);
  };
  return (
    <BSPage>
      <div style={{ padding: `14px ${t.padX}px 0` }}>
        {window.BSMastRow && <window.BSMastRow trailing={<BSMeCorner />} />}
        <div style={{ marginTop: 12 }}>
          <BSBackButton onClick={onBack} label="Library" />
        </div>
      </div>
      <div style={{ padding: `18px ${t.padX}px 0` }}>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
          <span style={{ width: 7, height: 7, borderRadius: 999, background: km.color }} />
          <span style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: km.color }}>{km.label}{item.price ? ` · ${item.price}` : ''}</span>
        </span>
        <h1 style={{ margin: '10px 0 0', fontFamily: t.DISPLAY, fontSize: 30, fontWeight: 700, lineHeight: 1.02, letterSpacing: '-0.03em', color: t.INK }}>{item.title}</h1>
        {(item.meta || item.coach) ? <div style={{ marginTop: 8, fontFamily: t.MONO, fontSize: 9.5, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{[item.meta, item.coach].filter(Boolean).join(' · ')}</div> : null}
      </div>
      <div style={{ padding: `18px ${t.padX}px 0` }}>
        <div style={{ borderLeft: `3px solid ${km.color}`, padding: '2px 0 2px 12px' }}>
          <div style={{ fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 15, color: t.INK, lineHeight: 1.5 }}>
            {item.preview || `Saved ${km.label.toLowerCase()} from your coach. Open it on its source page to start, swap, or log.`}
          </div>
        </div>
        {item.savedAt ? <div style={{ marginTop: 10, fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>Saved {new Date(item.savedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</div> : null}
      </div>
      {canStart && (
        <div style={{ padding: `16px ${t.padX}px 0` }}>
          <button onClick={() => setStartSheet(true)} style={{ width: '100%', padding: '15px', borderRadius: 6, clipPath: 'polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%)', border: 0, background: teal, color: t.isLight ? '#fff' : '#04201d', cursor: 'pointer', fontFamily: t.MONO, fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>Start this plan →</button>
          <div style={{ marginTop: 7, fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.06em', color: t.INK50 }}>Schedules the program onto your Train calendar as your own — edit any day.</div>
        </div>
      )}
      <div style={{ padding: `12px ${t.padX}px 0` }}>
        <button type="button" onClick={() => { bsLibToggle(item); onBack(); }} style={{ minHeight: 44, padding: '10px 2px', background: 'transparent', border: 0, borderBottom: `2px solid ${saved ? bsTHexA(t.INK, 0.35) : teal}`, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK }}>{saved ? 'Remove from library' : '♡ Save to library'}</button>
      </div>
      <BSFooter right="Library" />
      {startSheet && (
        <div onClick={() => !starting && setStartSheet(false)} style={{ position: 'absolute', inset: 0, zIndex: 70, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', boxSizing: 'border-box', background: t.PAPER, borderTopLeftRadius: 22, borderTopRightRadius: 22, borderTop: `1px solid ${t.RULE}`, padding: `18px ${t.padX}px calc(18px + env(safe-area-inset-bottom, 0px))`, boxShadow: '0 -20px 50px rgba(0,0,0,0.4)', '--bs-accent': teal }}>
            <div style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.22em', textTransform: 'uppercase', color: teal }}>Start plan</div>
            <div style={{ marginTop: 6, fontFamily: t.DISPLAY, fontSize: 24, fontWeight: 700, letterSpacing: '-0.03em', color: t.INK, lineHeight: 1 }}>{item.title}</div>
            <div aria-hidden style={{ margin: '12px 0 14px', height: 2, borderRadius: 2, background: `linear-gradient(90deg, ${t.INK}, ${teal} 72%, transparent)` }} />
            <label style={{ display: 'block' }}><span style={{ display: 'block', fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50, marginBottom: 4 }}>Start date</span>
              <input className="bs-uline" type="date" value={startISO} onChange={(e) => setStartISO(e.target.value)} style={{ width: '100%', boxSizing: 'border-box', padding: '6px 0 10px', fontFamily: t.DISPLAY, fontSize: 16, fontWeight: 600, color: t.INK, outline: 'none', '--bs-uline-ink': bsTHexA(t.INK, 0.25) }} /></label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginTop: 14 }}>
              <span style={{ fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.INK50 }}>Weeks</span>
              <button onClick={() => setStartWeeks(Math.max(1, startWeeks - 1))} style={{ width: 28, height: 28, borderRadius: 999, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer' }}>−</button>
              <span style={{ fontFamily: t.DISPLAY, fontSize: 17, fontWeight: 700, color: t.INK, minWidth: 18, textAlign: 'center' }}>{startWeeks}</span>
              <button onClick={() => setStartWeeks(Math.min(26, startWeeks + 1))} style={{ width: 28, height: 28, borderRadius: 999, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer' }}>＋</button>
            </div>
            {startErr && <div style={{ marginTop: 10, fontFamily: t.MONO, fontSize: 9, color: '#c0533b' }}>{startErr}</div>}
            <div style={{ display: 'flex', gap: 12, marginTop: 16, alignItems: 'center' }}>
              <button onClick={() => !starting && setStartSheet(false)} style={{ background: 'transparent', border: 0, cursor: 'pointer', padding: '13px 10px', minHeight: 44, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.INK }}><span style={{ borderBottom: `2px solid ${bsTHexA(t.INK, 0.35)}`, paddingBottom: 2 }}>Cancel</span></button>
              <button onClick={doStart} disabled={starting} style={{ flex: 1, padding: '14px', borderRadius: 6, clipPath: 'polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 0 100%)', border: 0, background: teal, color: t.isLight ? '#fff' : '#04201d', cursor: starting ? 'default' : 'pointer', fontFamily: t.MONO, fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>{starting ? 'Starting…' : 'Add to my week →'}</button>
            </div>
          </div>
        </div>
      )}
    </BSPage>
  );
}

function BSClientLibrary({ onBack, goMarket = () => {} }) {
  const t = useBS();
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  const items = useBSLibrary();
  const [filter, setFilter] = useStateBSC('all');
  const [query, setQuery] = useStateBSC('');
  const [open, setOpen] = useStateBSC(null);
  const kindMeta = BS_LIB_KINDS;
  if (open) {
    const live = items.find(x => x.id === open.id) || open;
    return <BSLibraryDetail item={live} onBack={() => setOpen(null)} />;
  }
  const q = query.trim().toLowerCase();
  const list = items
    .filter(i => filter === 'all' || i.kind === filter)
    .filter(i => !q || [i.title, i.meta, i.coach].filter(Boolean).join(' ').toLowerCase().includes(q));
  return (
    <BSPage>
      <div style={{ padding: `14px ${t.padX}px 0` }}>
        {window.BSMastRow && <window.BSMastRow trailing={<BSMeCorner />} />}
        <div style={{ marginTop: 12 }}>
          <BSBackButton onClick={onBack} />
        </div>
        <div style={{ marginTop: 14, fontFamily: t.MONO, fontSize: 9.5, letterSpacing: '0.2em', textTransform: 'uppercase', color: teal, fontWeight: 700 }}>Your library</div>
        <h1 style={{ margin: '6px 0 0', fontFamily: t.DISPLAY, fontSize: 38, fontWeight: 700, lineHeight: 0.95, letterSpacing: '-0.04em', color: t.INK }}>Saved<br/><span style={{ fontStyle: 'italic', color: teal }}>everything.</span></h1>
        <div style={{ marginTop: 10, fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 14, lineHeight: 1.4, color: t.INK70 }}>Every workout, meal, recipe and grocery list you keep — in one place.</div>
      </div>

      <div style={{ padding: `16px ${t.padX}px 4px`, display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
        {[['workout', 'Workouts', t.RUST || '#c0533b'], ['meal', 'Meals', t.GREEN || '#5fae7e'], ['recipe', 'Recipes', teal], ['grocery', 'Groceries', BS_LIB_KINDS.grocery.color]].map(([k, label, c]) => {
          const on = filter === k;
          const count = items.filter(i => i.kind === k).length;
          return (
            <button type="button" key={k} onClick={() => setFilter(on ? 'all' : k)} aria-pressed={on} style={{ background: 'transparent', border: 0, cursor: 'pointer', padding: '4px 0', minHeight: 44, textAlign: 'left' }}>
              <span style={{ display: 'block', fontFamily: t.DISPLAY, fontSize: 24, fontWeight: 700, color: on ? t.INK : t.INK70, letterSpacing: '-0.03em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{count}</span>
              <span style={{ display: 'block', marginTop: 3, fontFamily: t.MONO, fontSize: 7.5, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: c }}>{label}</span>
              <span aria-hidden style={{ display: 'block', marginTop: 5, width: 22, height: on ? 3 : 2, background: c }} />
            </button>
          );
        })}
      </div>

      <div style={{ padding: `0 ${t.padX}px 16px` }}>
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search your library…"
          style={{ width: '100%', boxSizing: 'border-box', padding: '10px 2px', border: 0, borderBottom: `1px solid ${t.RULE}`, borderRadius: 0, background: 'transparent', color: t.INK, fontFamily: t.DISPLAY, fontSize: 16, outline: 'none' }}
        />
      </div>

      {list.length === 0 ? (
        <div style={{ padding: `20px ${t.padX}px`, textAlign: 'center' }}>
          <div style={{ fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 15, color: t.INK70, lineHeight: 1.5 }}>{q ? 'No matches — try a different search.' : (filter === 'all' ? <>Nothing saved yet. Save your coaches&rsquo; workouts, meals, recipes, and grocery lists here — tap <b>Save</b> on any of them.</> : 'None in here yet.')}</div>
          {!q ? <button type="button" onClick={() => goMarket()} style={{ marginTop: 16, minHeight: 44, padding: '10px 2px', background: 'transparent', border: 0, borderBottom: `2px solid ${teal}`, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK }}>Browse marketplace →</button> : null}
        </div>
      ) : (
        <div style={{ padding: `0 ${t.padX}px` }}>
          {list.map((it, idx) => {
            const km = kindMeta[it.kind] || { label: it.kind, color: t.INK50 };
            return (
              <button type="button" key={it.id} onClick={() => setOpen(it)} style={{ width: '100%', display: 'grid', gridTemplateColumns: '8px 1fr auto', gap: 10, alignItems: 'baseline', padding: '12px 0', borderTop: idx === 0 ? 0 : `1px solid ${t.HAIR}`, background: 'transparent', border: 0, cursor: 'pointer', textAlign: 'left', minHeight: 44 }}>
                <span aria-hidden style={{ width: 8, height: 8, borderRadius: 1, alignSelf: 'center', background: km.color }} />
                <span style={{ minWidth: 0 }}>
                  <span style={{ display: 'block', fontFamily: t.DISPLAY, fontSize: 15, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{it.title}</span>
                  <span style={{ display: 'block', marginTop: 3, fontFamily: t.MONO, fontSize: 9, color: t.INK50, letterSpacing: '0.04em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{[km.label && km.label.toUpperCase(), it.price, it.coach, it.meta].filter(Boolean).join(' · ')}</span>
                </span>
                <span style={{ fontFamily: t.MONO, fontSize: 8.5, color: t.INK50, whiteSpace: 'nowrap' }}>{it.savedAt ? new Date(it.savedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : ''}</span>
              </button>
            );
          })}
        </div>
      )}
      <BSFooter right="Library" />
    </BSPage>
  );
}

function BSHomeWorkoutPreview({ workout = null, onBack, onMove = () => {}, onStart = () => {}, onMessage = () => {} }) {
  const t = useBS();
  const tr = useShapeTr();
  const rust = t.RUST;
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  const detail = workout && workout.detail;
  const wkTitle = (workout && workout.title) || 'Upper Pull — Peak';
  const wkMeta = (detail && detail.meta) || '52 min · 6 moves · RPE 8 · ~420 kcal';
  const wkNote = (detail && detail.note) || 'Peak week — tempo matters more than load. 3s eccentric on every pull. If bar speed drops, drop a rep, not the tempo.';
  const moves = (detail && detail.moves) || [
    { name: 'Pull-up',        scheme: '4 × 6-8 · 3 min rest', cue: 'Dead hang. Chest to bar.',      load: '42 lb', up: true },
    { name: 'Barbell row',    scheme: '4 × 8 · 2 min rest',   cue: 'Hinge 45°, pull to sternum.',   load: '155 lb' },
    { name: 'Chest-sup. row', scheme: '3 × 10 · 90s rest',    cue: 'Pause 1s at peak contraction.', load: '60 lb' },
    { name: 'Face pull',      scheme: '3 × 15 · 60s rest',    cue: 'External rotation at the top.', load: '35 lb' },
    { name: 'Incline curl',   scheme: '3 × 12 · 60s rest',    cue: 'Full stretch. 3s eccentric.',   load: '27.5 lb' },
    { name: 'Farmer carry',   scheme: '3 × 40m · 60s rest',   cue: 'Crush grip. Ribs down.',        load: '80 lb' },
  ];
  // "Today · Thu Jun 4 · 5:45 PM" — the workout is today's session. Weekday/month
  // tokens follow the selected UI language (i18n date-locale rule).
  const _wd = new Date();
  const _dateLoc = bsDateLocale();
  const _dow = _wd.toLocaleDateString(_dateLoc, { weekday: 'short' });
  const _mon = _wd.toLocaleDateString(_dateLoc, { month: 'short' });
  const wkTimeLabel = (() => {
    const [h, m] = String((workout && workout.time) || '09:00').split(':').map(Number);
    if (Number.isNaN(h)) return '9:00 AM';
    const ap = h >= 12 ? 'PM' : 'AM';
    return `${h % 12 === 0 ? 12 : h % 12}:${String(m).padStart(2, '0')} ${ap}`;
  })();
  const [reminded, setReminded] = useStateBSC(false);
  const headBtn = { background: 'transparent', border: 0, cursor: 'pointer', padding: 0, fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: t.INK };
  const footBtn = { flex: 1, padding: '14px', borderRadius: 5, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase' };
  return (
    <BSPage>
      <div style={{ padding: `46px ${t.padX}px 0` }}>
        {window.BSMastRow && <window.BSMastRow trailing={<BSMeCorner />} />}
      </div>
      <div style={{ padding: `12px ${t.padX}px 2px`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
        <BSBackButton onClick={onBack} />
        <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: rust }}>{tr('home:workoutPreview.eyebrow', { defaultValue: 'Preview' })}</span>
        <button onClick={onMessage} style={{ ...headBtn, color: t.INK50 }}>{tr('home:action.message', { defaultValue: 'Message' })}</button>
      </div>

      <div style={{ padding: `18px ${t.padX}px 4px` }}>
        <div style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{tr('home:when.today', { defaultValue: 'Today' })} · {_dow} {_mon} {_wd.getDate()} · {wkTimeLabel}</div>
        <div style={{ marginTop: 10, fontFamily: t.DISPLAY, fontSize: 38, fontWeight: 700, color: t.INK, letterSpacing: '-0.035em', lineHeight: 0.98 }}>{wkTitle}<span style={{ color: t.ACCENT }}>.</span></div>
        <div style={{ marginTop: 10, fontFamily: t.MONO, fontSize: 9.5, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{wkMeta}</div>
      </div>

      {/* Coach note — Wire press credit (rust = trainer role) */}
      <div style={{ padding: `16px ${t.padX}px 0` }}>
        <div style={{ borderLeft: `3px solid ${rust}`, padding: '3px 0 3px 11px' }}>
          <div style={{ fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 14, fontWeight: 500, color: t.INK, lineHeight: 1.5, letterSpacing: '-0.01em' }}>“{wkNote}”</div>
          <div style={{ marginTop: 5, fontFamily: t.MONO, fontSize: 7.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50 }}>Jordan Chen · Trainer · notes</div>
        </div>
      </div>

      {/* Moves — the plan ledger */}
      <BSOLHead heat={t.ACCENT} label={tr('home:workoutPreview.plan', { defaultValue: 'Plan' })} t={t} right={<span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.12em', color: t.INK50 }}>{tr('home:workoutPreview.moves', { defaultValue: '{count, plural, one {# move} other {# moves}}', count: moves.length })}</span>} />
      <div style={{ padding: `2px ${t.padX}px 0` }}>
        {moves.map((m, i) => (
          <div key={m.name} style={{ padding: '12px 0', borderTop: i === 0 ? 0 : `1px solid ${t.HAIR}` }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 9 }}>
              <span style={{ flexShrink: 0, width: 20, fontFamily: t.MONO, fontSize: 10, fontWeight: 700, color: t.INK50 }}>{String(i + 1).padStart(2, '0')}</span>
              <span style={{ minWidth: 0, fontFamily: t.DISPLAY, fontSize: 16, fontWeight: 700, color: t.INK, letterSpacing: '-0.02em' }}>{m.name}</span>
              <span aria-hidden style={{ flex: 1, minWidth: 14, borderBottom: `1px dotted ${bsTHexA(t.INK, 0.28)}`, transform: 'translateY(-4px)' }} />
              <span style={{ flexShrink: 0, fontFamily: t.MONO, fontSize: 11, fontWeight: 700, color: t.INK70, fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' }}>{m.load || ''}{m.load && m.up ? ' +' : ''}</span>
            </div>
            <div style={{ marginTop: 4, paddingLeft: 29, fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>{m.scheme}</div>
            {m.cue && <div style={{ marginTop: 4, paddingLeft: 29, fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 12.5, fontWeight: 500, color: t.INK70, letterSpacing: '-0.01em' }}>“{m.cue}”</div>}
          </div>
        ))}
      </div>

      {/* Quick actions — above the soundtrack */}
      <div style={{ padding: `14px ${t.padX}px 4px`, display: 'flex', gap: 10 }}>
        <BSSaveButton full item={{ id: 'workout:upper-pull-peak', kind: 'workout', title: 'Upper Pull — Peak', meta: '52 min · 6 moves · RPE 8', coach: 'Jordan Chen' }} />
        <button onClick={onMove} style={footBtn}>{tr('home:workoutPreview.moveSession', { defaultValue: 'Move session' })}</button>
        <button onClick={() => setReminded(true)} style={{ ...footBtn, ...(reminded ? { borderColor: teal, borderLeft: `3px solid ${teal}`, background: `${teal}14`, color: teal } : {}) }}>{reminded ? tr('home:workoutPreview.reminderSet', { defaultValue: '✓ Reminder set' }) : tr('home:workoutPreview.remindMe', { defaultValue: 'Remind me' })}</button>
      </div>

      {/* Pre-workout playlist — tap the play button to open it in Spotify before training */}
      <div style={{ padding: `18px ${t.padX}px 4px` }}>
        <BSEyebrow color={teal}>{tr('home:workoutPreview.soundtrack', { defaultValue: 'Soundtrack' })}</BSEyebrow>
        <div style={{ marginTop: 2, marginBottom: 12, fontFamily: t.DISPLAY, fontSize: 27, fontWeight: 700, color: t.INK, letterSpacing: '-0.025em' }}>{tr('home:workoutPreview.preWorkout', { defaultValue: 'Pre-workout' })}</div>
        <BSPlaylistCard kicker="Jordan Chen · Your coach" title="Pull heavy." meta="52m · 95-138 BPM · 14 tracks" color="#1db954" spotifyUrl="https://open.spotify.com/playlist/37i9dQZF1DX76Wlfdnj7AP" tracks={[
          { a: 'Iron Count', b: 'Tariq Osei', len: '3:38' },
          { a: 'Chalk & Steel', b: 'Sable', len: '4:02' },
          { a: 'Top Set', b: 'Linnea Aho', len: '3:21' },
          { a: 'Overhand', b: 'Samyuel', len: '3:54' },
          { a: 'Lat Spread', b: 'Mara Vance', len: '4:16' },
          { a: 'Last Rep', b: 'Shape Radio', len: '3:45' },
        ]} />
      </div>

      <div style={{ padding: `16px ${t.padX}px 14px` }}>
        <button onClick={onStart} style={{ width: '100%', padding: '15px', borderRadius: 5, clipPath: 'polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%)', border: 0, background: teal, color: t.isLight ? '#ffffff' : '#04201d', cursor: 'pointer', fontFamily: t.MONO, fontSize: 11, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase' }}>{tr('home:workoutPreview.begin', { defaultValue: 'Begin session →' })}</button>
      </div>
      <BSFooter right={tr('home:workoutPreview.eyebrow', { defaultValue: 'Preview' })} />
    </BSPage>
  );
}

// Stable per-ingredient id so a React list key never collides on duplicate
// names (addFood / manual edits can produce two rows with the same name).
let _bsIngSeq = 0;
const bsIngId = () => `bsing-${++_bsIngSeq}`;

// Real food recents — user_goals('food_recents'), cap 20, most-recent-first,
// deduped by name. Best-effort: a failed write never blocks the add.
async function bsLoadFoodRecents() {
  try {
    const doc = await window.shapeDb?.getUserGoals?.('food_recents');
    const items = doc && Array.isArray(doc.items) ? doc.items : [];
    return items.filter((x) => x && x.name).slice(0, 20);
  } catch (e) { return []; }
}
function bsPushFoodRecent(items, f) {
  const key = String(f.name || '').trim().toLowerCase();
  const rest = (Array.isArray(items) ? items : []).filter((x) => String((x && x.name) || '').trim().toLowerCase() !== key);
  return [{ name: f.name, qty: f.qty || '1 serving', kcal: Math.round(Number(f.kcal) || 0), p: Math.round(Number(f.p) || 0), c: Math.round(Number(f.c) || 0), f: Math.round(Number(f.f) || 0) }, ...rest].slice(0, 20);
}

// Barcode scan support: the BarcodeDetector API (Chrome/Android WebView) +
// camera access. iOS WebKit ships neither BarcodeDetector nor (pre-14.3)
// getUserMedia — those fall to the manual digits entry, honestly.
function bsBarcodeScanSupported() {
  try {
    return typeof window !== 'undefined'
      && typeof window.BarcodeDetector === 'function'
      && !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia);
  } catch (e) { return false; }
}

// Live camera scanner for the add-food sheet. Owns the stream lifecycle
// (unmount stops every track); polls BarcodeDetector ~3×/s on the video and
// fires onHit ONCE with the first raw code. Camera denial / detector failure
// degrades to onFallback (the manual digits entry) — never a dead end.
function BSBarcodeScan({ onHit, onFallback, teal }) {
  const t = useBS();
  const videoRef = React.useRef(null);
  React.useEffect(() => {
    let stream = null, timer = null, done = false;
    let detector = null;
    try {
      detector = new window.BarcodeDetector({ formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'itf'] });
    } catch (e) { onFallback(); return undefined; }
    navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
      .then((s) => {
        if (done) { s.getTracks().forEach((track) => track.stop()); return; }
        stream = s;
        const v = videoRef.current;
        if (v) { v.srcObject = s; const p = v.play && v.play(); if (p && p.catch) p.catch(() => {}); }
        timer = setInterval(async () => {
          const vid = videoRef.current;
          if (done || !vid || vid.readyState < 2) return;
          try {
            const hits = await detector.detect(vid);
            const code = hits && hits[0] && hits[0].rawValue;
            if (code && !done) { done = true; clearInterval(timer); onHit(String(code)); }
          } catch (e) { /* per-frame detect failures are normal — keep polling */ }
        }, 350);
      })
      .catch(() => { if (!done) onFallback(); });
    return () => { done = true; if (timer) clearInterval(timer); if (stream) stream.getTracks().forEach((track) => track.stop()); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return (
    <div style={{ marginTop: 12, position: 'relative', borderRadius: t.RADIUS_SM, overflow: 'hidden', border: `1px solid ${t.RULE}`, background: '#000' }}>
      <video ref={videoRef} muted playsInline style={{ display: 'block', width: '100%', height: 190, objectFit: 'cover' }} />
      <div aria-hidden style={{ position: 'absolute', left: '10%', right: '10%', top: '50%', height: 2, background: teal, opacity: 0.85, boxShadow: `0 0 12px ${teal}` }} />
      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '8px 12px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'linear-gradient(transparent, rgba(0,0,0,0.65))' }}>
        <span style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: '#fff' }}>Point at the barcode</span>
      </div>
    </div>
  );
}

// Full meal-logging flow — opened from the home "Up next" meal card's
// "Log now" button. One-tap "ate as planned", or adjust portion / ingredients,
// photo, or voice; writes to the day total and shows a logged confirmation.
function BSLogMealFlow({ onClose, onLogged = () => {}, meal = null, daySoFar = null, dayTargets = null, signedIn = false }) {
  const t = useBS();
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  // mode tabs removed — Adjust is the always-visible register; photo/voice are
  // dispatch disclosures; search folds into the ADD sheet.
  const [portion, setPortion] = useStateBSC(1);
  const [note, setNote] = useStateBSC('');
  const [foodQuery, setFoodQuery] = useStateBSC('');
  const [foodResults, setFoodResults] = useStateBSC(null);   // null = idle (no live query yet)
  const [foodStatus, setFoodStatus] = useStateBSC('idle');   // idle | searching | done | error
  const [foodRecents, setFoodRecents] = useStateBSC(null);   // null until loaded
  // Barcode lookup (v2) — 'scan' opens the camera (BarcodeDetector), 'enter'
  // the manual digits input (the honest fallback where the API is absent —
  // iOS WebKit has no BarcodeDetector).
  const [barcodeMode, setBarcodeMode] = useStateBSC(null);      // null | 'scan' | 'enter'
  const [barcodeDigits, setBarcodeDigits] = useStateBSC('');
  const [barcodeStatus, setBarcodeStatus] = useStateBSC('idle'); // idle | looking | invalid | notfound | error
  const [logged, setLogged] = useStateBSC(false);
  const [award, setAward] = useStateBSC(null);         // {awarded, points} | null — set after log resolves
  // Share-by-choice (spec 2026-07-12), freehand-logger parity with
  // BSMealLogged: per-meal, default off, never auto; only a real Supabase row
  // counts as shared. This screen has no un-log, so there's no Undo coupling —
  // a shared post stays owner-deletable from its feed card.
  const [sharedPostId, setSharedPostId] = useStateBSC(null);
  const [shareBusy, setShareBusy] = useStateBSC(false);
  const [coach, setCoach] = useStateBSC(null);         // {name, role} | null — resolved linked nutritionist/coach
  const [showAddFood, setShowAddFood] = useStateBSC(false);
  const [photoOpen, setPhotoOpen] = useStateBSC(false); // dispatch disclosures
  const [voiceOpen, setVoiceOpen] = useStateBSC(false);
  const [ings, setIngs] = useStateBSC(() => {
    // Seed from the REAL meal being logged when its macros are known; for a
    // signed-in account with no macro breakdown, start empty (add what you ate)
    // — never the demo plate. The demo ingredients are the signed-out preview.
    if (meal && Number.isFinite(Number(meal.kcal))) {
      return [{ id: bsIngId(), name: meal.title || 'Meal', qty: '1 serving', kcal: Math.round(Number(meal.kcal) || 0), p: Math.round(Number(meal.p) || 0), c: Math.round(Number(meal.c) || 0), f: Math.round(Number(meal.f) || 0), on: true }];
    }
    if (signedIn) return [];
    return [
      { id: bsIngId(), name: 'Grilled chicken breast', qty: '6 oz',  kcal: 280, p: 52, c: 0,  f: 8,  on: true },
      { id: bsIngId(), name: 'Jasmine rice',           qty: '1 cup', kcal: 205, p: 4,  c: 45, f: 0,  on: true },
      { id: bsIngId(), name: 'Charred broccoli',       qty: '1 cup', kcal: 55,  p: 4,  c: 11, f: 0,  on: true },
      { id: bsIngId(), name: 'Avocado',                qty: '½',     kcal: 120, p: 2,  c: 6,  f: 11, on: true },
      { id: bsIngId(), name: 'Tahini sauce',           qty: '2 tbsp',kcal: 90,  p: 3,  c: 3,  f: 8,  on: true },
    ];
  });
  const toggle = (i) => setIngs(arr => arr.map((x, j) => (j === i ? { ...x, on: !x.on } : x)));
  // Frozen copy of the ingredients as the sheet opened — the baseline the dirty
  // predicate compares against (toggle / edit / add / remove all diverge from it).
  const initialIngsRef = React.useRef(null);
  if (initialIngsRef.current === null) initialIngsRef.current = ings.map((x) => ({ ...x }));

  // Real recents — loaded once per sheet open (signed-in only; the demo
  // catalog stays the signed-out preview).
  React.useEffect(() => {
    if (!signedIn || !showAddFood || foodRecents !== null) return;
    let on = true;
    // A late load must never clobber a list an add already updated.
    bsLoadFoodRecents().then((items) => { if (on) setFoodRecents((cur) => (cur === null ? items : cur)); });
    return () => { on = false; };
  }, [signedIn, showAddFood]);

  // In-flight barcode lookup — aborted on sheet close and before a new lookup,
  // so a late OFF response can never reopen a dismissed editor or land the
  // PREVIOUS barcode's product over the one the member is entering now.
  const barcodeCtlRef = React.useRef(null);
  // Closing the add sheet always ends a scan (unmounts the camera), aborts an
  // in-flight lookup, and clears the barcode state — a reopened sheet never
  // resumes a stale lookup.
  React.useEffect(() => {
    if (!showAddFood) {
      try { barcodeCtlRef.current?.abort(); } catch (e) {}
      barcodeCtlRef.current = null;
      setBarcodeMode(null); setBarcodeDigits(''); setBarcodeStatus('idle');
    }
  }, [showAddFood]);

  // Persist an added food to real recents. Centralized so BOTH add paths (＋
  // direct and via the prefilled editor) go through it, and so an add that
  // races the initial recents load merges with the CLOUD list instead of
  // clobbering it with a single item. Best-effort — never blocks the add.
  const rememberFood = async (f) => {
    try {
      const base = foodRecents === null ? await bsLoadFoodRecents() : foodRecents;
      const next = bsPushFoodRecent(base, f);
      setFoodRecents(next);
      await window.shapeDb?.saveUserGoals?.('food_recents', { items: next });
    } catch (e) {}
  };

  // Live food search — debounced 350 ms, in-flight aborted, min 2 chars.
  React.useEffect(() => {
    if (!signedIn || !showAddFood) return;
    const q = foodQuery.trim();
    if (q.length < 2) { setFoodResults(null); setFoodStatus('idle'); return; }
    // Clear immediately — the previous query's rows must not stay clickable
    // through the debounce (a member could add a food that no longer matches
    // what they typed).
    setFoodResults(null);
    setFoodStatus('searching');
    const ctl = new AbortController();
    const timer = setTimeout(() => {
      window.ShapeFoodSearch?.search(q, { signal: ctl.signal })
        .then((data) => {
          if (ctl.signal.aborted) return;
          setFoodResults(Array.isArray(data.results) ? data.results : []);
          setFoodStatus(data.unavailable ? 'error' : 'done');
        })
        .catch(() => { if (ctl.signal.aborted) return; setFoodResults([]); setFoodStatus('error'); });
    }, 350);
    return () => { clearTimeout(timer); ctl.abort(); };
  }, [foodQuery, signedIn, showAddFood]);
  // Broadcast "cooking" presence while the meal logger is open (amber dot) — and,
  // for a PLAN/RECIPE-sourced meal, the live cooking TITLE (spec 2026-07-19).
  // Provenance is LIVE: pivoting to freehand mid-session actively clears the
  // row (never waits for close); the audience re-resolves per push, and a
  // settings change re-pushes immediately via shape:liveAudienceChanged.
  React.useEffect(() => { bsSetMyActivity('cooking'); return () => bsSetMyActivity(null); }, []);
  const cookPayload = React.useMemo(() => bsCookingPayload(meal), [meal]);
  const cookPushedRef = React.useRef(null);              // last-pushed MEAL KEY — fresh=true when
  React.useEffect(() => {                                // the key changes; a re-push of the SAME
    if (!window.ShapeLiveProgress) return undefined;     // meal must never reset started_at
    if (cookPayload) {
      // The ref holds a meal KEY (id, else the payload title), not a boolean, so
      // a DIRECT swap from one eligible meal to another (A → B with no
      // ineligible gap between renders) still restamps started_at for B.
      const mealKey = (meal && (meal.id != null ? String(meal.id) : null)) || cookPayload.title;
      window.ShapeLiveProgress.push(cookPayload, cookPushedRef.current !== mealKey);
      cookPushedRef.current = mealKey;
    } else {
      window.ShapeLiveProgress.clear();                  // ineligible → absence, NOW
      cookPushedRef.current = null;                      // a NEW eligible meal restarts the clock
    }
    // Pass the audience the settings change already resolved straight through —
    // never let this push re-read the (possibly not-yet-persisted) settings doc.
    const rePush = (e) => {
      if (!cookPayload) return;
      const vis = e && e.detail ? e.detail.visibility : undefined;
      window.ShapeLiveProgress.push(cookPayload, false, { visOverride: vis });
    };
    window.addEventListener('shape:liveAudienceChanged', rePush);
    return () => {
      window.removeEventListener('shape:liveAudienceChanged', rePush);
      window.ShapeLiveProgress.clear();                  // logger close → absence
    };
  }, [cookPayload]);

  // Resolve the member's linked coach for the dispatch register — prefer the
  // nutritionist thread, else any linked coach. No thread → coach stays null and
  // the whole dispatch register hides (the meal-note endpoint no-ops anyway).
  React.useEffect(() => {
    if (!signedIn || !window.ShapeMessages?.listDirectCoachThreads) return;
    let alive = true;
    window.ShapeMessages.listDirectCoachThreads().then((res) => {
      const list = Array.isArray(res) ? res : (res && res.data) || [];
      if (!alive || !list.length) return;
      const nutri = list.find((c) => c.provider_role === 'nutritionist');
      const co = nutri || list[0];
      const nm = co.who || co.name || co.full_name;
      if (!nm) return;
      setCoach({ name: nm, role: co.provider_role === 'nutritionist' ? 'nutritionist' : 'trainer' });
    }).catch(() => {});
    return () => { alive = false; };
  }, [signedIn]);

  // Voice note for the coach — either dictate (speech → text appended to the
  // note) or record an audio memo that rides along with the log. Web
  // MediaRecorder; transcription via /api/nutrition/voice. (Native mic plugin
  // is a follow-up.)
  const [voiceCapture, setVoiceCapture] = useStateBSC('text'); // 'text' (dictate) | 'audio' (memo)
  const [voiceState, setVoiceState] = useStateBSC('idle');     // 'idle' | 'recording' | 'processing'
  const [voiceError, setVoiceError] = useStateBSC('');
  const [voiceSecs, setVoiceSecs] = useStateBSC(0);
  const [voiceMemo, setVoiceMemo] = useStateBSC(null);         // { url, secs } recorded audio memo
  const voiceRef = React.useRef({ rec: null, chunks: [], stream: null, timer: null, secs: 0 });
  const fmtSecs = (s) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  const cleanupVoice = () => {
    const v = voiceRef.current;
    if (v.timer) { clearInterval(v.timer); v.timer = null; }
    try { v.stream && v.stream.getTracks().forEach(tr => tr.stop()); } catch (e) {}
    v.stream = null; v.rec = null; v.chunks = [];
  };
  React.useEffect(() => () => cleanupVoice(), []);
  const removeMemo = () => { setVoiceMemo(m => { try { if (m && m.url) URL.revokeObjectURL(m.url); } catch (e) {} return null; }); };
  const dictate = async (blob) => {
    setVoiceState('processing');
    try {
      const fd = new FormData();
      fd.append('audio', blob, 'note.webm');
      const res = await fetch('/api/nutrition/voice', { method: 'POST', body: fd, credentials: 'same-origin' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) { setVoiceError(data && data.error ? data.error : 'Could not transcribe'); return; }
      const text = String(data.transcript || '').trim();
      if (text) { setNote(n => (n && n.trim() ? `${n.trim()} ${text}` : text)); window.__bsToast?.('Added to your note', 'ok'); }
      else setVoiceError('Didn’t catch that — try again');
    } catch (e) {
      setVoiceError('Voice notes unavailable');
    } finally {
      setVoiceState('idle');
    }
  };
  const startVoice = async () => {
    setVoiceError('');
    if (!(typeof navigator !== 'undefined' && navigator.mediaDevices && navigator.mediaDevices.getUserMedia && typeof MediaRecorder !== 'undefined')) {
      setVoiceError('Voice input isn’t supported here yet'); return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const rec = new MediaRecorder(stream);
      const v = voiceRef.current;
      v.stream = stream; v.rec = rec; v.chunks = []; v.secs = 0;
      const captureAtStart = voiceCapture;
      rec.ondataavailable = (e) => { if (e.data && e.data.size) v.chunks.push(e.data); };
      rec.onstop = () => {
        const secs = v.secs;
        const blob = new Blob(v.chunks, { type: rec.mimeType || 'audio/webm' });
        cleanupVoice();
        if (!(blob.size > 0)) { setVoiceState('idle'); return; }
        if (captureAtStart === 'audio') {
          setVoiceMemo(m => { try { if (m && m.url) URL.revokeObjectURL(m.url); } catch (e) {} return { url: URL.createObjectURL(blob), secs, blob }; });
          window.__bsToast?.('Voice memo attached', 'ok');
          setVoiceState('idle');
        } else {
          dictate(blob);
        }
      };
      rec.start();
      setVoiceSecs(0);
      setVoiceState('recording');
      v.timer = setInterval(() => { v.secs += 1; setVoiceSecs(v.secs); }, 1000);
    } catch (e) {
      setVoiceError('Microphone access denied'); cleanupVoice(); setVoiceState('idle');
    }
  };
  const stopVoice = () => {
    const v = voiceRef.current;
    if (v.timer) { clearInterval(v.timer); v.timer = null; }
    try { if (v.rec && v.rec.state !== 'inactive') v.rec.stop(); else { cleanupVoice(); setVoiceState('idle'); } }
    catch (e) { cleanupVoice(); setVoiceState('idle'); }
  };
  const toggleVoice = () => { if (voiceState === 'recording') stopVoice(); else if (voiceState === 'idle') startVoice(); };

  // Meal photo for the coach — capture (camera) or pick from the library. The
  // image rides along with the log to the coach via /api/nutrition/meal-note.
  // No on-device macro reading yet — Maya reviews the plate.
  const [photo, setPhoto] = useStateBSC(null); // { url, blob }
  const photoCamRef = React.useRef(null);
  const photoLibRef = React.useRef(null);
  const onPhotoPick = (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = ''; // let the user re-pick the same file later
    if (!file) return;
    if (!/^image\//.test(file.type || '')) { window.__bsToast?.('Pick an image', 'err'); return; }
    setPhoto(p => { try { if (p && p.url) URL.revokeObjectURL(p.url); } catch (err) {} return { url: URL.createObjectURL(file), blob: file }; });
    window.__bsToast?.('Photo attached', 'ok');
  };
  const removePhoto = () => setPhoto(p => { try { if (p && p.url) URL.revokeObjectURL(p.url); } catch (err) {} return null; });

  // Edit / add an ingredient via a bottom sheet. editIng.index === null = new.
  const [editIng, setEditIng] = useStateBSC(null);
  const openEditIng = (i) => { const x = ings[i]; setEditIng({ index: i, name: x.name, qty: x.qty || '', kcal: x.kcal, p: x.p, c: x.c, f: x.f }); };
  const openAddIng = () => setEditIng({ index: null, name: '', qty: '', kcal: '', p: '', c: '', f: '' });
  const setEditIngField = (k, v) => setEditIng(e => (e ? { ...e, [k]: v } : e));
  const saveEditIng = () => {
    if (!editIng) return;
    const name = String(editIng.name || '').trim();
    if (!name) { window.__bsToast?.('Add a name', 'err'); return; }
    const item = {
      name, qty: String(editIng.qty || '').trim() || '1 serving',
      kcal: Math.max(0, Math.round(Number(editIng.kcal) || 0)), p: Math.max(0, Math.round(Number(editIng.p) || 0)),
      c: Math.max(0, Math.round(Number(editIng.c) || 0)), f: Math.max(0, Math.round(Number(editIng.f) || 0)),
    };
    if (editIng.index == null) {
      setIngs(arr => [...arr, { ...item, id: bsIngId(), on: true }]);
      window.__bsToast?.(`Added ${name}`, 'ok');
      // A search result added via the prefilled editor is still an add —
      // recents replay what was added (with any portion edits made here).
      if (editIng.fromSearch && signedIn) rememberFood(item);
    }
    else { const idx = editIng.index; setIngs(arr => arr.map((x, j) => (j === idx ? { ...x, ...item } : x))); window.__bsToast?.('Ingredient updated', 'ok'); }
    setEditIng(null);
  };
  const deleteEditIng = () => {
    if (editIng && editIng.index != null) { const idx = editIng.index; setIngs(arr => arr.filter((_, j) => j !== idx)); window.__bsToast?.('Removed', 'ok'); }
    setEditIng(null);
  };

  const sum = (k) => ings.reduce((a, x) => a + (x.on ? x[k] : 0), 0);
  const kcal = Math.round(sum('kcal') * portion);
  const P = Math.round(sum('p') * portion);
  const C = Math.round(sum('c') * portion);
  const F = Math.round(sum('f') * portion);
  // Day targets: real member targets when signed in (passed from the home ticker);
  // the demo goals are only the signed-out preview. null target → render "/ —".
  const CAL_GOAL = signedIn ? ((dayTargets && Number.isFinite(Number(dayTargets.cal))) ? Math.round(Number(dayTargets.cal)) : null) : 2100;
  const P_GOAL   = signedIn ? ((dayTargets && Number.isFinite(Number(dayTargets.protein))) ? Math.round(Number(dayTargets.protein)) : null) : 165;
  const DAY_BASE_CAL = 1568, DAY_BASE_P = 118;
  const hasPlanned = !!(meal && Number.isFinite(Number(meal.kcal)));
  const dirty = bsMealDirty(portion, ings, initialIngsRef.current);
  const ctaLabel = bsMealCtaLabel({ dirty, portion, kcal, hasPlanned });
  const resetToPlan = () => { setPortion(1); setIngs(initialIngsRef.current.map((x) => ({ ...x }))); };
  const coachName = coach ? coach.name : (signedIn ? null : 'Dr. Maya');
  const coachAccent = t.isLight ? '#a07a2e' : '#d8b25a';
  // Real "day so far" for a signed-in account (today's snapshot, passed in); the
  // demo base is only for the signed-out preview. Title/eyebrow/planned/time all
  // reflect the actual meal being logged — never a hardcoded sample.
  const dayBaseCal = signedIn ? Math.max(0, Math.round(Number(daySoFar && daySoFar.cal) || 0)) : DAY_BASE_CAL;
  const dayBaseP = signedIn ? Math.max(0, Math.round(Number(daySoFar && daySoFar.protein) || 0)) : DAY_BASE_P;
  const dayCal = dayBaseCal + kcal;
  const dayP = dayBaseP + P;
  const mealTitle = (meal && meal.title) || (signedIn ? 'Meal' : 'Chicken bowl + rice');
  const logTime = new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  const plannedLine = (meal && Number.isFinite(Number(meal.kcal)))
    ? `${Math.round(Number(meal.kcal))} planned · ${Math.round(Number(meal.p) || 0)}P · ${Math.round(Number(meal.c) || 0)}C · ${Math.round(Number(meal.f) || 0)}F`
    : (signedIn ? 'Add what you ate to log it' : '620 planned · 48P · 72C · 14F');
  const mealEyebrow = (meal && meal.tag) ? `${meal.tag} · Planned` : (signedIn ? 'Log a meal' : 'Lunch · Planned');
  // On log, deliver the written note + any voice memo to the client's
  // nutritionist (best-effort; the endpoint resolves the coach and no-ops when
  // there's nothing to send or no coach linked).
  const sendMealNote = () => {
    const hasNote = !!(note && note.trim());
    const hasMemo = !!(voiceMemo && voiceMemo.blob);
    const hasPhoto = !!(photo && photo.blob);
    if (!hasNote && !hasMemo && !hasPhoto) return;
    try {
      const fd = new FormData();
      if (hasNote) fd.append('note', note.trim());
      fd.append('mealTitle', mealTitle);
      fd.append('mealSummary', `${kcal} kcal · ${P}P · ${C}C · ${F}F`);
      if (hasMemo) fd.append('audio', voiceMemo.blob, 'memo.webm');
      if (hasPhoto) fd.append('photo', photo.blob, photo.blob.name || 'meal.jpg');
      fetch('/api/nutrition/meal-note', { method: 'POST', body: fd, credentials: 'same-origin' })
        .then(r => r.json().catch(() => ({})))
        .then(d => { if (d && d.delivered) window.__bsToast?.('Sent to your coach', 'ok'); })
        .catch(() => {});
    } catch (e) {}
  };
  const doLog = () => {
    sendMealNote();
    // Persist the logged macros onto today's health snapshot so the Nutrition
    // stats (today vs target, adherence) reflect real logging — server-side
    // accumulating write; no-ops when signed out. The +10 Shape Score award
    // ({awarded, points}) rides back on the resolved value; show it only when
    // actually granted (first meal-log of the day), never on an already-earned day.
    try {
      const r = window.ShapeMealLog?.log?.({ kcal, protein: P, carbs: C, fat: F });
      if (r && typeof r.then === 'function') {
        r.then((d) => (d && d.awardPromise) || null)
         .then((a) => { if (a && a.awarded) setAward(a); })
         .catch(() => {});
      }
    } catch (e) {}
    onLogged();
    setLogged(true);
  };
  const primaryBtn = { width: '100%', padding: '15px', borderRadius: t.RADIUS_SM, border: 0, background: t.INK, color: t.PAPER, cursor: 'pointer', fontFamily: t.MONO, fontSize: 11, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase' };

  // (DayTotals dissolved with THE TALLY station — the band carries the day
  // readout now, honest `—` when targets are unknown, same derivations.)

  const LedgerHead = ({ label, accent = teal, extra = null }) => (
    <div style={{ padding: `16px ${t.padX}px 0` }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
        <span style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK }}>{label}</span>
        {extra}
      </div>
      <div style={{ marginTop: 4, height: 2, background: `linear-gradient(90deg, ${t.INK}, ${accent})` }} />
    </div>
  );

  if (logged) {
    const calFrac = CAL_GOAL ? Math.max(0, Math.min(1, dayCal / CAL_GOAL)) : null;
    return (
      <BSPage mast={false}>
        {/* THE BAND — the filed stamp (Cockpit/Split spec 2026-07-14). Fixed
            #0b0f0f on every paper; the paper below the teal seam carries the
            actions. Same instrument literals as the live session's band. */}
        <div style={{ position: 'relative', background: '#0b0f0f', padding: `62px ${t.padX}px 18px`, overflow: 'hidden' }}>
          <div aria-hidden style={{ position: 'absolute', inset: 0, pointerEvents: 'none', background: 'repeating-linear-gradient(180deg, rgba(255,255,255,0.02) 0 1px, transparent 1px 3px)' }} />
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
            <button onClick={onClose} style={{ background: 'transparent', border: 0, padding: 0, minHeight: 44, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: '#f4ede0', display: 'inline-flex', alignItems: 'center', gap: 6 }}><span aria-hidden style={{ fontSize: 11 }}>←</span>Back</button>
            <span style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: '#38e0cc' }}>Meal · Filed {logTime}</span>
          </div>
          <div style={{ position: 'relative', textAlign: 'center', marginTop: 30 }}>
            <div style={{ fontFamily: t.MONO, fontSize: 46, fontWeight: 800, color: '#38e0cc', fontVariantNumeric: 'tabular-nums', lineHeight: 1, textShadow: '0 0 18px rgba(56,224,204,0.45)' }}>{kcal}</div>
            <div style={{ marginTop: 8, fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.55)' }}>Kcal · {P}P · Logged ✓</div>
            {award && award.awarded && (
              <div style={{ marginTop: 14, display: 'inline-flex', alignItems: 'center', gap: 8, padding: '7px 12px', borderRadius: 5, border: '1px solid rgba(56,224,204,0.5)', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: '#38e0cc', animation: 'bsAwardIn 180ms ease-out' }}>
                +{award.points != null ? award.points : 10} · Nutrition · Shape Score
              </div>
            )}
            <style>{`@keyframes bsAwardIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } } @media (prefers-reduced-motion: reduce) { [style*="bsAwardIn"] { animation: none !important; } }`}</style>
          </div>
          <div style={{ position: 'relative', marginTop: 24, borderTop: '1px solid rgba(244,237,224,0.14)', paddingTop: 12 }}>
            <div style={{ fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.35)' }}>Day so far</div>
            <div style={{ marginTop: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12 }}>
              <span style={{ fontFamily: t.MONO, fontSize: 20, fontWeight: 800, color: '#38e0cc', fontVariantNumeric: 'tabular-nums', textShadow: '0 0 12px rgba(56,224,204,0.35)' }}>{dayCal}<span style={{ fontSize: 8.5, color: 'rgba(244,237,224,0.35)', textShadow: 'none' }}> / {CAL_GOAL != null ? CAL_GOAL : '—'} KCAL</span></span>
              <span style={{ fontFamily: t.MONO, fontSize: 20, fontWeight: 800, color: '#e8a13c', fontVariantNumeric: 'tabular-nums', textShadow: '0 0 12px rgba(232,161,60,0.3)' }}>{dayP}<span style={{ fontSize: 8.5, color: 'rgba(244,237,224,0.35)', textShadow: 'none' }}> / {P_GOAL != null ? P_GOAL : '—'} P</span></span>
            </div>
            {calFrac != null && (
              <div aria-hidden style={{ marginTop: 11, display: 'flex', gap: 4 }}>
                {Array.from({ length: 10 }).map((_, i) => (
                  <span key={i} style={{ flex: 1, height: 4, borderRadius: 2, background: (i + 0.5) / 10 <= calFrac ? '#38e0cc' : 'rgba(244,237,224,0.14)', boxShadow: (i + 0.5) / 10 <= calFrac ? '0 0 8px rgba(56,224,204,0.5)' : 'none' }} />
                ))}
              </div>
            )}
          </div>
        </div>
        {/* The seam — the ONE band/paper boundary */}
        <div aria-hidden style={{ height: 3, background: `linear-gradient(90deg, ${teal}, ${bsTHexA(teal, 0.15)})` }} />
        <div style={{ padding: `22px ${t.padX}px 8px` }}>
          <button onClick={onClose} style={{ ...primaryBtn, clipPath: 'polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%)' }}>Done →</button>
        </div>
        {signedIn && typeof window !== 'undefined' && window.ShapeCommunity?.createPost && (
          <div style={{ textAlign: 'center', paddingBottom: 4 }}>
            {sharedPostId ? (
              <div style={{ minHeight: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: teal }}>✓ On the wire · Community</div>
            ) : (
              <button
                disabled={shareBusy}
                onClick={async () => {
                  if (sharedPostId || shareBusy) return;
                  setShareBusy(true);
                  try {
                    // The plate, not the ledger: this meal's post-portion macros
                    // only. planned = a plan meal logged untouched; attribution
                    // only when the meal really came from the plan/catalogue.
                    const res = await window.ShapeCommunity.createPost(bsMealSharePayload({
                      name: mealTitle, kcal, p: P, c: C, f: F, portion,
                      planned: hasPlanned && !dirty,
                      recipeId: (meal && meal.recipeId) || '',
                      // Attribution comes from the meal's OWN plan coach (stamped
                      // by bsHomeLiveWeek from /api/client/plan), never the
                      // DM-thread `coach` state — that resolver can name a
                      // different person or still be in flight (review P2).
                      coach: (hasPlanned && meal && meal.coach) || '',
                    }));
                    if (res && res.stored === 'supabase' && res.data && res.data.id) {
                      setSharedPostId(res.data.id);
                      window.__bsToast?.('On the wire → Community', 'ok');
                    } else {
                      window.__bsToast?.('Could not post — try again.', 'err');
                    }
                  } catch (e) {
                    window.__bsToast?.('Could not post — try again.', 'err');
                  }
                  setShareBusy(false);
                }}
                style={{ background: 'transparent', border: 0, cursor: shareBusy ? 'default' : 'pointer', minHeight: 44, padding: '0 12px', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: shareBusy ? t.INK50 : teal }}
              >{shareBusy ? 'Posting…' : 'Post to the wire →'}</button>
            )}
          </div>
        )}
      </BSPage>
    );
  }

  return (
    <BSPage mast={false}>
      {/* ═══ THE BAND — the one-tap + the live tally (Cockpit/Split spec,
          2026-07-14). Fixed #0b0f0f on every paper; CORRECT THE RECORD +
          DISPATCH stay paper below the teal seam. THE TALLY station
          dissolved — the band IS the tally now. */}
      <div style={{ position: 'relative', background: '#0b0f0f', padding: `62px ${t.padX}px 16px`, overflow: 'hidden' }}>
        <div aria-hidden style={{ position: 'absolute', inset: 0, pointerEvents: 'none', background: 'repeating-linear-gradient(180deg, rgba(255,255,255,0.02) 0 1px, transparent 1px 3px)' }} />
        <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
          <button onClick={onClose} style={{ background: 'transparent', border: 0, cursor: 'pointer', padding: 0, minHeight: 44, fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: '#f4ede0' }}>× Cancel</button>
          <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: '#38e0cc' }}>Log meal</span>
          <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.12em', color: 'rgba(244,237,224,0.55)' }}>{logTime}</span>
        </div>
        <div style={{ position: 'relative', marginTop: 16 }}>
          <div style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.55)' }}>{mealEyebrow}</div>
          <div style={{ marginTop: 8, fontFamily: t.DISPLAY, fontSize: 23, fontWeight: t.W.displayHeavy, letterSpacing: '0.02em', textTransform: 'uppercase', color: '#f4ede0', lineHeight: 1.05 }}>{mealTitle}</div>
          <div style={{ marginTop: 7, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.12em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.35)', fontWeight: 700 }}>{plannedLine}</div>
        </div>
        {/* Pristine planned meal → the glowing one-tap. Adjusted → the reset
            line. Free log → neither (unchanged gating). */}
        {hasPlanned && !dirty && (
          <button onClick={doLog} style={{ position: 'relative', width: '100%', marginTop: 14, textAlign: 'left', border: '1.5px solid #38e0cc', borderRadius: 8, background: 'rgba(56,224,204,0.08)', boxShadow: '0 0 18px rgba(56,224,204,0.18)', padding: '13px 15px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
            <span style={{ minWidth: 0 }}>
              <span style={{ display: 'block', fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.55)' }}>One tap</span>
              <span style={{ display: 'block', marginTop: 4, fontFamily: t.MONO, fontSize: 15, fontWeight: 800, letterSpacing: '0.04em', textTransform: 'uppercase', color: '#38e0cc', textShadow: '0 0 12px rgba(56,224,204,0.4)' }}>Ate it as planned</span>
            </span>
            <span style={{ fontSize: 18, fontWeight: 800, color: '#38e0cc', flexShrink: 0 }}>✓</span>
          </button>
        )}
        {hasPlanned && dirty && (
          <button onClick={resetToPlan} style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: 8, width: '100%', marginTop: 14, textAlign: 'left', padding: '10px 12px', borderRadius: 5, border: '1px solid rgba(244,237,224,0.25)', background: 'transparent', cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: 'rgba(244,237,224,0.7)' }}>
            <span aria-hidden style={{ fontSize: 13, color: '#38e0cc' }}>↺</span>
            <span>Adjusted — reset to plan</span>
          </button>
        )}
        {/* The live tally — THIS MEAL + the day, glowing (updates as the
            record below is corrected) */}
        <div style={{ position: 'relative', marginTop: 16, borderTop: '1px solid rgba(244,237,224,0.14)', paddingTop: 11, display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12, flexWrap: 'wrap' }}>
          <span style={{ fontFamily: t.MONO, fontSize: 22, fontWeight: 800, color: '#38e0cc', fontVariantNumeric: 'tabular-nums', textShadow: '0 0 14px rgba(56,224,204,0.4)' }}>{kcal}<span style={{ fontSize: 8.5, color: 'rgba(244,237,224,0.35)', textShadow: 'none' }}> KCAL</span></span>
          <span style={{ fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.1em', color: 'rgba(244,237,224,0.55)', fontVariantNumeric: 'tabular-nums' }}>{P}P · {C}C · {F}F</span>
          <span style={{ fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.08em', color: 'rgba(244,237,224,0.55)', fontVariantNumeric: 'tabular-nums' }}>DAY {dayCal}<span style={{ color: 'rgba(244,237,224,0.35)' }}> / {CAL_GOAL != null ? CAL_GOAL : '—'}</span></span>
        </div>
      </div>
      {/* The seam — the ONE band/paper boundary */}
      <div aria-hidden style={{ height: 3, background: `linear-gradient(90deg, ${teal}, ${bsTHexA(teal, 0.15)})` }} />

      {/* REGISTER 1 — Correct the record */}
      <LedgerHead label="Correct the record" />
      <div style={{ padding: `12px ${t.padX}px 4px` }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
          <span style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK50 }}>Portion</span>
          <span style={{ fontFamily: t.DISPLAY, fontSize: 24, fontWeight: 700, color: teal, fontVariantNumeric: 'tabular-nums' }}>{portion.toFixed(2)} <span style={{ fontSize: 13, color: t.INK50 }}>×</span></span>
        </div>
        <input type="range" min={0.25} max={2} step={0.25} value={portion} onChange={(e) => setPortion(parseFloat(e.target.value))} style={{ width: '100%', marginTop: 10, accentColor: teal, cursor: 'pointer' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.1em', color: t.INK50, marginTop: 2 }}>
          <span>¼</span><span>½</span><span>1×</span><span>1½</span><span>2×</span>
        </div>

        <div style={{ marginTop: 18, fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: t.INK50 }}>Ingredients · tap to toggle</div>
        <div style={{ marginTop: 4 }}>
          {ings.map((x, i) => (
            <div key={x.id || x.name} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '13px 0', borderBottom: i === ings.length - 1 ? 0 : `1px solid ${t.HAIR}` }}>
              <button onClick={() => toggle(i)} aria-pressed={x.on} aria-label={`${x.on ? 'Exclude' : 'Include'} ${x.name}`} style={{ width: 22, height: 22, flexShrink: 0, borderRadius: 4, border: `1px solid ${x.on ? teal : t.RULE}`, background: x.on ? teal : 'transparent', color: '#04201d', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 800 }}>{x.on ? '✓' : ''}</button>
              <div style={{ flex: 1, minWidth: 0, opacity: x.on ? 1 : 0.4 }}>
                <div style={{ fontFamily: t.DISPLAY, fontSize: 15, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em' }}>{x.name}</div>
                <div style={{ marginTop: 2, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>{x.qty} · {Math.round(x.kcal * portion)} kcal · {Math.round(x.p * portion)}P</div>
              </div>
              <button onClick={() => openEditIng(i)} style={{ flexShrink: 0, background: 'transparent', border: 0, cursor: 'pointer', fontFamily: t.MONO, fontSize: 8.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.RUST }}>Edit</button>
            </div>
          ))}
        </div>
        <button onClick={() => setShowAddFood(true)} style={{ marginTop: 12, width: '100%', padding: '12px', borderRadius: t.RADIUS_SM, border: `1px dashed ${t.RULE}`, background: 'transparent', color: t.INK70, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase' }}>＋ Add — search foods or enter manually</button>
      </div>

      {/* REGISTER 2 — Dispatch to coach (hidden when signed in with no linked coach) */}
      {(coach || !signedIn) && (
        <>
          <LedgerHead label={`Dispatch to ${coachName}`} accent={coachAccent} extra={<span style={{ fontFamily: t.MONO, fontSize: 8, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50 }}>Optional</span>} />
          <div style={{ padding: `10px ${t.padX}px 4px` }}>
            <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={2} placeholder="Felt a bit hungry still · swapped rice for sweet potato…" style={{ width: '100%', boxSizing: 'border-box', padding: '10px 0 9px', border: 0, borderBottom: `2px solid ${bsTHexA(t.INK, 0.28)}`, borderRadius: 0, background: 'transparent', color: t.INK, fontFamily: t.DISPLAY, fontSize: 14, fontWeight: 500, fontStyle: 'italic', outline: 'none', resize: 'vertical' }} />
            <div style={{ marginTop: 8, display: 'flex', gap: 8 }}>
              {[['photo', '⊡ Photo', photoOpen, () => { setPhotoOpen((v) => !v); setVoiceOpen(false); }, !!photo],
                ['voice', '● Voice', voiceOpen, () => { setVoiceOpen((v) => !v); setPhotoOpen(false); }, !!voiceMemo]].map(([k, label, open, onTap, attached]) => (
                <button key={k} onClick={onTap} aria-pressed={open} style={{ flex: 1, minHeight: 44, padding: '10px 8px', borderRadius: t.RADIUS_SM, cursor: 'pointer', border: `1px solid ${open || attached ? coachAccent : t.RULE}`, background: open ? `${coachAccent}14` : 'transparent', color: open || attached ? t.INK : t.INK50, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>
                  {label}{attached ? ' ✓' : ''}
                </button>
              ))}
            </div>

            {photoOpen && (
              <div style={{ marginTop: 10 }}>
                <input ref={photoCamRef} type="file" accept="image/*" capture="environment" onChange={onPhotoPick} style={{ display: 'none' }} />
                <input ref={photoLibRef} type="file" accept="image/*" onChange={onPhotoPick} style={{ display: 'none' }} />
                {photo ? (
                  <div style={{ borderRadius: 16, border: `1px solid ${t.RULE}`, overflow: 'hidden', position: 'relative' }}>
                    <img src={photo.url} alt="Your meal" style={{ display: 'block', width: '100%', maxHeight: 280, objectFit: 'cover' }} />
                    <button onClick={removePhoto} aria-label="Remove photo" style={{ position: 'absolute', top: 10, right: 10, width: 30, height: 30, borderRadius: 999, border: 0, background: 'rgba(0,0,0,0.55)', color: '#fff', cursor: 'pointer', fontSize: 16, fontWeight: 700, lineHeight: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>×</button>
                    <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '14px 12px 8px', background: 'linear-gradient(transparent, rgba(0,0,0,0.62))', color: '#fff', fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700 }}>Sends to {coachName} when you log</div>
                  </div>
                ) : (
                  <div style={{ borderRadius: 16, border: `1px solid ${t.RULE}`, background: t.PAPER2, padding: '34px 16px', textAlign: 'center' }}>
                    <div style={{ fontSize: 30 }}>⊡</div>
                    <div style={{ marginTop: 10, fontFamily: t.DISPLAY, fontSize: 18, fontWeight: 700, color: t.INK, letterSpacing: '-0.02em' }}>Snap or upload</div>
                    <div style={{ marginTop: 6, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{coachName} reviews your plate</div>
                  </div>
                )}
                <div style={{ marginTop: 12, display: 'flex', gap: 10 }}>
                  <button onClick={() => photoCamRef.current && photoCamRef.current.click()} style={{ flex: 1, padding: '13px', borderRadius: t.RADIUS_SM, border: 0, background: teal, color: '#04201d', cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>{photo ? 'Retake' : 'Take photo'}</button>
                  <button onClick={() => photoLibRef.current && photoLibRef.current.click()} style={{ flex: 1, padding: '13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>Upload</button>
                </div>
              </div>
            )}

            {voiceOpen && (
              <div style={{ marginTop: 10 }}>
                <div style={{ display: 'flex', gap: 6, marginBottom: 14 }}>
                  {[['text', 'Voice to text'], ['audio', 'Voice record']].map(([k, l]) => {
                    const on = voiceCapture === k;
                    return (
                      <button key={k} onClick={() => { if (voiceState !== 'idle') return; setVoiceCapture(k); setVoiceError(''); }} aria-pressed={on} style={{
                        flex: 1, padding: '9px 8px', borderRadius: t.RADIUS_SM, cursor: 'pointer',
                        border: `1px solid ${on ? teal : t.RULE}`, background: on ? `${teal}14` : 'transparent',
                        color: on ? t.INK : t.INK50, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase',
                      }}>{l}</button>
                    );
                  })}
                </div>
                <div style={{ borderRadius: 16, border: `1px solid ${t.RULE}`, background: t.PAPER2, padding: '24px 16px', textAlign: 'center' }}>
                  {voiceCapture === 'audio' && voiceMemo && voiceState !== 'recording' ? (
                    <div>
                      <audio src={voiceMemo.url} controls style={{ width: '100%' }} />
                      <div style={{ marginTop: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 14 }}>
                        <span style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50, fontWeight: 700 }}>Memo · {fmtSecs(voiceMemo.secs)}</span>
                        <button onClick={removeMemo} style={{ background: 'transparent', border: 0, color: t.RUST, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase' }}>Remove</button>
                      </div>
                      <div style={{ marginTop: 6, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.INK50 }}>Sent to your coach with this log</div>
                    </div>
                  ) : (
                    <>
                      <button onClick={toggleVoice} disabled={voiceState === 'processing'} aria-label={voiceState === 'recording' ? 'Stop recording' : 'Start speaking'} style={{
                        width: 96, height: 96, margin: '0 auto', borderRadius: 999, border: 0, padding: 0,
                        cursor: voiceState === 'processing' ? 'default' : 'pointer',
                        opacity: voiceState === 'processing' ? 0.6 : 1,
                        background: `radial-gradient(circle, ${teal} 0%, ${teal} 32%, ${teal}22 33%, transparent 70%)`,
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        animation: voiceState === 'recording' ? 'bs-blink 1.1s ease-in-out infinite' : 'none',
                      }}>
                        {voiceState === 'recording'
                          ? <span style={{ width: 24, height: 24, borderRadius: 6, background: '#04201d', display: 'block' }} />
                          : <span style={{ width: 14, height: 14, borderRadius: 999, background: '#04201d', display: 'block' }} />}
                      </button>
                      <div style={{ marginTop: 16, fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 15, fontWeight: 600, color: t.INK70, minHeight: 21, padding: `0 ${t.padX}px` }}>
                        {voiceState === 'recording' ? 'Listening…' : voiceState === 'processing' ? 'Transcribing…' : (voiceCapture === 'text' ? 'Speak — it’s added to your note' : 'Record a memo for your coach')}
                      </div>
                      <div style={{ marginTop: 8, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.16em', textTransform: 'uppercase', color: voiceError ? t.RUST : t.INK50, fontWeight: 600 }}>
                        {voiceError ? voiceError : voiceState === 'recording' ? `Tap to stop · ${fmtSecs(voiceSecs)}` : voiceState === 'processing' ? 'Working…' : 'Tap to speak'}
                      </div>
                    </>
                  )}
                </div>
              </div>
            )}
          </div>
        </>
      )}

      {/* THE TALLY station dissolved — the band carries THIS MEAL + the day
          live (Cockpit/Split spec); no duplicated register on paper. */}

      {/* Reserve height for the sticky ledger bar so content never hides behind it. */}
      <div style={{ height: 96 }} />

      {/* Sticky ledger bar — the always-reachable, honest log action. */}
      {createPortal((
        <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, zIndex: 5200, background: t.PAPER2, borderTop: `1px solid ${t.RULE}`, boxShadow: '0 -8px 22px rgba(0,0,0,0.12)', padding: `12px ${t.padX}px calc(14px + env(safe-area-inset-bottom, 0px))`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
          <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.1em', color: t.INK50, fontVariantNumeric: 'tabular-nums' }}>{kcal} KCAL · {P}P</span>
          <button onClick={doLog} disabled={signedIn && kcal <= 0} style={{ flex: '0 0 auto', minHeight: 44, padding: '0 18px', borderRadius: t.RADIUS_SM, clipPath: 'polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%)', border: 0, cursor: (signedIn && kcal <= 0) ? 'default' : 'pointer', opacity: (signedIn && kcal <= 0) ? 0.45 : 1, background: t.INK, color: t.PAPER, fontFamily: t.MONO, fontSize: 10.5, fontWeight: 800, letterSpacing: '0.06em', textTransform: 'uppercase' }}>{ctaLabel}</button>
        </div>
      ), (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || document.body)}

      {/* Add-food sheet — search recents or enter manually (replaces the old SEARCH tab). */}
      {showAddFood && (() => {
        const FOODS = [
          { name: 'Chipotle · chicken bowl', qty: '1 bowl',  kcal: 560, p: 42, c: 52, f: 18 },
          { name: 'Whey isolate',            qty: '1 scoop', kcal: 120, p: 25, c: 3,  f: 1  },
          { name: 'Jasmine rice',            qty: '1 cup',   kcal: 205, p: 4,  c: 45, f: 0  },
          { name: 'Grilled chicken breast',  qty: '6 oz',    kcal: 280, p: 52, c: 0,  f: 8  },
          { name: 'Greek yogurt · plain',    qty: '1 cup',   kcal: 150, p: 25, c: 9,  f: 4  },
          { name: 'Banana',                  qty: '1 medium',kcal: 105, p: 1,  c: 27, f: 0  },
          { name: 'Almonds',                 qty: '1 oz',    kcal: 165, p: 6,  c: 6,  f: 14 },
          { name: 'Olive oil',               qty: '1 tbsp',  kcal: 120, p: 0,  c: 0,  f: 14 },
        ];
        const q = foodQuery.trim().toLowerCase();
        // Signed-in members search the REAL hybrid food database (FDC + OFF via
        // /api/nutrition/food-search) with real user_goals recents; the demo
        // list (search + recents) is the signed-out preview only.
        const rows = q ? FOODS.filter(f => f.name.toLowerCase().includes(q)) : FOODS.slice(0, 3);
        const addFood = (f) => { setIngs(arr => [...arr, { id: bsIngId(), name: f.name, qty: f.qty, kcal: f.kcal, p: f.p, c: f.c, f: f.f, on: true }]); window.__bsToast?.(`Added ${f.name}`, 'ok'); setShowAddFood(false); };
        // Live handlers — ＋ adds the provider's default serving directly; a tap
        // on the row body opens the ingredient editor prefilled so the portion
        // can be adjusted before it lands. Adds persist to real recents
        // (best-effort — a failed write never blocks the add).
        const addLiveFood = (f) => {
          setIngs(arr => [...arr, { id: bsIngId(), name: f.name, qty: f.qty || '1 serving', kcal: Math.round(Number(f.kcal) || 0), p: Math.round(Number(f.p) || 0), c: Math.round(Number(f.c) || 0), f: Math.round(Number(f.f) || 0), on: true }]);
          window.__bsToast?.(`Added ${f.name}`, 'ok');
          setShowAddFood(false);
          rememberFood(f);
        };
        const editLiveFood = (f) => {
          setShowAddFood(false);
          // fromSearch: the editor's save persists this add to recents too.
          setEditIng({ index: null, fromSearch: true, name: f.name, qty: f.qty || '', kcal: String(Math.round(Number(f.kcal) || 0)), p: String(Math.round(Number(f.p) || 0)), c: String(Math.round(Number(f.c) || 0)), f: String(Math.round(Number(f.f) || 0)) });
        };
        // Barcode → one OFF product → the prefilled ingredient editor (the
        // member confirms the portion before it lands — same contract as a
        // search-row tap). Honest states for invalid / not-found / outage.
        // Stale-guarded like the text search: a new lookup (or the sheet
        // closing) ABORTS the prior request, and every post-await update is
        // gated on this call still being the live one — a late response can
        // never reopen a dismissed sheet or win over a newer code.
        const lookupBarcode = async (raw) => {
          const code = bsValidBarcode(raw);
          if (!code) { setBarcodeStatus('invalid'); return; }
          try { barcodeCtlRef.current?.abort(); } catch (e) {}
          const ctl = new AbortController();
          barcodeCtlRef.current = ctl;
          setBarcodeStatus('looking');
          setBarcodeMode((m) => (m === 'scan' ? null : m)); // a scanned hit stops the camera
          try {
            const data = await window.ShapeFoodSearch?.barcode?.(code, { signal: ctl.signal });
            if (ctl.signal.aborted || barcodeCtlRef.current !== ctl) return;
            const row = data && Array.isArray(data.results) ? data.results[0] : null;
            if (row) { setBarcodeStatus('idle'); setBarcodeDigits(''); setBarcodeMode(null); editLiveFood(row); return; }
            setBarcodeStatus(data && data.unavailable ? 'error' : 'notfound');
          } catch (e) {
            if (ctl.signal.aborted || barcodeCtlRef.current !== ctl) return;
            setBarcodeStatus('error');
          }
        };
        const searching = foodQuery.trim().length >= 2;
        const liveRows = searching ? (foodResults || []) : (foodRecents || []);
        const liveStatus = foodStatus === 'searching' ? 'Searching…'
          : foodStatus === 'error' ? 'Can’t reach the food database — enter manually below'
          : searching ? `${liveRows.length} result${liveRows.length === 1 ? '' : 's'}`
          : (foodRecents === null || liveRows.length ? 'Recents' : 'No recents yet — search or enter manually');
        return createPortal((
          <div onClick={() => setShowAddFood(false)} style={{ position: 'absolute', inset: 0, zIndex: 6000, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end' }}>
            <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', background: t.PAPER, borderTopLeftRadius: 20, borderTopRightRadius: 20, borderTop: `1px solid ${t.RULE}`, padding: `18px ${t.padX}px calc(20px + env(safe-area-inset-bottom, 0px))`, boxShadow: '0 -16px 40px rgba(0,0,0,0.35)', maxHeight: '80%', overflowY: 'auto' }}>
              <div style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK50, marginBottom: 12 }}>Add food</div>
              {signedIn ? (
                <>
                  <input autoFocus value={foodQuery} onChange={(e) => setFoodQuery(e.target.value)} placeholder="Search foods & brands…" style={{ width: '100%', boxSizing: 'border-box', padding: '13px 14px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: t.PAPER2, color: t.INK, fontFamily: t.DISPLAY, fontSize: 15, outline: 'none' }} />
                  {/* Barcode (v2) — scan where BarcodeDetector exists (Chrome /
                      Android WebView); the manual digits entry everywhere
                      (iOS WebKit ships no BarcodeDetector). */}
                  <div style={{ marginTop: 10, display: 'flex', alignItems: 'center', gap: 18 }}>
                    {bsBarcodeScanSupported() && (
                      <button onClick={() => { setBarcodeStatus('idle'); setBarcodeMode(barcodeMode === 'scan' ? null : 'scan'); }} style={{ background: 'transparent', border: 0, padding: '6px 0', cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: barcodeMode === 'scan' ? teal : t.INK50 }}>▥ Scan barcode</button>
                    )}
                    <button onClick={() => { setBarcodeStatus('idle'); setBarcodeMode(barcodeMode === 'enter' ? null : 'enter'); }} style={{ background: 'transparent', border: 0, padding: '6px 0', cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: barcodeMode === 'enter' ? teal : t.INK50 }}># Enter barcode</button>
                    {barcodeMode && <button onClick={() => { setBarcodeMode(null); setBarcodeStatus('idle'); }} style={{ marginLeft: 'auto', background: 'transparent', border: 0, padding: '6px 0', cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50 }}>Cancel</button>}
                  </div>
                  {barcodeMode === 'scan' && <BSBarcodeScan teal={teal} onHit={(code) => lookupBarcode(code)} onFallback={() => setBarcodeMode('enter')} />}
                  {barcodeMode === 'enter' && (
                    <div style={{ marginTop: 8, display: 'flex', gap: 8 }}>
                      <input value={barcodeDigits} onChange={(e) => setBarcodeDigits(e.target.value.replace(/[^\d\s-]/g, ''))} onKeyDown={(e) => { if (e.key === 'Enter') lookupBarcode(barcodeDigits); }} inputMode="numeric" placeholder="Barcode digits (EAN / UPC)…" aria-label="Barcode digits" style={{ flex: 1, minWidth: 0, boxSizing: 'border-box', padding: '11px 13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: t.PAPER2, color: t.INK, fontFamily: t.MONO, fontSize: 14, outline: 'none' }} />
                      <button onClick={() => lookupBarcode(barcodeDigits)} disabled={barcodeStatus === 'looking'} style={{ flex: '0 0 auto', minHeight: 44, padding: '0 16px', borderRadius: t.RADIUS_SM, border: 0, background: teal, color: '#08221f', cursor: barcodeStatus === 'looking' ? 'default' : 'pointer', opacity: barcodeStatus === 'looking' ? 0.6 : 1, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase' }}>Look up</button>
                    </div>
                  )}
                  {barcodeStatus !== 'idle' && (
                    <div style={{ marginTop: 8, fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase', color: barcodeStatus === 'looking' ? t.INK50 : t.RUST }}>
                      {barcodeStatus === 'looking' ? 'Looking up…'
                        : barcodeStatus === 'invalid' ? 'That doesn’t read as a barcode — 8–14 digits'
                        : barcodeStatus === 'notfound' ? 'No match for that barcode — search or enter it manually'
                        : 'Can’t reach the food database — try again or enter manually'}
                    </div>
                  )}
                  <div style={{ marginTop: 14, fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: foodStatus === 'error' ? t.RUST : t.INK50 }}>{liveStatus}</div>
                  <div style={{ marginTop: 2 }}>
                    {liveRows.map((r, i) => (
                      <div key={r.id || `${r.name}-${i}`} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '4px 0', borderBottom: i === liveRows.length - 1 ? 0 : `1px solid ${t.HAIR}` }}>
                        <button onClick={() => editLiveFood(r)} style={{ flex: 1, minWidth: 0, minHeight: 44, textAlign: 'left', background: 'transparent', border: 0, padding: '9px 0', cursor: 'pointer' }}>
                          <div style={{ fontFamily: t.DISPLAY, fontSize: 15, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.name}</div>
                          <div style={{ marginTop: 2, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.brand ? `${r.brand} · ` : ''}{r.qty} · {r.kcal} kcal · {r.p}P</div>
                        </button>
                        <button onClick={() => addLiveFood(r)} aria-label={`Add ${r.name}`} style={{ flex: '0 0 auto', minWidth: 44, minHeight: 44, background: 'transparent', border: 0, color: teal, cursor: 'pointer', fontSize: 22, fontWeight: 700, lineHeight: 1 }}>＋</button>
                      </div>
                    ))}
                    {searching && foodStatus === 'done' && liveRows.length === 0 && <div style={{ padding: '16px 0', fontFamily: t.DISPLAY, fontSize: 14, color: t.INK50 }}>No matches for “{foodQuery.trim()}”.</div>}
                  </div>
                </>
              ) : (
                <>
                  <input autoFocus value={foodQuery} onChange={(e) => setFoodQuery(e.target.value)} placeholder="Search foods, brands, barcodes…" style={{ width: '100%', boxSizing: 'border-box', padding: '13px 14px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: t.PAPER2, color: t.INK, fontFamily: t.DISPLAY, fontSize: 15, outline: 'none' }} />
                  <div style={{ marginTop: 14, fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50 }}>{q ? `${rows.length} result${rows.length === 1 ? '' : 's'}` : 'Recents'}</div>
                  <div style={{ marginTop: 2 }}>
                    {rows.map((r, i) => (
                      <div key={r.name} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '13px 0', borderBottom: i === rows.length - 1 ? 0 : `1px solid ${t.HAIR}` }}>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontFamily: t.DISPLAY, fontSize: 15, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em' }}>{r.name}</div>
                          <div style={{ marginTop: 2, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>{r.qty} · {r.kcal} kcal · {r.p}P</div>
                        </div>
                        <button onClick={() => addFood(r)} aria-label={`Add ${r.name}`} style={{ flex: '0 0 auto', minWidth: 44, minHeight: 44, background: 'transparent', border: 0, color: teal, cursor: 'pointer', fontSize: 22, fontWeight: 700, lineHeight: 1 }}>＋</button>
                      </div>
                    ))}
                    {q && rows.length === 0 && <div style={{ padding: '16px 0', fontFamily: t.DISPLAY, fontSize: 14, color: t.INK50 }}>No matches for “{foodQuery.trim()}”.</div>}
                  </div>
                </>
              )}
              <button onClick={() => { setShowAddFood(false); openAddIng(); }} style={{ marginTop: 12, width: '100%', padding: '13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase' }}>Enter manually →</button>
            </div>
          </div>
        ), (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || document.body);
      })()}

      {/* Ingredient editor / add sheet */}
      {editIng && (() => {
        const inputStyle = { width: '100%', boxSizing: 'border-box', padding: '12px 13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: t.PAPER2, color: t.INK, fontFamily: t.DISPLAY, fontSize: 15, fontWeight: 500, outline: 'none' };
        return createPortal((
          <div onClick={() => setEditIng(null)} style={{ position: 'absolute', inset: 0, zIndex: 6000, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end' }}>
            <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', background: t.PAPER, borderTopLeftRadius: 20, borderTopRightRadius: 20, borderTop: `1px solid ${t.RULE}`, padding: `18px ${t.padX}px calc(20px + env(safe-area-inset-bottom, 0px))`, boxShadow: '0 -16px 40px rgba(0,0,0,0.35)' }}>
              <div style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.2em', textTransform: 'uppercase', color: t.INK50, marginBottom: 12 }}>{editIng.index == null ? 'Add ingredient' : 'Edit ingredient'}</div>
              <input autoFocus value={editIng.name} placeholder="Ingredient" onChange={(e) => setEditIngField('name', e.target.value)} style={inputStyle} />
              <input value={editIng.qty} placeholder="Portion · e.g. 1 cup" onChange={(e) => setEditIngField('qty', e.target.value)} style={{ ...inputStyle, marginTop: 8 }} />
              <div style={{ marginTop: 10, display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gap: 8 }}>
                {[['kcal', 'Kcal'], ['p', 'Protein'], ['c', 'Carbs'], ['f', 'Fat']].map(([k, l]) => (
                  <label key={k} style={{ display: 'block' }}>
                    <span style={{ display: 'block', fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50, fontWeight: 700, marginBottom: 4 }}>{l}</span>
                    <input value={editIng[k]} inputMode="numeric" placeholder="0" onChange={(e) => setEditIngField(k, e.target.value.replace(/[^0-9]/g, ''))} style={{ width: '100%', boxSizing: 'border-box', padding: '10px 6px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: t.PAPER2, color: t.INK, fontFamily: t.MONO, fontSize: 13, fontWeight: 700, outline: 'none', textAlign: 'center' }} />
                  </label>
                ))}
              </div>
              <div style={{ display: 'flex', gap: 8, marginTop: 16 }}>
                {editIng.index != null && <button onClick={deleteEditIng} style={{ padding: '13px 14px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RUST}`, background: 'transparent', color: t.RUST, cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase' }}>Remove</button>}
                <button onClick={() => setEditIng(null)} style={{ flex: 1, padding: '13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase' }}>Cancel</button>
                <button onClick={saveEditIng} style={{ flex: 1, padding: '13px', borderRadius: t.RADIUS_SM, border: 0, background: t.INK, color: t.PAPER, cursor: 'pointer', fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase' }}>Save</button>
              </div>
            </div>
          </div>
        ), (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || document.body);
      })()}
    </BSPage>
  );
}

// Retro-tighten past auto-posts when a Settings change makes the member's
// share level STRICTER (Share off, or profile → more private). Loosening never
// touches history. Shared by both preference-update handlers so the rule can't
// drift between them. Fire-and-forget.
function bsMaybeRetightenAutoPosts(prevPrefs, nextPrefs) {
  try {
    const ws = window.ShapeWorkoutShare;
    if (!ws) return;
    const before = ws.rule(prevPrefs); const after = ws.rule(nextPrefs);
    if (ws.rank[after] > ws.rank[before]) window.ShapeCommunity?.tightenAutoPosts?.(after);
  } catch (e) {}
}

// Live-row withdrawal is enforced by the MUTATION, not a listener (spec
// 2026-07-19): whichever device changes the setting resolves the new audience
// and acts on the member's own user_activity_live row directly — null audience
// → delete, tightened → restamp visibility. Works even when the broadcasting
// device is asleep; the shape:liveAudienceChanged event is only the LOCAL
// re-push. Returns {ok}; the caller must await and dispatch that event ONLY on
// success, or a failed withdrawal could be followed by a re-push that
// resurrects the row the member just tried to pull down.
//
// ACCEPTED RESIDUAL (TOCTOU, documented not hidden): the settings write and the
// row mutation are two operations, not one transaction. The bound: one retry,
// an honest toast on failure, no re-push on failure, and expiry caps the worst
// case. Folding both into a single serialized RPC would re-route the entire
// settings write path for that bound — declined at this scope.
async function bsRetightenLiveRow(nextPrefs) {
  try {
    const { bsLiveAudience } = await import('../services/liveProgress.mjs');
    const vis = bsLiveAudience(nextPrefs, false);
    const db = window.shapeDb; const uid = window.ShapeAuth?.getCachedState?.()?.user?.id;
    if (!db?.client || !uid) return { ok: false };
    const run = () => (!vis
      ? db.client.from('user_activity_live').delete().eq('user_id', uid)
      : db.client.from('user_activity_live').update({ visibility: vis }).eq('user_id', uid));
    const { error } = await run();
    if (error) {                                   // one retry, then honest failure
      const { error: e2 } = await run();
      if (e2) return { ok: false };
    }
    // Hand the RESOLVED audience back so the local re-push can use it directly.
    return { ok: true, visibility: vis };
  } catch (e) { return { ok: false }; }
}

// Shared by both preference-update handlers so the rule can't drift between
// them (the same reason bsMaybeRetightenAutoPosts is shared).
function bsOnShareSettingChanged(prevPrefs, nextPrefs) {
  bsMaybeRetightenAutoPosts(prevPrefs, nextPrefs);
  bsRetightenLiveRow(nextPrefs).then((r) => {
    if (r && r.ok) {
      // Carry the RESOLVED audience on the event. The re-push must NOT re-read
      // user_goals: saveUserGoals('client_settings', …) above is
      // fire-and-forget, so that read can still return the OLD doc and the
      // wider previous audience — resurrecting the row we just withdrew, with
      // its payload (a meal title) intact (Codex P1).
      try { window.dispatchEvent(new CustomEvent('shape:liveAudienceChanged', { detail: { visibility: r.visibility } })); } catch (e) {}
    } else {
      try { window.__bsToast?.('Live-sharing change didn\'t save — check your connection.', 'info'); } catch (e) {}
    }
  });
}

// ── Live home week ───────────────────────────────────────────────────────────
// Builds the home day-log / week-dots / up-next models from the REAL assigned
// plan (/api/client/plan — the same source the Train + Eat tabs read), so a
// member with an assigned program sees their actual week on home. Returns null
// shape pieces per day where nothing is assigned; callers fall back to the
// shared demo week only when NO plan exists at all.
function bsHomeLiveWeek(plan, t) {
  const monday = new Date(); monday.setHours(0, 0, 0, 0);
  monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7));
  // Slot assigned workouts onto the week (same rules as the Train deck).
  const wSlots = [null, null, null, null, null, null, null];
  const unscheduled = [];
  for (const w of ((plan.training && plan.training.workouts) || [])) {
    if (w.scheduledDate) {
      const dt = new Date(w.scheduledDate + 'T00:00:00');
      const idx = Math.round((dt - monday) / 86400000);
      if (idx >= 0 && idx <= 6 && !wSlots[idx]) { wSlots[idx] = w; continue; }
    }
    unscheduled.push(w);
  }
  for (let i = 0; i < 7 && unscheduled.length; i++) if (!wSlots[i]) wSlots[i] = unscheduled.shift();
  // Slot meal-plan days (same rules as the Eat menu).
  const mSlots = [null, null, null, null, null, null, null];
  const mSeq = [];
  for (const d of ((plan.meals && plan.meals.days) || [])) {
    if (Number.isInteger(d.dow) && d.dow >= 0 && d.dow <= 6 && !mSlots[d.dow]) mSlots[d.dow] = d;
    else mSeq.push(d);
  }
  for (let i = 0; i < 7 && mSeq.length; i++) if (!mSlots[i]) mSlots[i] = mSeq.shift();

  const mealTimes = (typeof window !== 'undefined' && window.ShapeMealTimes && window.ShapeMealTimes.get()) || {};
  const dots = [], workoutByIdx = [], mealsByIdx = [];
  for (let i = 0; i < 7; i++) {
    const w = wSlots[i];
    let wk = null;
    if (w) {
      const moves = (w.exercises || []).map((e) => ({
        name: e.name,
        scheme: [[e.sets, e.reps].filter(Boolean).join(' × '), e.rest].filter(Boolean).join(' · '),
        load: e.load || '',
      }));
      const meta = [w.durationMin ? `${w.durationMin} min` : null, `${moves.length} move${moves.length === 1 ? '' : 's'}`].filter(Boolean).join(' · ');
      wk = { time: w.time || '—', kind: 'TRN', title: w.title || 'Workout', sub: meta, detail: { moves, meta, note: w.description || '' } };
    }
    workoutByIdx.push(wk);
    const md = mSlots[i];
    const recs = [];
    if (md && Array.isArray(md.meals)) {
      md.meals.forEach((meal, j) => {
        const slot = String(meal.slot || 'MEAL').toUpperCase();
        const time = meal.time || mealTimes[slot === 'BFAST' ? 'BREAKFAST' : slot] || '';
        const sub = [meal.kcal ? `${meal.kcal} kcal` : null, meal.p ? `${meal.p}P` : null].filter(Boolean).join(' · ');
        recs.push({
          id: `home-live-${i}-${j}`, time, tag: slot.slice(0, 5), tagColor: t.AMBER,
          title: meal.title || 'Meal', sub: sub || '', kcal: meal.kcal || 0, p: meal.p || 0, c: meal.c || 0, f: meal.f || 0,
          prep: meal.prep || '—', portion: meal.portion || '1 plate', score: meal.score || '—',
          hero: meal.hero || meal.brief || `${meal.title || 'Meal'}.`, brief: meal.brief || '',
          ingredients: (meal.ingredients || []).map((ing) => ({ n: ing.qty || '', m: ing.name || '', k: ing.kcal != null ? `${ing.kcal} kcal` : '' })),
          steps: meal.steps || [], coachNote: meal.coachNote || '',
          // The plan's OWN assigning nutritionist — the meal share's honest
          // attribution source (review P2: the DM-thread coach can be a
          // different person, a trainer, or unresolved at tap time).
          coach: (plan.meals && plan.meals.coach) || '',
        });
      });
    }
    mealsByIdx.push(recs);
    const ds = [];
    if (w) ds.push(t.AMBER);
    if (recs.length) ds.push(t.BLUE);
    dots.push(ds);
  }
  return {
    dots, workoutByIdx, mealsByIdx,
    hasTraining: !!(plan.training && plan.training.hasPlan),
    hasMeals: !!(plan.meals && plan.meals.hasPlan),
  };
}

function BSClientHome({ onProfile, sheet, goCalendar, goRadio, goTrain, goEat = () => {}, goMarket, goScore, goChat = () => {}, goIntegrations, tweaks = {}, setTweak = () => {} }) {
  const t = useBS();
  const tr = useShapeTr();
  const bsHomeProgram = useBSProgram();
  // Real current week, computed live so the home reflects today (not demo dates).
  // Monday-first index 0..6; weekDates = the seven dates of this calendar week.
  // Weekday/month tokens follow the selected UI language (i18n date-locale rule);
  // the composed dateline layout is preserved.
  const _dateLoc = bsDateLocale();
  const _dowShort = (d) => d.toLocaleDateString(_dateLoc, { weekday: 'short' });
  const _monShort = (d) => d.toLocaleDateString(_dateLoc, { month: 'short' });
  const _now = new Date();
  const todayIdx = (_now.getDay() + 6) % 7;
  const weekDates = (() => {
    const mon = new Date(_now); mon.setHours(0, 0, 0, 0); mon.setDate(_now.getDate() - todayIdx);
    return Array.from({ length: 7 }, (_, i) => { const d = new Date(mon); d.setDate(mon.getDate() + i); return d; });
  })();
  const isoWeek = (() => {
    const d = new Date(Date.UTC(_now.getFullYear(), _now.getMonth(), _now.getDate()));
    const day = (d.getUTCDay() + 6) % 7;
    d.setUTCDate(d.getUTCDate() - day + 3);
    const firstThu = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
    return 1 + Math.round(((d - firstThu) / 86400000 - 3 + ((firstThu.getUTCDay() + 6) % 7)) / 7);
  })();
  const nowTime = `${String(_now.getHours()).padStart(2, '0')}:${String(_now.getMinutes()).padStart(2, '0')}`;
  const fmtDate = (idx) => `${_monShort(weekDates[idx])} ${weekDates[idx].getDate()}`;
  // The slate's NOW tick tracks the wall clock while Home stays open — a
  // once-a-minute state tick (same-value setState bails out, so off-minute
  // firings are free). Render-time `_now` alone goes stale between renders.
  const [bsNowMin, setBsNowMin] = useStateBSC(_now.getHours() * 60 + _now.getMinutes());
  React.useEffect(() => {
    const id = setInterval(() => { const d = new Date(); setBsNowMin(d.getHours() * 60 + d.getMinutes()); }, 60000);
    return () => clearInterval(id);
  }, []);

  // The REAL assigned plan (same /api/client/plan the Train + Eat tabs read).
  // When any plan exists the day log / dots / up-next cards build from it;
  // the shared demo week remains the signed-out / no-plan fallback.
  const [livePlan, setLivePlan] = useStateBSC(null);
  React.useEffect(() => {
    let on = true;
    if (window.ShapePlan?.get) {
      window.ShapePlan.get().then((p) => {
        if (on && p && ((p.training && p.training.hasPlan) || (p.meals && p.meals.hasPlan))) setLivePlan(p);
      }).catch(() => {});
    }
    return () => { on = false; };
  }, []);
  // Signed in with no assigned plan → an EMPTY week (no workouts/meals/dots), NOT
  // the demo week. There are no coaches on Shape yet, so a real account shows its
  // real (empty) plan; the demo week is only the signed-out preview.
  const bsHomeSignedIn = !!(typeof window !== 'undefined' && window.ShapeAuth?.getCachedState?.()?.user?.id);
  const liveWeek = React.useMemo(() => {
    if (livePlan) return bsHomeLiveWeek(livePlan, t);
    if (bsHomeSignedIn) return bsHomeLiveWeek({ training: { hasPlan: false, workouts: [] }, meals: { hasPlan: false, days: [] } }, t);
    return null;
  }, [livePlan, bsHomeSignedIn, t]);

  const [selIdx, setSelIdx] = useStateBSC(todayIdx); // selected weekday 0..6 (today by default)
  // "Up next" follows the day you tap in the week strip (not just today).
  // Once ANY live plan exists every card follows it — a demo workout next to a
  // live day log would claim a session that isn't assigned.
  const selWorkout = liveWeek ? liveWeek.workoutByIdx[selIdx] : bsClientWorkoutForDay(selIdx);
  const _selDelta = selIdx - todayIdx;
  const upNextLabel = _selDelta === 0 ? tr('home:when.today', { defaultValue: 'Today' }) : _selDelta === 1 ? tr('home:when.tomorrow', { defaultValue: 'Tomorrow' }) : _selDelta === -1 ? tr('home:when.yesterday', { defaultValue: 'Yesterday' })
    : weekDates[selIdx].toLocaleDateString(_dateLoc, { weekday: 'long' });
  const [mealLogged, setMealLogged] = useStateBSC({});      // meal id → logged this session
  const [loggingMealId, setLoggingMealId] = useStateBSC(null); // meal that opened the logger
  const [mealToLog, setMealToLog] = useStateBSC(null); // the meal object being logged → real title/macros/time into the logger
  const [stepsHistory, setStepsHistory] = useStateBSC(false); // STEPS door → BSStepsHistory overlay (Home now owns this; BSStepsCard's own copy was deleted with its mount)
  // Hoisted OUT of the render body's door-shelf IIFE — useBSStepsToday() is a
  // React hook (uses useStateBSC/useBSStepGoal internally) and must be called
  // unconditionally at the top level, never inside JSX below the early-return
  // overlays. Step 3's shelf JSX reads this const directly.
  const stepsToday = useBSStepsToday();
  const [previewMeal, setPreviewMeal] = useStateBSC(null);
  const [weekStat, setWeekStat] = useStateBSC(null); // tapped Week-totals card → detail sheet
  const [showWorkoutPreview, setShowWorkoutPreview] = useStateBSC(false);
  const [showLogMeal, setShowLogMeal] = useStateBSC(false);
  const [habitsPage, setHabitsPage] = useStateBSC(false);
  const [goalsPage, setGoalsPage] = useStateBSC(false);
  const [todayPage, setTodayPage] = useStateBSC(false);   // the daily check-in + hydration page
  // Engine-driven top move — the signal engine's single highest-value action for
  // the signed-in client today (check-in overdue · streak at risk · food gap ·
  // goal slip · score drop). Honest: only a real flag from the live self record;
  // null otherwise, and the plan-based moves below lead instead. {key, reason}.
  const [engineFlag, setEngineFlag] = useStateBSC(null);
  // THE CYCLE — Home's ONLY cycle input, and it never names it (doctrine:
  // plain cycle language lives on cycle surfaces alone). Read here, spent as a
  // neutral recovery note on the day's directive.
  const { optIn: cycleOptIn } = useBSCycleSettings();
  const { cycle: cycleNow } = useBSCycleDerived(cycleOptIn);
  React.useEffect(() => {
    let on = true;
    (async () => {
      try {
        const S = (typeof window !== 'undefined') && window.ShapeSignals;
        if (!S || !S.selfRecord || !S.directive) return;
        const rec = await S.selfRecord();
        if (!on || !rec) return;
        // The ONE directive (cross-domain — incl. a coach-flagged sleep lever),
        // grounded in real signals. Lead with it only when there's a real lever.
        const dir = S.directive(rec);
        setEngineFlag(dir && dir.action && dir.lever && dir.lever !== 'none' && dir.verdict !== '—' ? dir : null);
      } catch (e) { /* honest: no engine move */ }
    })();
    return () => { on = false; };
  }, []);
  const [homeProgressPage, setHomeProgressPage] = useStateBSC(false);
  const [habitFlash, setHabitFlash] = useStateBSC(null); // { name, pts } — transient credit after checking a habit
  const habitFlashTimer = React.useRef(null);
  const [checkinPage, setCheckinPage] = useStateBSC(false);
  const [checkinDue, setCheckinDue] = useStateBSC(false);
  // Weekly check-in nudge — due when a signed-in client has no row this week.
  React.useEffect(() => {
    const uid = window.ShapeAuth?.getCachedState?.()?.user?.id;
    if (!uid || !window.ShapeCheckins) return undefined;
    let on = true;
    window.ShapeCheckins.mine(1).then((rows) => {
      if (!on) return;
      const wk = window.ShapeCheckins.weekOf();
      setCheckinDue(!(rows || []).some((r) => String(r.week_of) === wk));
    }).catch(() => {});
    return () => { on = false; };
  }, []);
  const [showLogActivity, setShowLogActivity] = useStateBSC(false);
  const [showMood, setShowMood] = useStateBSC(false);
  const [coachFeed, setCoachFeed] = useStateBSC({ banners: [], items: [] });
  const [ticker, setTicker] = useStateBSC(null);
  // Which ticker metrics to show + their order — edited in Settings, saved to profile.
  const [tickerPrefs, setTickerPrefs] = useStateBSC({ hidden: [], order: null });
  React.useEffect(() => {
    if (!(window.shapeDb && window.shapeDb.getUserGoals)) return undefined;
    let alive = true;
    window.shapeDb.getUserGoals('client_ticker').then(s => {
      if (alive && s && typeof s === 'object') setTickerPrefs({ hidden: Array.isArray(s.hidden) ? s.hidden : [], order: Array.isArray(s.order) ? s.order : null });
    }).catch(() => {});
    return () => { alive = false; };
  }, []);
  const [analytics, setAnalytics] = useStateBSC(null);
  // The Energy card reads the user's active goal (nutrition + training prefs)
  // and reframes the same balance into one of three states. Default 'maintain'.
  const [energyGoal, setEnergyGoal] = useStateBSC('maintain');
  React.useEffect(() => {
    let cancelled = false;
    if (!(window.shapeDb && window.shapeDb.getUserGoals)) return undefined;
    Promise.all([
      window.shapeDb.getUserGoals('client_nutrition_prefs').catch(() => ({})),
      window.shapeDb.getUserGoals('client_training_prefs').catch(() => ({})),
    ]).then(([np, tp]) => {
      if (cancelled) return;
      const raw = `${(np && np.primary_goal) || ''} ${(tp && tp.primary_goal) || (tp && tp.goal) || ''}`.toLowerCase();
      const goal = /fat ?loss|cut|lean|weight ?loss|shred/.test(raw) ? 'cut'
        : /hypertroph|build|bulk|mass|muscle|strength|gain/.test(raw) ? 'build'
        : 'maintain';
      setEnergyGoal(goal);
    });
    return () => { cancelled = true; };
  }, []);

  // Live focus banner + pushed items the coach sent. Initial pull, then a
  // Supabase Realtime subscription on coach_focus_banners / coach_pushed_items
  // (filtered to this user's rows via RLS) re-fetches the moment the coach
  // hits Send / Add — banner / today's list update without a pull-to-refresh.
  React.useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        if (!window.ShapeCoachFeed || typeof window.ShapeCoachFeed.fetch !== 'function') return;
        const feed = await window.ShapeCoachFeed.fetch();
        if (!cancelled && feed) setCoachFeed(feed);
      } catch {}
    };
    load();
    const unsubscribe = (window.ShapeCoachFeed && typeof window.ShapeCoachFeed.subscribe === 'function')
      ? window.ShapeCoachFeed.subscribe(() => { if (!cancelled) load(); })
      : () => {};
    return () => {
      cancelled = true;
      try { unsubscribe(); } catch {}
    };
  }, []);

  // Hydrate the masthead ticker from /api/client/analytics — latest snapshot
  // (calories, protein, sleep, HRV, RHR, weight). Falls back to the demo
  // values when the API returns nothing (signed-out / brand-new account).
  const refreshAnalytics = React.useCallback(() => {
    // Try the authenticated helper first (sends Bearer in native). If it yields
    // nothing — e.g. the helper's own guards, or demo mode — fall back to a
    // plain same-origin fetch, which authenticates via the bridged cookie on
    // /m/. This covers both the native shell and the in-browser /m/ preview.
    const viaHelper = window.ShapeAnalytics?.get ? window.ShapeAnalytics.get() : Promise.resolve(null);
    Promise.resolve(viaHelper)
      .then(d => {
        if (d) return d;
        return fetch('/api/client/analytics', { credentials: 'same-origin', cache: 'no-store' }).then(r => (r.ok ? r.json() : null));
      })
      .then(d => { if (d) { if (d.ticker) setTicker(d.ticker); setAnalytics(d); } })
      .catch(() => {});
  }, []);
  React.useEffect(() => { refreshAnalytics(); }, [refreshAnalytics]);

  // Today's Shape Score additions for the home "Score" chip. Sums the score
  // ledger entries earned *today* (local day) so the chip reflects what's been
  // added so far this day and grows as the day goes on. null = not loaded /
  // demo, in which case the chip keeps its sample value.
  const [ptsByDate, setPtsByDate] = useStateBSC(null); // dateString → points earned that day (live ledger)
  React.useEffect(() => {
    let cancelled = false;
    fetch('/api/client/score', { credentials: 'same-origin', cache: 'no-store' })
      .then(r => (r.ok ? r.json() : null))
      .then(d => {
        if (cancelled || !d || !Array.isArray(d.recent)) return;
        const map = {};
        d.recent.forEach(e => { if (e && e.earned_at) { const k = new Date(e.earned_at).toDateString(); map[k] = (map[k] || 0) + (Number(e.delta) || 0); } });
        setPtsByDate(map);
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  // Per-day logs + week-strip dots are both derived from the SHARED client demo
  // week (bsClientWeekDemo.js) — the same source the month calendar uses — so the
  // home week strip and the calendar always show the same workouts/consults/meals
  // for a given weekday. Keyed Mon..Sun → 20..26 to ride the live week.
  const BS_KIND_COLOR = { TRN: t.AMBER, MEAL: t.BLUE, CHK: t.GREEN, CON: t.RUST, REST: t.INK50 };
  const DAY_LOGS = {};
  BS_CLIENT_WEEK_DEMO.forEach((day, idx) => {
    DAY_LOGS[20 + idx] = day.map((it, i) => ({
      time: it.time, tag: it.kind, tagColor: BS_KIND_COLOR[it.kind] || t.INK50,
      title: it.title, sub: it.sub, state: it.state, last: i === day.length - 1,
    }));
  });
  const WEEK_DOTS_BY_IDX = BS_CLIENT_WEEK_DEMO.map((day) => {
    const kinds = new Set(day.map((it) => it.kind));
    return BS_CLIENT_WEEK_DOT_ORDER.filter((k) => kinds.has(k)).map((k) => BS_KIND_COLOR[k]);
  });
  const selDay = weekDates[selIdx].getDate(); // day-of-month for display strings
  const dataDay = 20 + selIdx;
  // Every meal for the selected day, as full preview records — each renders as
  // its own agenda card (the Day Log list is gone). Live = the assigned meal
  // plan; demo rows only when no plan exists.
  const selMeals = (() => {
    if (liveWeek) return liveWeek.mealsByIdx[selIdx] || [];
    const rows = (DAY_LOGS[dataDay] || []).filter((r) => r.tag === 'MEAL');
    return rows.map((row, j) => {
      const sub = row.sub || '';
      const kcal = parseInt(((sub.match(/(\d[\d,]*)\s*kcal/i) || [])[1] || '0').replace(/,/g, ''), 10);
      const pp = parseInt((sub.match(/(\d+)\s*P\b/i) || [])[1] || '0', 10);
      const remK = Math.max(0, kcal - pp * 4);
      const cc = Math.round((remK * 0.55) / 4);
      const ff = Math.round((remK * 0.45) / 9);
      const parts = String(row.title || '').split(/\s*(?:,|\+|&|\/| with | and )\s*/i).map((x) => x.trim()).filter(Boolean);
      const per = parts.length ? Math.round(kcal / parts.length) : kcal;
      return {
        id: `home-demo-${selIdx}-${j}`, time: row.time || '', tag: row.tag, tagColor: row.tagColor,
        title: row.title, sub, kcal, p: pp, c: cc, f: ff,
        prep: '10 min', portion: '1 plate', score: 'A',
        hero: `${row.title}.`,
        brief: 'From today’s plan. Confirm to update your calories, protein, carbs, and fat for the day.',
        ingredients: parts.map((m2, k2) => ({ n: 'portion', m: m2.charAt(0).toUpperCase() + m2.slice(1), k: `${k2 === parts.length - 1 ? Math.max(0, kcal - per * (parts.length - 1)) : per} kcal` })),
      };
    });
  })();
  // Habits for the selected day — live from the user's habits (mirrored into
  // tweaks) when present, demo set otherwise. `done` reflects that specific day.
  const _homeHabitsDec = (typeof window !== 'undefined' && window._bsDecodeHabits) ? window._bsDecodeHabits(tweaks.habits) : [];
  const _homeHabitsDateKey = (() => {
    const dd = weekDates[selIdx];
    return `${dd.getFullYear()}-${String(dd.getMonth() + 1).padStart(2, '0')}-${String(dd.getDate()).padStart(2, '0')}`;
  })();
  const selDayHabits = (() => {
    const ptsOf = (h) => (typeof window !== 'undefined' && window._bsHabitPts) ? window._bsHabitPts(h) : (h.pts || 5);
    if (_homeHabitsDec && _homeHabitsDec.length) {
      return _homeHabitsDec.map(h => ({ id: h.id, name: h.name, type: h.type, domain: h.domain, pts: ptsOf(h), done: (h.history || []).includes(_homeHabitsDateKey), live: true }));
    }
    // Signed in with no habits yet → empty (the card shows "add your first one");
    // the demo habit set is the signed-out preview only.
    if (bsHomeSignedIn) return [];
    const demo = (typeof window !== 'undefined' && window._BS_HABIT_DEMO_ROWS) || [];
    return demo.map(h => ({ id: h.id, name: h.name, type: h.type, pts: h.pts, done: (h.pattern || [])[selIdx] > 0, live: false }));
  })();
  // Check a habit off right on the home card: flips the selected day in the
  // habit's history, mirrors into tweaks (instant re-render — the row leaves
  // the card) and persists via the same /api/client/habits toggle the habits
  // page uses. Demo habits (no live set yet) route to the habits page.
  const toggleHomeHabit = (h) => {
    if (!h.live) { setHabitsPage(true); return; }
    if (window.bsRequireAccount && !window.bsRequireAccount('track habits')) return;
    const next = _homeHabitsDec.map(x => {
      if (x.id !== h.id) return x;
      const hist = new Set(x.history || []);
      if (hist.has(_homeHabitsDateKey)) hist.delete(_homeHabitsDateKey); else hist.add(_homeHabitsDateKey);
      return { ...x, history: [...hist].sort() };
    });
    if (window._bsEncodeHabits) setTweak('habits', window._bsEncodeHabits(next));
    if (window.ShapeAuth?.getCachedState?.().user) {
      fetch('/api/client/habits', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'toggle', id: h.id, date: _homeHabitsDateKey }) }).catch(() => {});
    }
    if (!h.done) {
      setHabitFlash({ name: h.name, pts: Math.round(h.pts) });
      clearTimeout(habitFlashTimer.current);
      habitFlashTimer.current = setTimeout(() => setHabitFlash(null), 2200);
    }
  };
  // Per-day calorie balance for the LEAD block (target = 2100 burned).
  // Sums kcal from MEAL items in DAY_LOGS, computes deficit/surplus.
  const DAY_MACROS = {
    20: { kcalIn: 1588, kcalBurn: 2100, status: 'logged', note: 'Five logs in. Lower pull + 4 meals.' },
    21: { kcalIn: 1568, kcalBurn: 2100, status: 'on track', note: 'On track. 1568 in, 2100 burned.\nOne workout and lunch left to log.' },
    22: { kcalIn: 1570, kcalBurn: 2050, status: 'on track', note: 'Day done. Pull day + 3 meals.' },
    23: { kcalIn: 1550, kcalBurn: 1900, status: 'easy day', note: 'Light day. Z2 run + 2 meals.' },
    24: { kcalIn: 2200, kcalBurn: 2100, status: 'refeed',   note: 'Refeed Friday. +100 over target.\nPlanned ahead of consult.' },
    25: { kcalIn: 1720, kcalBurn: 1850, status: 'long run', note: 'Long run done. Brunch + 3 meals.' },
    26: { kcalIn: 1320, kcalBurn: 1700, status: 'rest day', note: 'Rest day. Three lighter meals.' },
  };
  const macros = DAY_MACROS[dataDay] || DAY_MACROS[20 + todayIdx] || DAY_MACROS[21];
  // Live balance for TODAY when we have a real logged-calories snapshot
  // (ticker.cal from /api/client/analytics: consumed vs target). Other days, or
  // when nothing's logged, fall back to the editorial sample.
  const liveCal = ticker && typeof ticker.cal === 'number' ? ticker.cal : null;
  const liveTarget = ticker && typeof ticker.cal_target === 'number' ? ticker.cal_target : null;
  const hasLiveBalance = selIdx === todayIdx && liveCal != null && liveTarget != null;
  // Demo macro balance is the SIGNED-OUT preview only — a signed-in account
  // never sees fabricated kcal/notes (the honest "log to see" state covers it).
  const balance = hasLiveBalance ? (liveCal - liveTarget) : (bsHomeSignedIn ? 0 : (macros.kcalIn - macros.kcalBurn)); // negative = deficit
  const balanceSign = balance < 0 ? '−' : '+';
  const balanceValue = Math.abs(balance).toString();
  // Demoted secondary line with a tilde (admits it's approximate). '— kcal' when
  // today has no logged nutrition yet.
  // Honest "no live data" state: today before any logs, OR any day a signed-in
  // account has no real balance for (kills the demo-note leak on non-today days).
  const noLiveToday = (selIdx === todayIdx && liveCal == null) || (bsHomeSignedIn && !hasLiveBalance);
  const energyEstimate = noLiveToday ? '— kcal' : `~${balanceSign}${balanceValue} kcal`;

  // ── ENERGY card — one component, three goal-driven states. Same balance,
  // reframed: a deficit reads as on-target for a cut, balanced for maintenance,
  // and "fuel up" for a build. Hero is a word, not a fake-precise number.
  const energyAccents = { cut: t.GREEN, maintain: t.BLUE, build: t.AMBER };
  const energyAccent = energyAccents[energyGoal] || t.BLUE;
  const ENERGY_STATES = {
    cut: {
      kicker: 'Energy · On target', hero: 'Under',
      meta: ['Fat loss', energyEstimate, 'within range'],
      tail: balance < 0 ? "You're tracking where you want to be." : 'A little over today — ease back tomorrow.',
    },
    maintain: {
      kicker: 'Energy · Balanced', hero: 'Even',
      meta: ['Maintain', energyEstimate, 'steady'],
      tail: 'Right in the pocket for holding steady.',
    },
    build: {
      kicker: 'Energy · Fuel up', hero: balance < 0 ? 'Short' : 'Built',
      meta: ['Build', energyEstimate, balance < 0 ? 'under surplus' : 'on surplus'],
      tail: balance < 0 ? 'A build day wants more — add a meal.' : "Surplus in. That's the fuel for growth.",
    },
  };
  let energy = ENERGY_STATES[energyGoal] || ENERGY_STATES.maintain;
  // Today with nothing logged yet → invite logging instead of asserting a state.
  if (noLiveToday) {
    const goalLabel = { cut: 'Fat loss', maintain: 'Maintain', build: 'Build' }[energyGoal] || 'Maintain';
    energy = { kicker: 'Energy · Log to see', hero: 'Open', meta: [goalLabel, '— kcal', 'nothing logged'], tail: '' };
  }
  const energyCaption = noLiveToday
    ? 'Log a meal to see where today lands against your goal.'
    : (hasLiveBalance ? energy.tail : `${macros.note} ${energy.tail}`);

  if (previewMeal) {
    return <BSMealPreview meal={previewMeal} onBack={() => setPreviewMeal(null)} onLog={() => { setMealToLog(previewMeal); setLoggingMealId(previewMeal.id); setShowLogMeal(true); setPreviewMeal(null); }}
      onFiled={() => { const id = previewMeal && previewMeal.id; if (id != null) setMealLogged((prev) => ({ ...prev, [id]: true })); }}
      onUnfiled={() => { const id = previewMeal && previewMeal.id; if (id != null) setMealLogged((prev) => { const n = { ...prev }; delete n[id]; return n; }); }} />;
  }
  if (showWorkoutPreview) {
    return <BSHomeWorkoutPreview workout={selWorkout} onBack={() => setShowWorkoutPreview(false)} onMove={() => { setShowWorkoutPreview(false); goCalendar?.(); }} onStart={() => { setShowWorkoutPreview(false); goTrain?.(); }} onMessage={() => { setShowWorkoutPreview(false); goChat('Jordan Chen', 'Coach · Hypertrophy'); }} />;
  }
  if (showLogMeal) {
    return <BSLogMealFlow meal={mealToLog} daySoFar={{ cal: liveCal, protein: (ticker && typeof ticker.protein_g === 'number' ? ticker.protein_g : null) }} dayTargets={{ cal: (ticker && typeof ticker.cal_target === 'number') ? ticker.cal_target : null, protein: (ticker && typeof ticker.protein_target === 'number') ? ticker.protein_target : null }} signedIn={bsHomeSignedIn} onClose={() => { setShowLogMeal(false); setMealToLog(null); }} onLogged={() => { if (loggingMealId) setMealLogged((prev) => ({ ...prev, [loggingMealId]: true })); }} />;
  }
  if (habitsPage) {
    return <BSHabitsPage tweaks={tweaks} setTweak={setTweak} accent={t.GREEN} onBack={() => setHabitsPage(false)} onOpenScore={() => { setHabitsPage(false); goScore?.(); }} />;
  }
  if (checkinPage) {
    return <BSWeeklyCheckin onBack={() => { setCheckinPage(false); setCheckinDue(false); }} />;
  }
  if (homeProgressPage) {
    return <BSClientProgress onBack={() => setHomeProgressPage(false)} />;
  }
  if (goalsPage) {
    return <BSClientGoals onBack={() => setGoalsPage(false)} onOpenProgress={() => { setGoalsPage(false); setHomeProgressPage(true); }} />;
  }
  if (todayPage) {
    return <BSTodayPage onBack={() => setTodayPage(false)} />;
  }

  // "Today · your move" — ONE clear next move. The signal engine's top action
  // leads when it has a real flag (the RIGHT move, not just the next chronological
  // item); otherwise it synthesizes from the day's plan (workout → unlogged meals
  // → habits → done). Only on today; other days are plan views. heroMealId lets the
  // Meals glance show the targeted meal as "next" without a duplicate Log button.
  const todayDirective = (() => {
    if (selIdx !== todayIdx) return null;
    const _teal = t.isLight ? '#0a8f87' : '#34d6c5';
    // engineFlag is the engine's directive (lever + grounded reason). The lever
    // → move map preserves the existing heads/CTAs; the sub is the cross-domain
    // reason; the new `sleep` lever is the cross-discipline one.
    // `stakes` = never-shaming upside copy on the levers that carry a real Shape Score
    // commitment (kept = earns + momentum; lapsing dips the number). Framed as "keep /
    // protect", never "or lose". Only the penalize-able levers carry it.
    // CTAs are framed as a first-person PROMISE ("I'll …"), not a command — tapping
    // the day's next move feels like making a pledge you then keep (commitment &
    // consistency). The head stays the directive; the button is the promise.
    const engineMove = engineFlag ? ({
      // head defaultValues read the SHARED BS_LEVER_HEADS (dailyWire.mjs) so the
      // Shape Daily telegram and this Home lead can never say a different move;
      // i18n overrides still ride on top via the tr() key.
      checkin:   { head: tr('home:lead.checkin.head', { defaultValue: BS_LEVER_HEADS.checkin }), cta: [tr('home:lead.checkin.cta', { defaultValue: "I'll check in →" }), () => setCheckinPage(true)], c: t.ACCENT, stakes: tr('home:lead.checkin.stakes', { defaultValue: 'keep your momentum + protect 15 pts' }) },
      training:  { head: tr('home:lead.training.head', { defaultValue: BS_LEVER_HEADS.training }), cta: [tr('home:lead.training.cta', { defaultValue: "I'll keep my streak →" }), () => setHabitsPage(true)], c: t.GREEN, stakes: tr('home:lead.training.stakes', { defaultValue: 'hold your streak + momentum' }) },
      nutrition: { head: tr('home:lead.nutrition.head', { defaultValue: BS_LEVER_HEADS.nutrition }), cta: [tr('home:lead.nutrition.cta', { defaultValue: "I'll log a meal →" }), () => goEat()], c: _teal, stakes: tr('home:lead.nutrition.stakes', { defaultValue: 'keep your momentum going' }) },
      goal:      { head: tr('home:lead.goal.head', { defaultValue: BS_LEVER_HEADS.goal }), cta: [tr('home:lead.goal.cta', { defaultValue: "I'll weigh in →" }), () => setGoalsPage(true)], c: t.AMBER },
      score:     { head: tr('home:lead.score.head', { defaultValue: BS_LEVER_HEADS.score }), cta: [tr('home:lead.score.cta', { defaultValue: "I'll grab a win →" }), () => setHabitsPage(true)], c: t.AMBER },
      // `sleep` deliberately omitted — logging last night's sleep is consolidated
      // into the "Today · how are you" check-in page (opened from the nudge below;
      // Sleep · last night row + recovery readiness), so it never spawns a
      // separate directive box.
    }[engineFlag.lever]) : null;
    // THE CYCLE — the neutral note (spec 2026-07-19, Task 4). Deliberate
    // deviation: the plan allows this to LEAD ("MAY lead"), but leading is
    // only reachable when nothing else is pending — exactly where the
    // kept-promise echo lives, and replacing a member's "you kept your word"
    // with a body-state note is a worse close. So it rides as the SUB of the
    // done state: it can never outrank real work, and the echo survives.
    // ⚠ Gated on 'menstrual' ONLY. The plan also names luteal-with-a-fired-
    // recovery-read, but that read is the Progress card's (it needs 120 days
    // of series + every statistical floor); asserting "lighter load reads
    // well" in luteal without it would be a claim we cannot back. Deferred,
    // not fabricated.
    const cycleNote = (cycleOptIn && cycleNow && cycleNow.phase === 'menstrual')
      ? tr('home:lever.recoverySub', { defaultValue: 'Lighter load reads well today.' })
      : null;
    const todo = [];
    if (engineMove) todo.push({ head: engineMove.head, sub: [engineFlag.reason, engineMove.stakes].filter(Boolean).join(' · '), cta: engineMove.cta, c: engineMove.c, engine: true });
    if (selWorkout && selWorkout.title) todo.push({ label: selWorkout.title, cta: [tr('home:lead.workout.cta', { defaultValue: "I'll train today →" }), () => setShowWorkoutPreview(true)], c: t.RUST, workout: true });
    selMeals.filter(m => !mealLogged[m.id]).forEach(m => todo.push({ label: tr('home:lead.logMeal', { defaultValue: 'Log {title}', title: m.title }), cta: [tr('home:lead.meal.cta', { defaultValue: "I'll log it →" }), () => { setMealToLog(m); setLoggingMealId(m.id); setShowLogMeal(true); }], c: _teal, mealId: m.id, meal: m }));
    const habitsLeft = selDayHabits.filter(h => !h.done).length;
    if (habitsLeft > 0) todo.push({ label: tr('home:lead.habitsToFinish', { defaultValue: '{count, plural, one {# habit to finish} other {# habits to finish}}', count: habitsLeft }), cta: [tr('home:lead.habits.cta', { defaultValue: "I'll finish my habits →" }), () => setHabitsPage(true)], c: t.GREEN });
    // Kept-promise echo: when everything's logged, close the loop on the day's pledge.
    if (!todo.length) return { done: true, head: tr('home:lead.done.head', { defaultValue: 'You kept your word today.' }), sub: cycleNote || tr('home:lead.done.sub', { defaultValue: "Everything you said you'd do — done." }), c: t.GREEN, leadIsWorkout: false, leadMeal: null };
    const lead = todo[0];
    return {
      head: lead.engine ? lead.head : lead.label, cta: lead.cta, c: lead.c,
      sub: lead.engine ? lead.sub : (todo.length > 1 ? tr('home:lead.moreOnPlan', { defaultValue: '{count, plural, one {# more on today’s plan} other {# more on today’s plan}}', count: todo.length - 1 }) : null),
      heroMealId: lead.mealId || null,
      // Lead-identity flags (Task 4 reads these to suppress the slate's echo row's
      // second interactive surface — the double-feature fix).
      leadIsWorkout: !!lead.workout,
      leadMeal: lead.meal || null,
    };
  })();

  // Compact 3-move list for the LEAD plate when lead=workout (mirrors the
  // slate TRAINING row's own list — same source, same 3-move truncation — so
  // the lead and the slate never disagree on what "today's workout" is).
  const _wkCompactLead = (() => {
    if (!(todayDirective && todayDirective.leadIsWorkout && selWorkout)) return [];
    const moves = (selWorkout.detail && selWorkout.detail.moves) || [];
    const compact = moves.slice(0, 3).map((m, i) => [String(i + 1).padStart(2, '0'), m.name, String(m.scheme || '').replace(' rest', ''), m.load || '']);
    if (moves.length > 3) compact.push(['+', `+ ${moves.length - 3} more`, moves.slice(3).map((m) => m.name).slice(0, 3).join(' · '), '']);
    return compact;
  })();

  // ★ THE LEAD, rail edition (concept B — owner pick off the 2026-07-13 home
  // board): the page's single elevated moment now threads INLINE on the
  // slate's rail — at its time slot when the lead is the workout or a meal
  // (timeLabel), at the rail's head when it's untimed (engine / habits / done
  // leads). The BSPlate chrome died with the pick; head, sub, compact move
  // list, meal macros, CTAs, and the hero-home tour anchor carry over
  // verbatim from the old standalone plate.
  const _leadBlock = (timeLabel) => !todayDirective ? null : (
    <div data-tour="hero-home" style={{ padding: `11px ${t.padX}px 13px`, borderBottom: `1px solid ${t.HAIR}` }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }}>
        <span style={{ fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.2em', textTransform: 'uppercase', color: todayDirective.c }}>
          {timeLabel
            ? `${timeLabel} · ${tr('home:lead.railHeader', { defaultValue: 'Your move' })}`
            : (todayDirective.done ? tr('home:lead.headerDone', { defaultValue: 'Today · done' }) : tr('home:lead.header', { defaultValue: 'Today · your move' }))}
        </span>
        <span style={{ fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{_dowShort(_now)} {_now.getDate()}</span>
      </div>
      <div style={{ marginTop: 6, fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 22, lineHeight: 1.06, letterSpacing: '-0.03em', color: t.INK }}>{todayDirective.head}</div>
      {todayDirective.sub && <div style={{ marginTop: 5, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{todayDirective.sub}</div>}
      {todayDirective.leadIsWorkout && _wkCompactLead.length > 0 && (
        <div style={{ marginTop: 9 }}>
          {_wkCompactLead.map(([n, name, sub, wt], i, arr) => (
            <div
              key={`lead-${n}-${i}`}
              onClick={() => setShowWorkoutPreview(true)}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setShowWorkoutPreview(true); } }}
              role="button"
              tabIndex={0}
              aria-label={tr('home:lead.openWorkoutPreview', { defaultValue: '{name} — open workout preview', name })}
              style={{ display: 'grid', gridTemplateColumns: '22px 1fr auto', alignItems: 'center', minHeight: 44, gap: 10, padding: '6px 0', borderBottom: i === arr.length - 1 ? 0 : `1px solid ${t.HAIR}`, cursor: 'pointer' }}>
              <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, color: t.INK50 }}>{n}</span>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontFamily: t.DISPLAY, fontSize: 14, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em' }}>{name}</div>
                <div style={{ fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, marginTop: 2 }}>{sub}</div>
              </div>
              {wt ? <span style={{ fontFamily: t.MONO, fontSize: 11, fontWeight: 700, color: t.INK70, fontVariantNumeric: 'tabular-nums' }}>{wt}</span> : <span />}
            </div>
          ))}
        </div>
      )}
      {todayDirective.leadMeal && todayDirective.leadMeal.kcal > 0 && (
        <div style={{ marginTop: 8, fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.06em', color: t.INK50, fontWeight: 600 }}>
          {todayDirective.leadMeal.kcal} kcal · {todayDirective.leadMeal.p}P · {todayDirective.leadMeal.c}C · {todayDirective.leadMeal.f}F
        </div>
      )}
      {/* ONE text-action in the lead's accent (owner call 2026-07-13: the boxed
          CTA + the Preview link opened the SAME workout preview — the box look
          dies and the redundant Preview → link dies with it). */}
      {todayDirective.cta && (
        <div style={{ marginTop: 4 }}>
          <button onClick={todayDirective.cta[1]} style={{ display: 'inline-flex', alignItems: 'center', minHeight: 44, padding: '0 2px', background: 'transparent', border: 0, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: todayDirective.c }}>{todayDirective.cta[0]}</button>
        </div>
      )}
    </div>
  );

  // ── ANTI-ACCRETION CONTRACT ────────────────────────────────────────────
  // Do not add a plate. If it can't be a row, it lives on a tab and gets at
  // most a row-door.
  // ────────────────────────────────────────────────────────────────────────
  return (
    <BSPage>
      <BSMasthead
        compact
        title={<img src={`${import.meta.env.BASE_URL}shape-wordmark.png`} alt="Shape" style={{ display: 'block', margin: '6px auto -2px', height: 56, width: 'auto', filter: t.isLight ? 'brightness(0)' : 'brightness(0) invert(1)' }} />}
        leftKicker={`${_dowShort(_now)} · ${_monShort(_now)} ${_now.getDate()} · ${_now.getFullYear()}`}
        rightKicker={`${bsHomeProgram.nutritionPhase || tr('home:phase.cut', { defaultValue: 'Cut' })} · ${tr('home:dateline.weekAbbr', { defaultValue: 'W' })}${isoWeek}`}
        trailing={<BSHeaderTools onProfile={onProfile} />}
        showDoubleRule={false}
        showDotTexture={false}
        noTopRule
      />

      <BSTicker items={(() => {
        const tk = ticker || {};
        const fmtSleep = (h) => {
          if (h == null) return null;
          const whole = Math.floor(h);
          const min = Math.round((h - whole) * 60);
          return `${whole}H${String(min).padStart(2, '0')}M`;
        };
        const fmtDelta = (n, suffix) => {
          if (n == null) return '';
          const sign = n > 0 ? '+' : n < 0 ? '-' : '';
          return `${sign}${Math.abs(n)}${suffix}`;
        };
        const pct = tk.cal != null && tk.cal_target ? Math.round((tk.cal / tk.cal_target - 1) * 100) : null;
        const proColor = tk.protein_g != null && tk.protein_g >= 120 ? '#a3e09a' : undefined;
        // Today's habits — live from the user's set (real date key, independent
        // of the week-strip selection); demo numbers when no live habits yet.
        const tkHab = (() => {
          if (!_homeHabitsDec.length) return null;
          const d = new Date();
          const k = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
          const ptsOf = (h) => (typeof window !== 'undefined' && window._bsHabitPts) ? window._bsHabitPts(h) : (h.pts || 5);
          const done = _homeHabitsDec.filter(h => (h.history || []).includes(k));
          return { done: done.length, total: _homeHabitsDec.length, pts: done.reduce((a, h) => a + Math.round(ptsOf(h)), 0) };
        })();
        const all = [
          { label: 'CAL',  value: tk.cal != null ? `${tk.cal}/${tk.cal_target}` : '1568/2100', note: pct != null ? `${pct >= 0 ? '+' : ''}${pct}% TGT` : '-25% TGT' },
          { label: 'PRO',  value: tk.protein_g != null ? `${tk.protein_g}G` : '118G', note: tk.protein_g != null && tk.protein_g >= 120 ? tr('home:ticker.onPace', { defaultValue: 'ON PACE' }) : tr('home:ticker.buildUp', { defaultValue: 'BUILD UP' }), color: proColor },
          { label: 'HAB',  value: tkHab ? `${tkHab.done}/${tkHab.total}` : '3/5', note: tkHab ? `+${tkHab.pts} PTS` : '+12 PTS', color: tkHab && tkHab.total > 0 && tkHab.done >= tkHab.total ? '#a3e09a' : undefined },
          { label: 'SLP',  value: fmtSleep(tk.sleep_hours) || '7H24M', note: fmtDelta(tk.sleep_delta_min, 'M VS YEST') || '+28M VS AVG', color: '#a3e09a' },
          { label: 'HRV',  value: tk.hrv_ms != null ? `${Math.round(tk.hrv_ms)}MS` : '62MS', note: tk.hrv_ms != null && tk.hrv_ms >= 50 ? tr('home:ticker.good', { defaultValue: 'GOOD' }) : tr('home:ticker.low', { defaultValue: 'LOW' }), color: tk.hrv_ms != null && tk.hrv_ms >= 50 ? '#a3e09a' : '#ffc56a' },
          { label: 'RHR',  value: tk.resting_hr != null ? `${Math.round(tk.resting_hr)}BPM` : '54BPM', note: tk.resting_hr != null && tk.resting_hr > 60 ? tr('home:ticker.elev', { defaultValue: 'ELEV' }) : tr('home:ticker.steady', { defaultValue: 'STEADY' }), color: tk.resting_hr != null && tk.resting_hr > 60 ? '#ffc56a' : undefined },
          { label: 'WGT',  value: tk.weight_lb != null ? `${t.convWeight(tk.weight_lb).toFixed(1)}${t.weightUnit.toUpperCase()}` : (t.isMetric ? '80.8KG' : '178.2LB'), note: tk.weight_delta_7d != null ? fmtDelta(Math.round(t.convWeight(tk.weight_delta_7d) * 10) / 10, ' 7D') : (t.isMetric ? '-0.2 7D' : '-0.4 7D') },
        ];
        const order = (tickerPrefs.order && tickerPrefs.order.length) ? tickerPrefs.order : all.map(i => i.label);
        // Append metrics added after the user's prefs were saved (e.g. HAB) so
        // new live metrics show up without re-toggling in Settings.
        const ordered = order.map(k => all.find(i => i.label === k)).filter(Boolean);
        const extras = all.filter(i => !order.includes(i.label));
        const out = [...ordered, ...extras].filter(it => !(tickerPrefs.hidden || []).includes(it.label));
        // Signed in with no live metrics yet → no ticker (BSTicker hides on []).
        // The demo ticker numbers are the signed-out preview only.
        if (bsHomeSignedIn && !(ticker && (ticker.cal != null || ticker.protein_g != null || ticker.weight_lb != null || ticker.sleep_hours != null || ticker.hrv_ms != null || ticker.resting_hr != null)) && !tkHab) return [];
        return out.length ? out : all;
      })()} />

      {/* Edition strip — moved below the ticker (which sits under the date masthead) */}
      <div style={{
        padding: `7px ${t.padX}px 10px`,
        borderBottom: `1px solid ${t.RULE}`,
        display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
        background: t.PAPER2,
      }}>
        <span style={{ fontFamily: t.MONO, fontSize: 10, letterSpacing: '0.22em', textTransform: 'uppercase', fontWeight: 700, color: t.GREEN }}>
          {tr('home:edition.clients', { defaultValue: 'Clients Edition · No. {n}', n: 14 })}
        </span>
        <span style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.18em', textTransform: 'uppercase', fontWeight: 600, color: t.INK50 }}>
          {tr('home:edition.vol', { defaultValue: 'Vol. I' })}
        </span>
      </div>

      {/* NOW PLAYING — Shape Radio (above the week calendar) */}
      <BSNowPlaying onOpen={goRadio} />

      {/* THIS WEEK — calendar preview (directly below the Clients Edition band) */}
      <div style={{ padding: `${t.sectGap}px ${t.padX}px 8px`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
        <span style={{ display: 'inline-flex', alignItems: 'baseline', gap: 9, minWidth: 0, flexWrap: 'wrap' }}>
          <span style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 11, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK, whiteSpace: 'nowrap' }}>▍ {tr('home:section.thisWeek', { defaultValue: 'This week' })}</span>
          <span style={{ fontFamily: t.MONO, fontSize: 9, color: t.INK50, letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 600, whiteSpace: 'nowrap' }}>{tr('home:dateline.wkAbbr', { defaultValue: 'Wk' })} {isoWeek} · {fmtDate(0)}–{weekDates[0].getMonth() === weekDates[6].getMonth() ? weekDates[6].getDate() : fmtDate(6)}</span>
        </span>
        <button onClick={goCalendar} style={{ flexShrink: 0, display: 'inline-flex', alignItems: 'center', minHeight: 44, background: 'transparent', border: 0, padding: '0 2px', color: t.ACCENT, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', cursor: 'pointer', whiteSpace: 'nowrap' }}>{tr('home:action.monthView', { defaultValue: 'Month view →' })}</button>
      </div>
      <div style={{ padding: `0 ${t.padX}px 12px` }}>
        {/* Calendar rule with a heat needle over the selected day — the #1622
            Train/Eat week-strip grammar (owner clean-up pass, 2026-07-13: the
            boxed day tiles die; typographic day columns keep the activity dots). */}
        <div aria-hidden style={{ position: 'relative', height: 2, background: `linear-gradient(90deg, ${t.INK}, ${t.ACCENT} 58%, transparent)` }}>
          {weekDates.map((_, i) => (
            <span key={i} style={{ position: 'absolute', left: `${((i + 0.5) * 100) / 7}%`, top: -3, width: 1.5, height: 8, background: t.RULE }} />
          ))}
          <span style={{ position: 'absolute', left: `${((selIdx + 0.5) * 100) / 7}%`, top: -7, width: 0, height: 0, borderLeft: '5px solid transparent', borderRight: '5px solid transparent', borderTop: `7px solid ${t.ACCENT}`, transform: 'translateX(-5px)' }} />
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', marginTop: 6 }}>
          {weekDates.map((date, idx) => {
            const on    = idx === selIdx;
            const today = idx === todayIdx;
            const dots  = (liveWeek ? liveWeek.dots[idx] : WEEK_DOTS_BY_IDX[idx]) || [];
            return (
              <button type="button" key={idx} onClick={() => setSelIdx(idx)}
                aria-label={`${date.toLocaleDateString(_dateLoc, { weekday: 'long', month: 'long', day: 'numeric' })}${on ? `, ${tr('home:aria.selected', { defaultValue: 'selected' })}` : ''}${today ? `, ${tr('home:aria.today', { defaultValue: 'today' })}` : ''}`}
                style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, minHeight: 44, padding: '4px 0', background: 'transparent', border: 0, cursor: 'pointer' }}>
                <span style={{ fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.16em', fontWeight: 700, color: on ? t.ACCENT : t.INK50 }}>{date.toLocaleDateString(_dateLoc, { weekday: 'narrow' }).toUpperCase()}</span>
                <span style={{ fontFamily: t.DISPLAY, fontWeight: t.W.display, fontSize: 16, letterSpacing: '-0.04em', lineHeight: 1.15, fontVariantNumeric: 'tabular-nums', color: on || today ? t.INK : t.INK50 }}>{date.getDate()}</span>
                <span style={{ display: 'flex', gap: 2.5, height: 3, marginTop: 1 }}>
                  {dots.slice(0, 3).map((c, k) => <span key={k} style={{ width: 4, height: 3, borderRadius: 1, background: c }} />)}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* BULLETINS — max 2 slim one-liners, ABOVE the lead. Each suppressed
          per-lever, not by whether a lead exists at all (the spec: bulletins
          suppress "when the lever they represent is already the lead"). The
          daily check-in bulletin is NOT gated externally here — BSTodayNudge's
          variant="bulletin" already self-gates on `useBSCheckinLogged()`
          internally (returns null once logged), so the only external
          suppression needed is the engine's `checkin` lever leading. Calling
          useBSCheckinLogged() again here would be a second hook instance
          racing the same async fetch against BSTodayNudge's own — deleted, not
          duplicated. Same per-lever suppression on the weekly bulletin: it
          hides only when the engine's `checkin` lever is the lead, not
          whenever ANY lead exists (a workout/meal/habit lead must not eat the
          weekly check-in's only Home surface). Urgency earns height;
          completion demotes to an index row (Task 5, INSIDE.). */}
      {!(engineFlag && engineFlag.lever === 'checkin') && (
        <BSTodayNudge onOpen={() => setTodayPage(true)} variant="bulletin" />
      )}
      {checkinDue && !(engineFlag && engineFlag.lever === 'checkin') && (
        <BSHomeBulletin label={tr('home:bulletin.weeklyCheckin', { defaultValue: 'Weekly check-in due' })} detail={tr('home:bulletin.weeklyCheckinDetail', { defaultValue: '2 min' })} onOpen={() => setCheckinPage(true)} />
      )}

      {/* ★ THE LEAD renders INSIDE the slate's rail now (concept B) — see
          _leadBlock above. Timed leads (workout / meal) thread at their slot;
          untimed leads (engine / habits / done) sit at the rail's head. The
          fold is never empty: the done-state block still renders. */}

      {/* The day's plan beneath the move. The slate header below (its kicker
          shows upNextLabel on non-today views) is the single label surface now —
          the old BSSection duplicate here was removed (Roll-up c). */}

      {/* TODAY'S SLATE — one time-ordered run-sheet. Admission test: "is this
          scheduled to happen TODAY?" Rows, not cards. Anti-accretion: a future
          feature may claim a slate row only by passing that test; otherwise it
          lives on a tab and gets at most an index row / shelf door (see §5). */}
      {(() => {
        const teal = t.isLight ? '#0a8f87' : '#34d6c5';
        const rust = t.RUST;
        // Coach-scheduled times (24h minutes) drive both the displayed time and
        // the sort order — carried verbatim from the pre-slate AgendaCard block.
        const _wkAt = (selWorkout && selWorkout.time && selWorkout.time !== '—') ? selWorkout.time : '09:00';
        const [_wkH, _wkM] = String(_wkAt).split(':').map(Number);
        const WORKOUT_AT = (Number.isNaN(_wkH) ? 9 : _wkH) * 60 + (Number.isNaN(_wkM) ? 0 : _wkM);
        const _wkShortMeta = (selWorkout && selWorkout.detail && selWorkout.detail.meta)
          ? selWorkout.detail.meta.split(' · ').slice(0, 3).join(' · ')
          : (selWorkout && selWorkout.sub) || '';
        const _lunchPref = (typeof window !== 'undefined' && window.ShapeMealTimes && window.ShapeMealTimes.get().LUNCH) || '12:40';
        const [_lh, _lm] = String(_lunchPref).split(':').map(Number);
        const MEAL_AT = (Number.isNaN(_lh) ? 12 : _lh) * 60 + (Number.isNaN(_lm) ? 40 : _lm);
        const fmtAt = (mins) => {
          const h = Math.floor(mins / 60), m = mins % 60;
          const ap = h >= 12 ? 'PM' : 'AM';
          const h12 = h % 12 === 0 ? 12 : h % 12;
          return `${h12}:${String(m).padStart(2, '0')} ${ap}`;
        };
        const mealMinutes = (m) => {
          const [h, mm] = String(m.time || '').split(':').map(Number);
          if (!Number.isNaN(h)) return h * 60 + (Number.isNaN(mm) ? 0 : mm);
          return MEAL_AT;
        };
        const slotLabel = (m) => {
          const tag = String(m.tag || '').toUpperCase();
          const bfast = tr('home:slot.breakfast', { defaultValue: 'Breakfast' });
          const lunch = tr('home:slot.lunch', { defaultValue: 'Lunch' });
          const snack = tr('home:slot.snack', { defaultValue: 'Snack' });
          const dinner = tr('home:slot.dinner', { defaultValue: 'Dinner' });
          if (tag.startsWith('BFAST') || tag.startsWith('BREAK')) return bfast;
          if (tag.startsWith('LUNCH')) return lunch;
          if (tag.startsWith('SNACK')) return snack;
          if (tag.startsWith('DIN')) return dinner;
          const h = Math.floor(mealMinutes(m) / 60);
          return h < 11 ? bfast : h < 15 ? lunch : h < 17 ? snack : dinner;
        };
        // Ghost log-tick — the 36px inline control cell for a MEAL row's `right`
        // slot. Carries the exact tap targets the old mealsCard glance used
        // (setMealToLog/setLoggingMealId/setShowLogMeal), plus the LOGGED state.
        // Plain element factory (called, not mounted as a component type) so its
        // per-render identity can't remount the tick subtree.
        const mealTick = (m, logged) => logged ? (
          <span aria-hidden style={{ width: 24, height: 24, display: 'grid', placeItems: 'center', fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.06em', color: teal }}>✓</span>
        ) : (
          <button
            onClick={(e) => { e.stopPropagation(); setMealToLog(m); setLoggingMealId(m.id); setShowLogMeal(true); }}
            aria-label={tr('home:lead.logMeal', { defaultValue: 'Log {title}', title: m.title })}
            style={{ width: 24, height: 24, borderRadius: 5, flexShrink: 0, border: `1.5px solid ${teal}`, background: `${teal}12`, cursor: 'pointer', padding: 0 }}
          />
        );
        // Ordering is bsHomeSlateSort's alone (the tested pure module): timed
        // rows ascending by their displayed time, untimed rows after every
        // timed row in source order. No second sort key — the old parallel
        // `_sortAt` pre-sort duplicated the same ordering from raw minutes.
        const rows = [];
        // MEAL rows — one per selMeals meal. heroMealId suppresses the tick with
        // the lead echo (no second interactive surface on the lead's subject).
        selMeals.forEach((m) => {
          const logged = !!mealLogged[m.id];
          const isLead = !!(todayDirective && todayDirective.heroMealId === m.id);
          // The lead meal IS the inline lead block at its slot (concept B) —
          // never a second row for the same subject.
          if (isLead) { rows.push({ key: 'slate-lead', time: fmtAt(mealMinutes(m)), _min: mealMinutes(m), lead: true }); return; }
          rows.push({
            key: `meal-${m.id}`,
            // `time` still feeds bsHomeSlateSort (rows order by the displayed
            // string) — it just doesn't render as a column anymore; the row's
            // schedule reads from the right-side meta below (owner call 2026-07-14).
            time: fmtAt(mealMinutes(m)),
            _min: mealMinutes(m),
            tag: tr('home:tag.meal', { defaultValue: 'Meal' }), tagColor: teal,
            title: m.title,
            status: [fmtAt(mealMinutes(m)), m.kcal ? `${m.kcal} ${tr('home:unit.kcal', { defaultValue: 'kcal' })}` : null].filter(Boolean).join(' · '),
            right: mealTick(m, logged),
            onOpen: () => setPreviewMeal(m),
            ariaLabel: `${m.title}, ${slotLabel(m)}, ${logged ? tr('home:aria.logged', { defaultValue: 'logged' }) : tr('home:aria.notLogged', { defaultValue: 'not logged' })}`,
          });
        });
        // TRAINING row — real duration status; lead echo when the lead IS the
        // workout, else a quiet Start → link (training stays one tap). Rest day
        // → the Active-recovery row (carried verbatim from the old rest-day
        // branch's copy/tone, condensed to slate-row shape).
        // Reads Task 3's authoritative leadIsWorkout flag — never re-derive lead
        // status via a title-string comparison (todayDirective.head === selWorkout.title
        // is fragile: it only happens to work because Task 3's todo.push sets
        // label: selWorkout.title verbatim, and breaks silently the moment that
        // coupling drifts).
        const workoutIsLead = !!(todayDirective && todayDirective.leadIsWorkout);
        if (selWorkout && workoutIsLead) {
          // The lead workout IS the inline lead block at its slot (concept B).
          rows.push({ key: 'slate-lead', time: fmtAt(WORKOUT_AT), _min: WORKOUT_AT, lead: true });
        } else if (selWorkout) {
          rows.push({
            key: 'slate-training',
            time: fmtAt(WORKOUT_AT),
            _min: WORKOUT_AT,
            tag: tr('home:tag.training', { defaultValue: 'Training' }), tagColor: rust,
            title: selWorkout.title,
            status: [fmtAt(WORKOUT_AT), _wkShortMeta].filter(Boolean).join(' · '),
            right: (
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <button onClick={(e) => { e.stopPropagation(); goTrain?.(); }} style={{ background: 'transparent', border: 0, padding: 0, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: rust }}>{tr('home:action.start', { defaultValue: 'Start →' })}</button>
                <span aria-hidden style={{ fontFamily: t.MONO, fontSize: 12, color: t.INK50 }}>›</span>
              </div>
            ),
            onOpen: () => setShowWorkoutPreview(true),
            ariaLabel: `${selWorkout.title}, ${tr('home:aria.training', { defaultValue: 'training' })}, ${_wkShortMeta}`,
          });
        } else {
          rows.push({
            key: 'slate-training',
            time: '',
            tag: tr('home:tag.training', { defaultValue: 'Training' }), tagColor: t.GREEN,
            title: tr('home:slate.activeRecovery', { defaultValue: 'Active recovery' }),
            status: tr('home:slate.restDayMeta', { defaultValue: 'Rest day · walk + mobility' }),
            right: undefined,
            onOpen: undefined,
            ariaLabel: tr('home:slate.activeRecoveryAria', { defaultValue: 'Active recovery, rest day' }),
          });
        }
        // COACH rows — pushed items from coach_pushed_items (payload taps carried
        // verbatim from the deleted "From your coach" block).
        (coachFeed.items || []).forEach((it) => {
          const p = it.payload || {};
          const isMeal = it.kind === 'meal';
          const meta = isMeal
            ? [p.time, p.kcal != null ? p.kcal + ' ' + tr('home:unit.kcal', { defaultValue: 'kcal' }) : null, p.protein != null ? p.protein + tr('home:unit.gProtein', { defaultValue: 'g P' }) : null].filter(Boolean).join(' · ')
            : [p.time, p.sets, p.reps, p.tempo && (tr('home:coach.tempo', { defaultValue: 'Tempo' }) + ' ' + p.tempo)].filter(Boolean).join(' · ');
          rows.push({
            key: `coach-${it.id}`,
            time: p.time || '',
            tag: tr('home:tag.coach', { defaultValue: 'Coach' }), tagColor: isMeal ? teal : rust,
            title: p.name || (isMeal ? tr('home:coach.mealFrom', { defaultValue: 'Meal from your coach' }) : tr('home:coach.workoutFrom', { defaultValue: 'Workout from your coach' })),
            status: [meta, p.cue || p.note].filter(Boolean).join(' · '),
            right: undefined,
            onOpen: undefined,
            ariaLabel: isMeal ? tr('home:coach.ariaMeal', { defaultValue: 'Coach-pushed meal: {name}', name: p.name || '' }) : tr('home:coach.ariaWorkout', { defaultValue: 'Coach-pushed workout: {name}', name: p.name || '' }),
          });
        });
        // OPEN habit rows — up to 3, carried verbatim from the deleted HABITS
        // plate: habit checkbox stopPropagation + the #1502 keyboard guard on
        // the ROW (BSSlateRow's onKeyDown, first line: `if (e.target !==
        // e.currentTarget) return;` — added in Task 2). The checkbox itself is
        // a leaf control, not a container an event could bubble THROUGH before
        // reaching it — it only needs stopPropagation on click (so the row's
        // onOpen doesn't also fire) plus its own native <button> Enter/Space
        // activation. Do NOT re-add the e.target!==e.currentTarget guard on
        // the checkbox's own onKeyDown — a bare <button> has no children for a
        // keypress to bubble up FROM, so that guard there is meaningless (it
        // would always be true) and duplicates logic that already lives one
        // level up, on the row.
        const habitsDone = selDayHabits.filter(h => h.done).length;
        const habitsPts = selDayHabits.filter(h => h.done).reduce((a, h) => a + Math.round(h.pts), 0);
        const habitsPossible = selDayHabits.reduce((a, h) => a + Math.round(h.pts), 0);
        const openHabits = selDayHabits.filter(h => !h.done);
        openHabits.slice(0, 3).forEach((h) => {
          const avoid = h.type === 'avoid';
          const isWork = h.domain === 'work';
          const pillC = avoid ? t.RUST : t.GREEN;
          const avoidWord = tr('home:tag.avoid', { defaultValue: 'Avoid' });
          const doWord = tr('home:tag.do', { defaultValue: 'Do' });
          const workWord = tr('home:tag.work', { defaultValue: 'Work' });
          rows.push({
            key: `habit-${h.id || h.name}`,
            time: '',
            // Work-domain habits tag WORK in slate blue (spec 2026-07-13); the
            // checkbox keeps the do/avoid color, so nothing is lost.
            tag: isWork ? workWord : (avoid ? avoidWord : doWord), tagColor: isWork ? t.BLUE : pillC,
            title: h.name,
            status: tr('home:habit.pts', { defaultValue: '+{pts} pts', pts: Math.round(h.pts) }),
            right: (
              <button
                onClick={(e) => { e.stopPropagation(); toggleHomeHabit(h); }}
                aria-label={h.live ? tr('home:habit.markDone', { defaultValue: 'Mark {name} done', name: h.name }) : tr('home:habit.demoAria', { defaultValue: 'Demo habits — open the habits page' })}
                style={{ width: 24, height: 24, borderRadius: 5, flexShrink: 0, border: `1.5px solid ${h.live ? pillC : t.RULE}`, background: `${pillC}12`, cursor: 'pointer', padding: 0, display: 'grid', placeItems: 'center', fontSize: 10, lineHeight: 1 }}
              >{h.live ? '' : '🔒'}</button>
            ),
            onOpen: () => setHabitsPage(true),
            ariaLabel: tr('home:habit.rowAria', { defaultValue: '{kind}: {name}, worth {pts, plural, one {# point} other {# points}}, {state}', kind: avoid ? avoidWord : doWord, name: h.name, pts: Math.round(h.pts), state: h.done ? tr('home:aria.done', { defaultValue: 'done' }) : tr('home:aria.open', { defaultValue: 'open' }) }),
          });
        });
        const sortedRows = bsHomeSlateSort(rows);
        // A quiet sub-head before the first habit row, so habits read as their
        // own block inside the run-sheet (owner request) — meals/training stay
        // unlabeled (their tag column already identifies them).
        const firstHabitIdx = sortedRows.findIndex((r) => String(r.key).startsWith('habit-'));
        // ── NOW tick (concept B, today only): sits between the last passed
        // timed row and the first upcoming one. Rows without a real `_min`
        // (coach pushes, habits, rest day) never anchor it, and untimed rows
        // sort after timed ones, so the marker can never land inside the
        // habits block.
        const nowMin = bsNowMin;
        const isTodayView = selIdx === todayIdx;
        let nowIdx = -1;
        if (isTodayView) {
          nowIdx = sortedRows.findIndex((r) => typeof r._min === 'number' && r._min > nowMin);
          if (nowIdx === -1) {
            let lastTimed = -1;
            sortedRows.forEach((r, i) => { if (typeof r._min === 'number') lastTimed = i; });
            nowIdx = lastTimed === -1 ? -1 : lastTimed + 1;
          }
        }
        const nowMarker = isTodayView && nowIdx !== -1 ? (
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: 9, padding: `6px ${t.padX}px`, minHeight: 24 }} aria-label={`${tr('home:slate.now', { defaultValue: 'Now' })}, ${fmtAt(nowMin)}`}>
            <span aria-hidden style={{ position: 'absolute', left: 4, top: '50%', width: 9, height: 9, marginTop: -4.5, borderRadius: '50%', background: teal }}>
              <span style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: teal, ...(bsSdReduced() ? { opacity: 0.2 } : { animation: 'bsHomeNowPulse 2.4s ease-in-out infinite' }) }} />
            </span>
            <span style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: teal }}>{tr('home:slate.now', { defaultValue: 'Now' })} · {fmtAt(nowMin)}</span>
            <span aria-hidden style={{ flex: 1, height: 1, background: `linear-gradient(90deg, ${teal}55, transparent)` }} />
          </div>
        ) : null;
        const renderRow = (r, i) => (r.lead
          ? <React.Fragment key="slate-lead">{_leadBlock(r.time)}</React.Fragment>
          : <BSSlateRow key={r.key} index={i} tag={r.tag} tagColor={r.tagColor} title={r.title} status={r.status} right={r.right} onOpen={r.onOpen} ariaLabel={r.ariaLabel} />);
        return (
          <>
            <div style={{ padding: `${t.sectGap}px ${t.padX}px 8px`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
              <span style={{ display: 'inline-flex', alignItems: 'baseline', gap: 9, minWidth: 0, flexWrap: 'wrap' }}>
                <span style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 11, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK, whiteSpace: 'nowrap' }}>▤ {tr('home:section.slate', { defaultValue: "Today's slate" })}</span>
                <span style={{ fontFamily: t.MONO, fontSize: 9, color: t.INK50, letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 600, whiteSpace: 'nowrap' }}>{upNextLabel}</span>
              </span>
              <button onClick={() => goEat()} style={{ flexShrink: 0, display: 'inline-flex', alignItems: 'center', minHeight: 44, background: 'transparent', border: 0, padding: '0 2px', color: teal, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', cursor: 'pointer', whiteSpace: 'nowrap' }}>{tr('common:nav.eat', { defaultValue: 'Eat' })} →</button>
            </div>
            <div style={{ padding: `0 ${t.padX}px 4px` }}>
              <div aria-hidden style={{ height: 2, background: `linear-gradient(90deg, ${t.INK}, ${t.ACCENT} 58%, transparent)`, marginBottom: 4 }} />
            </div>
            <div style={{ position: 'relative' }}>
              {/* THE RAIL (concept B): one heat line threading the day — the
                  inline lead + the NOW tick anchor to it. Sits inside the rows'
                  left gutter (t.padX ≥ 18 at every density), so nothing shifts. */}
              {sortedRows.length > 0 && (
                <span aria-hidden style={{ position: 'absolute', left: 8, top: 2, bottom: 6, width: 2, background: `linear-gradient(180deg, ${teal}, ${teal}22)` }} />
              )}
              {todayDirective && !todayDirective.leadIsWorkout && !todayDirective.heroMealId && _leadBlock(null)}
              {sortedRows.length === 0 ? (
                <div style={{ padding: `10px ${t.padX}px 16px`, fontFamily: t.BODY, fontSize: 13.5, color: t.INK70, lineHeight: 1.45 }}>{tr('home:slate.empty', { defaultValue: 'Nothing scheduled for today.' })}</div>
              ) : (() => {
                const pre = firstHabitIdx === -1 ? sortedRows : sortedRows.slice(0, firstHabitIdx);
                return (
                  <>
                    {pre.map((r, i) => (
                      <React.Fragment key={`slot-${r.key}`}>
                        {i === nowIdx && nowMarker}
                        {renderRow(r, i)}
                      </React.Fragment>
                    ))}
                    {nowIdx === pre.length && nowMarker}
                  </>
                );
              })()}
              {/* The tour's hero-habits anchor is THIS sub-block — narrowed from
                  the whole slate (the spotlight used to swallow the meal +
                  training rows too) to just the habits head, rows, and states. */}
              <div data-tour="hero-habits">
              {firstHabitIdx !== -1 && (
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, padding: `13px ${t.padX}px 3px` }}>
                  <span style={{ fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: t.GREEN }}>{tr('home:slate.habitsHead', { defaultValue: 'Daily habits' })}</span>
                  <span style={{ fontFamily: t.MONO, fontSize: 9.5, letterSpacing: '0.1em', color: t.INK50, fontVariantNumeric: 'tabular-nums' }}>{habitsDone}/{selDayHabits.length}</span>
                  <span aria-hidden style={{ flex: 1, height: 1, background: t.HAIR }} />
                </div>
              )}
              {firstHabitIdx !== -1 && sortedRows.slice(firstHabitIdx).map((r, j) => (
                <BSSlateRow key={r.key} index={firstHabitIdx + j} tag={r.tag} tagColor={r.tagColor} title={r.title} status={r.status} right={r.right} onOpen={r.onOpen} ariaLabel={r.ariaLabel} />
              ))}
              {openHabits.length > 3 && (
                <button onClick={() => setHabitsPage(true)} style={{ width: '100%', textAlign: 'left', background: 'transparent', border: 0, padding: `10px ${t.padX}px`, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, borderBottom: `1px solid ${t.HAIR}` }}>
                  <span style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{tr('home:slate.moreHabits', { defaultValue: '{count, plural, one {+# more habit} other {+# more habits}}', count: openHabits.length - 3 })}</span>
                  <span style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.14em', textTransform: 'uppercase', color: t.GREEN, fontWeight: 800 }}>{tr('home:action.viewAll', { defaultValue: 'View all →' })}</span>
                </button>
              )}
              {selDayHabits.length === 0 && (
                <div style={{ padding: `10px ${t.padX}px 4px`, fontFamily: t.BODY, fontSize: 13, color: t.INK70, lineHeight: 1.4 }}>
                  <button onClick={() => setHabitsPage(true)} style={{ background: 'transparent', border: 0, padding: 0, cursor: 'pointer', color: t.GREEN, fontFamily: t.MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase' }}>{tr('home:slate.addFirstHabit', { defaultValue: '+ Add your first habit →' })}</button>
                </div>
              )}
              {selDayHabits.length > 0 && openHabits.length === 0 && (
                <div style={{ padding: `10px ${t.padX}px 4px`, fontFamily: t.BODY, fontSize: 13, color: t.INK70, lineHeight: 1.4 }}>
                  {tr('home:slate.allDonePre', { defaultValue: 'All habits done —' })} <span style={{ color: t.GREEN, fontWeight: 700 }}>{tr('home:habit.pts', { defaultValue: '+{pts} pts', pts: habitsPts })}</span> {tr('home:slate.allDonePost', { defaultValue: 'banked today.' })}
                </div>
              )}
              {habitFlash && (
                <div style={{ margin: `8px ${t.padX}px 0`, display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 10px', borderRadius: 4, background: `${t.ACCENT}1f`, border: `1px solid ${t.ACCENT}55`, color: t.ACCENT, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.04em' }}>{tr('home:slate.habitFlash', { defaultValue: '✓ +{pts} pts → Shape Score', pts: habitFlash.pts })}</div>
              )}
              </div>
            </div>
            {/* COACH WEEKLY NOTES — both notes as italic op-ed lines WITH bylines,
                rendered INSIDE the slate section, after the rows. Fixes the
                pre-existing demo-notes leak: the Jordan Chen / Dr. Maya Patel
                fallback (formerly map lines 3086-3089) now renders signed-out
                only — a signed-in account with no real coach banners yet sees
                no notes at all, instead of fabricated samples. */}
            {(() => {
              const banners = coachFeed.banners || [];
              const dayOf = (b) => {
                if (!b || !b.sent_at) return 'Mon';
                const d = new Date(b.sent_at);
                return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][d.getDay()] || 'Mon';
              };
              const trainerBanner = banners.find(b => b.provider_role !== 'nutritionist');
              const nutriBanner = banners.find(b => b.provider_role === 'nutritionist');
              const notes = [];
              if (trainerBanner) notes.push({ role: 'trainer', text: trainerBanner.text, who: trainerBanner.provider_name || 'Jordan Chen', when: dayOf(trainerBanner) });
              if (nutriBanner) notes.push({ role: 'nutritionist', text: nutriBanner.text, who: nutriBanner.provider_name || 'Dr. Maya Patel', when: dayOf(nutriBanner) });
              // Real coach notes only — no sample-note fallback (owner call:
              // the demo quotes are gone even in signed-out preview).
              if (!notes.length) return null;
              return (
                <div style={{ padding: `12px ${t.padX}px 4px`, display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {notes.map((n, i) => (
                    <div key={i} style={{ fontFamily: t.DISPLAY, fontStyle: 'italic', fontSize: 13, fontWeight: 500, color: t.INK70, lineHeight: 1.45, letterSpacing: '-0.01em' }}>
                      &ldquo;{n.text}&rdquo;
                      <span style={{ display: 'block', marginTop: 4, fontStyle: 'normal', fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>
                        — {n.who} · {n.role === 'nutritionist' ? tr('home:role.nutritionist', { defaultValue: 'Nutritionist' }) : tr('home:role.trainer', { defaultValue: 'Trainer' })}
                      </span>
                    </div>
                  ))}
                </div>
              );
            })()}
          </>
        );
      })()}

      {/* § INSIDE. — everything else lives here: index rows (live figure + door)
          and the shelf doors. Per the Front-Page Rule: do not add a plate here. If
          it can't be a row, it lives on a tab and gets at most a row-door. */}
      {(() => {
        const teal = t.isLight ? '#0a8f87' : '#34d6c5';
        return (
          <div style={{ padding: `${t.sectGap}px ${t.padX}px 4px` }}>
            <span style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 20, letterSpacing: '-0.02em', color: t.INK }}>
              {tr('home:section.inside', { defaultValue: 'Inside' })}<span style={{ color: teal, fontStyle: 'italic' }}>.</span>
            </span>
            <div aria-hidden style={{ height: 2, marginTop: 8, background: `linear-gradient(90deg, ${t.INK}, ${teal} 58%, transparent)` }} />
          </div>
        );
      })()}

      {/* The INSIDE. index-rows block fades in as ONE quiet unit (not per-row) —
          #1518-pattern keyframe, reduced-motion-gated. */}
      <div style={{ ...(bsSdReduced() ? null : { animation: 'bsHomeIndexIn 220ms ease-out both' }) }}>
        {/* WEEKLY TOTALS → two index rows. Same payloads as the old tile grid — the
            weekStat portal sheet below is unchanged and reads these objects as-is.
            Signed-out-only gate carried verbatim from the deleted tile grid. */}
        {(() => {
          // These are hardcoded demo figures (not wired to real rollups yet) — show
          // them only in the signed-out preview, never as fake stats to a real user.
          if (bsHomeSignedIn) return null;
          const _tagDone = tr('home:weekStat.tagDone', { defaultValue: 'Done' });
          const _tagSched = tr('home:weekStat.tagScheduled', { defaultValue: 'Scheduled' });
          const weekTotals = [
            { l: tr('home:weekStat.sessions', { defaultValue: 'Sessions' }), v: 4, max: 5, c: t.RUST, unit: 'sessions',
              history: [['Mon', 'Upper Push — Peak', _tagDone], ['Tue', 'Lower Pull — Vol.', _tagDone], ['Thu', 'Upper Pull — Peak', _tagDone], ['Sat', 'Z2 run · 45m', _tagDone], ['Sun', 'Lower Push — Peak', _tagSched]] },
            { l: tr('home:weekStat.avgKcal', { defaultValue: 'Avg kcal' }), v: 1890, max: 2100, c: t.BLUE, unit: 'avg kcal', chart: true, goalFrame: tr('home:weekStat.goalFrameDeficit', { defaultValue: 'In your deficit · on track' }),
              series: [['M', 1820], ['T', 2010], ['W', 1760], ['T', 1980], ['F', 1890], ['S', 2140], ['S', 1830]] },
          ];
          return (
            <>
              {/* weekTotals[0] (Sessions) carries no goalFrame field (only Avg kcal
                  does) — give it a real status string matching the old tile's own
                  affordance copy ("View history →" in its footer) rather than
                  leaving status undefined (a blank status reads as a rendering
                  bug, not a deliberate omission). */}
              <BSIndexRow label={weekTotals[0].l} figure={`${weekTotals[0].v}/${weekTotals[0].max}`} status={tr('home:action.viewHistory', { defaultValue: 'View history ›' })} onOpen={() => setWeekStat(weekTotals[0])} />
              <BSIndexRow label={weekTotals[1].l} figure={`${weekTotals[1].v.toLocaleString(_dateLoc)}/${weekTotals[1].max.toLocaleString(_dateLoc)}`} status={weekTotals[1].goalFrame} onOpen={() => setWeekStat(weekTotals[1])} />
            </>
          );
        })()}

        {/* CHECK-IN residue — BSTodayNudge's row variant; only renders once today's
            check-in is logged (the bulletin owns the due state, above the lead). */}
        <BSTodayNudge variant="row" onOpen={() => setTodayPage(true)} />
      </div>

      {/* THE DOOR SHELF — STEPS · GOAL · PROGRESS · SHOP, horizontal snap-scroll,
          3 visible + a 12px end-peek so the 4th door shows a sliver. Native buttons
          in DOM order (VoiceOver traversal order == visual order).
          `stepsToday` is read from the HOISTED const (Step 2, top of BSClientHome's
          hooks block) — NOT called here. No hook may be called inside this render
          IIFE (or anywhere in the main-return JSX): BSClientHome has 8 early-return
          overlays above this point, so a hook called here would be skipped on those
          renders and violate the Rules of Hooks. */}
      {(() => {
        const teal = t.isLight ? '#0a8f87' : '#34d6c5';
        const openStepsDoor = () => {
          if (stepsToday.hasData) { setStepsHistory(true); return; }
          try { window.dispatchEvent(new CustomEvent('shape:openIntegrations')); } catch (e) {}
        };
        const stepsFigure = stepsToday.todayKnown ? stepsToday.val.toLocaleString(_dateLoc) : '—';
        const stepsStatus = !stepsToday.hasData
          ? tr('home:steps.connectWatch', { defaultValue: 'Connect a watch' })
          : !stepsToday.todayKnown
            ? tr('home:steps.noneToday', { defaultValue: 'No steps yet today' })
            : stepsToday.hit
              ? tr('home:steps.goalHit', { defaultValue: 'Goal hit ✓' })
              : tr('home:steps.toGo', { defaultValue: '{count, number} to go', count: Math.max(0, stepsToday.goal - stepsToday.val) });
        return (
          <>
            {/* The doors join the index above as stacked dot-leader rows (owner
                call 2026-07-13) — the 2×2 boxed shelf is gone. */}
            <div style={{ padding: `0 ${t.padX}px 12px` }}>
              <BSShelfDoor c={teal} eyebrow={tr('home:door.steps', { defaultValue: 'Steps' })} figure={stepsFigure} status={stepsStatus} pct={stepsToday.hasData && stepsToday.todayKnown ? stepsToday.pct : undefined} onOpen={openStepsDoor} />
              <BSMeGoalCard onOpen={() => setGoalsPage(true)} />
              <BSProgressDoor onOpen={() => setHomeProgressPage(true)} />
              <BSShelfDoor c={teal} eyebrow={tr('home:door.shopList', { defaultValue: 'Shop list' })} figure="→" status={tr('home:door.byAisle', { defaultValue: 'By aisle' })} onOpen={() => { try { window.__bsPendingGrocery = true; } catch (e) {} goEat(); }} />
            </div>
            {stepsHistory && <BSStepsHistory onClose={() => setStepsHistory(false)} />}
          </>
        );
      })()}

      {/* Week-stat detail sheet */}
      {weekStat && createPortal(
        <div onClick={() => setWeekStat(null)} style={{ position: 'absolute', inset: 0, zIndex: 200, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }}>
          <div onClick={e => e.stopPropagation()} className="bs-scroll" style={{ width: '100%', background: t.PAPER, borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: `18px ${t.padX}px calc(20px + env(safe-area-inset-bottom, 0px))`, maxHeight: '82%', overflowY: 'auto', borderTop: `1px solid ${t.RULE}` }}>
            <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }}>
              <div>
                <div style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.2em', textTransform: 'uppercase', color: weekStat.c, fontWeight: 700 }}>{tr('home:weekStat.thisWeek', { defaultValue: '{label} · this week', label: weekStat.l })}</div>
                <div style={{ marginTop: 4, fontFamily: t.DISPLAY, fontSize: 34, fontWeight: 700, color: t.INK, letterSpacing: '-0.04em', lineHeight: 1 }}>{weekStat.v.toLocaleString(_dateLoc)}<span style={{ fontFamily: t.DISPLAY, fontSize: 16, color: t.INK50, marginLeft: 6 }}>/ {weekStat.max.toLocaleString(_dateLoc)}</span></div>
              </div>
            </div>

            {weekStat.chart ? (
              <div style={{ marginTop: 18 }}>
                <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 6, height: 130 }}>
                  {weekStat.series.map(([d, val], i) => {
                    const peak = Math.max(...weekStat.series.map(x => x[1]), weekStat.max);
                    const h = Math.max(4, Math.round((val / peak) * 110));
                    return (
                      <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 }}>
                        <span style={{ fontFamily: t.MONO, fontSize: 8, color: t.INK50, fontVariantNumeric: 'tabular-nums' }}>{val.toLocaleString(_dateLoc)}</span>
                        <div style={{ width: '100%', maxWidth: 26, height: h, borderRadius: 6, background: weekStat.c }} />
                        <span style={{ fontFamily: t.MONO, fontSize: 8.5, color: t.INK50, letterSpacing: '0.04em' }}>{d}</span>
                      </div>
                    );
                  })}
                </div>
                <div style={{ marginTop: 14, fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50, fontWeight: 600 }}>{tr('home:weekStat.chartFoot', { defaultValue: '7-day average · target {target, number} kcal', target: weekStat.max })}</div>
              </div>
            ) : (
              <div style={{ marginTop: 14 }}>
                {(weekStat.history || []).map(([day, label, tag], i, arr) => (
                  <div key={i} style={{ display: 'grid', gridTemplateColumns: '40px 1fr auto', alignItems: 'center', gap: 12, padding: '12px 0', borderBottom: i === arr.length - 1 ? 0 : `1px solid ${t.HAIR}` }}>
                    <span style={{ fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK50 }}>{day}</span>
                    <span style={{ fontFamily: t.DISPLAY, fontSize: 14.5, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em' }}>{label}</span>
                    <span style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.1em', textTransform: 'uppercase', color: tag === 'Scheduled' ? t.INK50 : weekStat.c, fontWeight: 700 }}>{tag}</span>
                  </div>
                ))}
              </div>
            )}

            <button onClick={() => setWeekStat(null)} style={{ width: '100%', marginTop: 18, padding: '13px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK70, fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', cursor: 'pointer' }}>{tr('home:action.close', { defaultValue: 'Close' })}</button>
          </div>
        </div>,
        (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || document.body
      )}

      {/* THIS WEEK — (moved to top) */}

      {/* ── HOME WIDGETS — user-added stats & blocks ─────────────── */}
      {(() => {
        const added = _bsHomeWidgets(tweaks);
        const setList = (next) => setTweak('homeWidgets', _bsEncodeWidgets(next));
        const remove = (k) => setList(added.filter(w => w.key !== k));
        const add    = (k) => { if (!added.find(w => w.key === k)) setList([...added, { key: k, span: 2 }]); };
        const setSpan = (k, span) => setList(added.map(w => w.key === k ? { ...w, span } : w));
        const addedKeys = added.map(w => w.key);
        return (
          <>
            {added.length > 0 && (
              <>
                <BSSection title={tr('home:widgets.title', { defaultValue: 'Your widgets' })} meta={tr('home:widgets.active', { defaultValue: '{count, plural, one {# active} other {# active}}', count: added.length })} />
                <div style={{ padding: `${t.sectGap}px ${t.padX}px 4px`, display: 'grid', gridTemplateColumns: 'minmax(0,1fr) minmax(0,1fr)', gap: 10 }}>
                  {added.map(w => (
                    <div key={w.key} style={{ minWidth: 0, gridColumn: w.span === 1 ? 'span 2' : 'span 1' }}>
                      <BSWidgetSlot widgetKey={w.key} onRemove={remove} />
                    </div>
                  ))}
                </div>
              </>
            )}
          </>
        );
      })()}

      <BSFooter right={tr('home:footer.page', { defaultValue: 'Pg 1 of 1' })} />
      {showLogActivity && <BSLogActivity onClose={() => setShowLogActivity(false)} onSaved={() => { refreshAnalytics(); setTimeout(refreshAnalytics, 700); }} />}
      {showMood && <BSMoodSheet onClose={() => setShowMood(false)} onSaved={() => { refreshAnalytics(); setTimeout(refreshAnalytics, 700); }} />}
    </BSPage>
  );
}

// ─── helper: tweaks-backed widget list ─────────────────────
// Encoded as comma-separated "key:span" pairs; legacy "key" decodes as span 2.
function _bsHomeWidgets(tweaks) {
  const v = tweaks.homeWidgets;
  const arr = typeof v === 'string'
    ? v.split(',').filter(Boolean)
    : Array.isArray(v) ? v : [];
  return arr.map(item => {
    if (typeof item !== 'string') return null;
    const [key, span] = item.split(':');
    if (!key) return null;
    return { key, span: span === '1' ? 1 : 2 };
  }).filter(Boolean);
}
function _bsEncodeWidgets(list) {
  return list.map(w => `${w.key}:${w.span}`).join(',');
}

// Index of today within a Mon–Sun week (0 = Mon … 6 = Sun).
function bsWeekdayIdx(d = new Date()) { return (d.getDay() + 6) % 7; }

// Build the 7-day Train PROGRAM from live assigned workouts. Workouts with a
// scheduled_date land on that weekday; any unscheduled ones are laid onto the
// open weekdays in order so a client with a plan but no dates still sees real
// data. Days with no workout render as rest. Presentation (titles, accents,
// tags) is derived here — the API returns only raw plan data.
function bsBuildTrainProgram(workouts, t) {
  const DOW = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  const ACCENTS = [t.RUST, t.AMBER, t.BLUE];
  const monday = new Date(); monday.setHours(0, 0, 0, 0);
  monday.setDate(monday.getDate() - bsWeekdayIdx(monday));
  const dateFor = (i) => { const d = new Date(monday); d.setDate(d.getDate() + i); return d; };

  // Slot workouts onto the week. Dated rows claim their day first; then
  // weekly-repeat self sessions (payload.repeatDow) fill their weekdays via
  // bsSlotRepeats (respecting taken slots); finally any remaining undated rows
  // fill the gaps in order.
  const mondayISO = `${monday.getFullYear()}-${String(monday.getMonth() + 1).padStart(2, '0')}-${String(monday.getDate()).padStart(2, '0')}`;
  const slots = [null, null, null, null, null, null, null];
  const repeats = [];
  const unscheduled = [];
  for (const w of (workouts || [])) {
    if (w.scheduledDate) {
      // Dated rows belong to their exact day. In this week + slot free → place it;
      // slot taken or outside this week (a program's future/past day) → ignore
      // (the deck is a 7-day view; other weeks show on the calendar).
      const dt = new Date(w.scheduledDate + 'T00:00:00');
      const idx = Math.round((dt - monday) / 86400000);
      if (idx >= 0 && idx <= 6 && !slots[idx]) slots[idx] = w;
      continue;
    }
    if (Array.isArray(w.repeatDow) && w.repeatDow.length) { repeats.push({ ...w, payload: { repeatDow: w.repeatDow } }); continue; }
    unscheduled.push(w);
  }
  // bsSlotRepeats reads payload.repeatDow — carry the original workout on the slot.
  const repeatByDow = bsSlotRepeats(repeats, mondayISO);
  for (let i = 0; i < 7; i++) {
    if (!slots[i] && repeatByDow[i]) {
      const orig = repeats.find((r) => r === repeatByDow[i]);
      slots[i] = orig || repeatByDow[i];
    }
  }
  for (let i = 0; i < 7 && unscheduled.length; i++) {
    if (!slots[i]) slots[i] = unscheduled.shift();
  }

  return slots.map((w, i) => {
    const d = dateFor(i);
    const label = `${DOW[i]} ${d.getDate()}`;
    if (!w) {
      return {
        d: label, kicker: 'The Recovery', title: 'Rest\nday.', tag: 'REST',
        tagColor: t.GREEN, accent: t.GREEN, headline: 'Full rest.',
        meta: 'No session · 0 min', copy: 'No workout scheduled today. Recover, eat well, sleep.',
        moves: [], total: '0 sessions', coachLine: 'Recovery is training. Take the day.',
      };
    }
    const moves = (w.exercises || []).map((e, j) => {
      // Segment rows (a run/ride/swim leg or a Hyrox station) show their free
      // descriptor as the scheme line, with no load column. `video` = the
      // trainer's form clip — threaded through so the live session's ▶ How-to
      // chip can reach it (it was dropped here, making the chip unreachable
      // on real coached plans — CodeRabbit P2 on the Cockpit PR).
      if (e.seg) return { n: String(j + 1).padStart(2, '0'), m: e.name, s: e.seg, l: '', video: e.video || null };
      const sr = [e.sets, e.reps].filter(Boolean).join(' × ');
      const s = [sr, e.rest].filter(Boolean).join(' · ');
      return { n: String(j + 1).padStart(2, '0'), m: e.name, s: s || '—', l: e.load || '—', video: e.video || null };
    });
    const isSelf = !!w.selfAuthored;
    const prog = w.program && w.program.id ? w.program : null;
    const isCustom = w.kind === 'custom';
    const timeLabel = w.time ? (() => {
      const [h, m] = String(w.time).split(':').map(Number);
      if (Number.isNaN(h)) return '';
      const ap = h >= 12 ? 'PM' : 'AM';
      return `${h % 12 === 0 ? 12 : h % 12}:${String(m || 0).padStart(2, '0')} ${ap}`;
    })() : '';
    // Honest byline: self days are "Programmed by you" (or the program name · Wn),
    // never a fabricated coach name; coach days keep the coach copy.
    const selfByline = prog ? `${prog.name || 'Your program'}${prog.week ? ` · Week ${prog.week}` : ''}` : 'Programmed by you';
    return {
      d: label,
      kicker: isSelf ? 'The Training' : 'The Training',
      title: w.title || 'Workout',
      tag: isSelf ? 'YOURS' : (isCustom ? 'CUSTOM' : 'FEATURE'),
      tagColor: isSelf ? t.ACCENT : (isCustom ? t.BLUE : t.AMBER),
      accent: ACCENTS[i % ACCENTS.length],
      time: w.time || '',
      timeLabel,
      adjustGen: w.adjustGen ?? (w.payload && w.payload.adjustGen) ?? null,
      headline: w.title || 'Workout',
      meta: [w.durationMin ? `${w.durationMin} min` : null, `${moves.length} move${moves.length === 1 ? '' : 's'}`].filter(Boolean).join(' · '),
      copy: w.description || (isSelf ? selfByline : 'Programmed by your coach.'),
      moves,
      total: `${moves.length} move${moves.length === 1 ? '' : 's'}`,
      coachLine: isSelf ? selfByline : (w.description || 'Move with intent. Quality over load.'),
      // Self-authoring metadata the hero + edit affordance read.
      selfAuthored: isSelf,
      program: prog,
      workoutId: w.id || null,
      repeatDow: Array.isArray(w.repeatDow) ? w.repeatDow : null,
    };
  });
}

// ═══════════════════════════════════════════════════════════
// ── Shared "tracklist" UI for the Train + Eat day views ────────────────────
// Rounded weekly calendar: day letter, date number, status dot; active tile
// gets a teal outline + faint wash.
// Find-a-coach leader row — the marketplace deep link pinned atop Train + Eat.
// Zero-box: 3px role spine + hairline bounds; role color rides spine/glyph/tag/
// arrow, the title stays theme ink. One shared implementation (the trainer bar
// was previously duplicated verbatim in the Build-door branch and the deck).
function BSFindCoachBar({ role, onOpen }) {
  const t = useBS();
  const trainer = role === 'trainer';
  const c = trainer ? '#c0533b' : '#a07a2e';
  const glyphC = trainer ? '#c0533b' : '#b8923f';
  return (
    <button type="button" onClick={onOpen} style={{ display: 'flex', alignItems: 'center', gap: 9, margin: `8px ${t.padX}px 0`, width: `calc(100% - ${t.padX * 2}px)`, boxSizing: 'border-box', minHeight: 44, padding: '4px 2px 4px 10px', background: 'transparent', border: 0, borderTop: `1px solid ${t.HAIR}`, borderBottom: `1px solid ${t.HAIR}`, borderLeft: `3px solid ${c}`, cursor: 'pointer', textAlign: 'left' }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={glyphC} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ flexShrink: 0 }}>
        {trainer
          ? <path d="M4 9v6M7 7.5v9M17 7.5v9M20 9v6M7 12h10" />
          : <><path d="M12 8c-1-2-4-2.4-5.6-.9C4 8.8 4.6 13 7 16.4c1 1.4 1.9 1.9 2.7 1.5.8-.4 1.8-.4 2.6 0 .8.4 1.7-.1 2.7-1.5 2.4-3.4 3-7.6.6-9.3C16 5.6 13 6 12 8Z" /><path d="M12 8c0-1.8 1-3.2 3-3.7" /></>}
      </svg>
      <span style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 13.5, color: t.INK, whiteSpace: 'nowrap' }}>{trainer ? 'Find a trainer' : 'Find a nutritionist'}</span>
      <span style={{ fontFamily: t.MONO, fontSize: 7.5, color: glyphC, letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700, whiteSpace: 'nowrap' }}>{trainer ? 'Vetted coaches' : 'Vetted RDs'}</span>
      <span aria-hidden style={{ flex: 1, borderBottom: `1.5px dotted ${bsTHexA(t.INK, 0.22)}`, transform: 'translateY(-2px)', minWidth: 12 }} />
      <span style={{ color: glyphC, fontSize: 14, flexShrink: 0, fontWeight: 700 }}>→</span>
    </button>
  );
}

function BSWeekStrip({ activeIdx, onSelect, restFlags = [] }) {
  const t = useBS();
  const DOWL = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  const _now = new Date();
  const todayIdx = (_now.getDay() + 6) % 7;
  const mon = new Date(_now); mon.setHours(0, 0, 0, 0); mon.setDate(_now.getDate() - todayIdx);
  const dates = Array.from({ length: 7 }, (_, i) => { const d = new Date(mon); d.setDate(mon.getDate() + i); return d.getDate(); });
  const names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  return (
    <div style={{ padding: `12px ${t.padX}px 4px` }}>
      {/* Calendar rule with a heat needle over the active day (Session Meter grammar). */}
      <div aria-hidden style={{ position: 'relative', height: 2, background: t.RULE, margin: '5px 2px 0' }}>
        {DOWL.map((_, i) => (
          <span key={i} style={{ position: 'absolute', left: `${((i + 0.5) * 100) / 7}%`, top: -3, width: 1.5, height: 8, background: t.RULE }} />
        ))}
        <span style={{ position: 'absolute', left: `${((activeIdx + 0.5) * 100) / 7}%`, top: -7, width: 0, height: 0, borderLeft: '5px solid transparent', borderRight: '5px solid transparent', borderTop: `7px solid ${t.ACCENT}`, transform: 'translateX(-5px)' }} />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', marginTop: 6 }}>
        {DOWL.map((L, i) => {
          const on = i === activeIdx;
          return (
            <button type="button" key={i} onClick={() => onSelect(i)} aria-label={`${names[i]} ${dates[i]}${on ? ', selected' : ''}`} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, minHeight: 44, padding: '4px 0', background: 'transparent', border: 0, cursor: 'pointer' }}>
              <span style={{ fontFamily: t.MONO, fontSize: 7.5, letterSpacing: '0.16em', fontWeight: 700, color: on ? t.ACCENT : t.INK50 }}>{L}</span>
              <span style={{ fontFamily: t.DISPLAY, fontWeight: t.W.display, fontSize: 14, color: on ? t.INK : t.INK50, letterSpacing: '-0.03em', lineHeight: 1.15, fontVariantNumeric: 'tabular-nums' }}>{dates[i]}</span>
              <span aria-hidden style={{ width: 4, height: 3, borderRadius: 1, background: restFlags[i] ? t.GREEN : 'transparent' }} />
            </button>
          );
        })}
      </div>
    </div>
  );
}

// Section header: teal kicker, big serif title, optional right-aligned action.
function BSTrackHeader({ kicker, title, actionLabel, onAction }) {
  const t = useBS();
  return (
    <div style={{ padding: `18px ${t.padX}px 0` }}>
      <div style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.24em', textTransform: 'uppercase', color: t.ACCENT, fontWeight: 700, marginBottom: 5 }}>{kicker}</div>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }}>
        <div style={{ fontFamily: t.DISPLAY, fontWeight: t.W.display, fontSize: 21, letterSpacing: '-0.03em', color: t.INK, lineHeight: 1 }}>{title}</div>
        {actionLabel && <button onClick={onAction} style={{ background: 'transparent', border: 0, color: t.ACCENT, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', cursor: 'pointer', padding: 0, whiteSpace: 'nowrap' }}>{actionLabel} →</button>}
      </div>
    </div>
  );
}

// Coach/nutritionist playlist card. When the playlist has a Spotify URL, the
// client can save it straight into their own Spotify library (follow).
// Spotify wordmark glyph, reused at a few sizes/fills.
const bsSpotifyGlyph = (size = 22, fill = '#fff') => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill} aria-hidden="true"><path fillRule="evenodd" clipRule="evenodd" d="M12 0C5.4 0 0 5.4 0 12s5.4 12 12 12 12-5.4 12-12S18.66 0 12 0zm5.521 17.34c-.24.359-.66.48-1.021.24-2.82-1.74-6.36-2.101-10.561-1.141-.418.122-.779-.179-.899-.539-.12-.421.18-.78.54-.9 4.56-1.021 8.52-.6 11.64 1.32.42.18.479.659.301 1.02zm1.44-3.3c-.301.42-.841.6-1.262.3-3.239-1.98-8.159-2.58-11.939-1.38-.479.12-1.02-.12-1.14-.6-.12-.48.12-1.021.6-1.141C9.6 9.9 15 10.561 18.72 12.84c.361.181.54.78.241 1.2zm.12-3.36C15.24 8.4 8.82 8.16 5.16 9.301c-.6.179-1.2-.181-1.38-.721-.18-.601.18-1.2.72-1.381 4.26-1.26 11.28-1.02 15.721 1.621.539.3.719 1.02.42 1.56-.299.421-1.02.599-1.559.3z"/></svg>
);
// Apple logo glyph (Apple Music), reused like the Spotify one.
const bsAppleGlyph = (size = 22, fill = '#fff') => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill} aria-hidden="true"><path d="M17.05 12.04c-.03-2.86 2.34-4.23 2.44-4.3-1.33-1.95-3.4-2.22-4.14-2.25-1.77-.18-3.45 1.04-4.35 1.04-.9 0-2.28-1.02-3.75-.99-1.93.03-3.71 1.12-4.7 2.85-2 3.48-.51 8.63 1.44 11.45.95 1.38 2.09 2.93 3.58 2.87 1.44-.06 1.98-.93 3.72-.93 1.73 0 2.22.93 3.74.9 1.54-.03 2.52-1.41 3.46-2.79 1.09-1.6 1.54-3.15 1.57-3.23-.03-.02-3.01-1.16-3.04-4.57zM14.2 4.38c.79-.96 1.33-2.29 1.18-3.62-1.14.05-2.53.76-3.35 1.72-.73.85-1.37 2.21-1.2 3.51 1.27.1 2.57-.65 3.37-1.61z"/></svg>
);

function BSPlaylistCard({ kicker, title, meta, color, spotifyUrl, url, provider, tracks }) {
  const t = useBS();
  const [open, setOpen] = useStateBSC(false);
  const [saveState, setSaveState] = useStateBSC('idle'); // idle | saving | saved | error
  const [saveMsg, setSaveMsg] = useStateBSC('');
  const list = Array.isArray(tracks) ? tracks : [];
  const isApple = provider === 'apple';
  const pUrl = url || spotifyUrl || '';
  const pName = isApple ? 'Apple Music' : 'Spotify';
  const glyph = isApple ? bsAppleGlyph : bsSpotifyGlyph;
  const isProvUrl = isApple ? /music\.apple\.com\//i.test(pUrl) : /(^|\.)spotify\.com\//i.test(pUrl);
  // Only genuine playlist links can be followed into a user's library. For Apple
  // that means a CATALOG playlist (a `pl.` id) — saveAppleMusicPlaylist can't add
  // a personal library URL (`/library/playlist/p.xxx`), so don't offer Save for it.
  const canSave = isApple ? (/music\.apple\.com\//i.test(pUrl) && /\/pl\.[A-Za-z0-9-]+/i.test(pUrl)) : (isProvUrl && /playlist[/:]/i.test(pUrl));
  const openProvider = () => {
    const fallback = isApple
      ? `https://music.apple.com/search?term=${encodeURIComponent(String(title || 'playlist'))}`
      : `https://open.spotify.com/search/${encodeURIComponent(String(title || 'playlist'))}`;
    const u = isProvUrl ? pUrl : fallback;
    try { window.open(u, '_blank', 'noopener,noreferrer'); } catch (e) { try { window.location.href = u; } catch (e2) {} }
  };
  // Follow (save) the coach's playlist into the signed-in member's own library.
  // Spotify goes through /api/integrations/spotify/save-playlist (bridge or a
  // /m/ cookie fallback); Apple Music writes client-side via MusicKit (no server
  // route). A missing/expired connection surfaces as a "connect" message.
  const saveToLibrary = async () => {
    if (saveState === 'saving' || saveState === 'saved') return;
    setSaveState('saving'); setSaveMsg('');
    try {
      if (isApple) {
        const fn = window.ShapeIntegrations && window.ShapeIntegrations.saveAppleMusicPlaylist;
        if (typeof fn !== 'function') throw new Error('Apple Music is not available here.');
        await fn(pUrl);
      } else {
        let done = false;
        const fn = window.ShapeIntegrations && window.ShapeIntegrations.saveSpotifyPlaylist;
        if (typeof fn === 'function') {
          try { await fn(pUrl); done = true; }
          catch (e) { if (!/not configured|VITE_API_BASE_URL/i.test(e && e.message || '')) throw e; }
        }
        if (!done) {
          const res = await fetch('/api/integrations/spotify/save-playlist', {
            method: 'POST', credentials: 'same-origin',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ url: pUrl }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) throw new Error(data.error || 'Could not save to Spotify.');
        }
      }
      setSaveState('saved');
      try { window.__bsToast && window.__bsToast('Saved to your ' + pName, 'ok'); } catch (e) {}
    } catch (e) {
      const msg = (e && e.message) || ('Could not save to ' + pName + '.');
      setSaveState('error'); setSaveMsg(msg);
      // For "not linked / not signed in" errors the popup shows an inline
      // "Connect … to save" CTA — skip the toast so it isn't doubled up.
      const needsConnect = /sign ?in|connect (spotify|apple)|authentic|log ?in|unauthor|reconnect|before saving|not connected|not configured|not available/i.test(msg);
      if (!needsConnect) { try { window.__bsToast && window.__bsToast(msg, 'error'); } catch (e2) {} }
    }
  };
  // Total track count parsed from the meta line ("… · 14 tracks") so the popup
  // can say "first 6 of 14" when we only carry a preview.
  const totalTracks = (() => { const m = /(\d+)\s*tracks/i.exec(String(meta || '')); return m ? Number(m[1]) : null; })();

  const sheet = open ? createPortal(
    <div onClick={() => setOpen(false)} style={{ position: 'absolute', inset: 0, zIndex: 200, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }}>
      <div onClick={e => e.stopPropagation()} className="bs-scroll" style={{ width: '100%', background: t.PAPER, borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: `18px ${t.padX}px calc(20px + env(safe-area-inset-bottom, 0px))`, maxHeight: '82%', overflowY: 'auto', borderTop: `1px solid ${t.RULE}` }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 11 }}>
          <div style={{ width: 42, height: 42, flexShrink: 0, borderRadius: 11, background: color, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{glyph(24, '#fff')}</div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.14em', textTransform: 'uppercase', color, fontWeight: 700, marginBottom: 2 }}>{kicker}</div>
            <div style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 19, color: t.INK, letterSpacing: '-0.02em' }}>{title}</div>
            <div style={{ fontFamily: t.MONO, fontSize: 8.5, color: t.INK50, marginTop: 2, letterSpacing: '0.04em' }}>{meta}</div>
          </div>
        </div>
        <div style={{ marginTop: 16, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.16em', textTransform: 'uppercase', color: t.INK50, fontWeight: 700 }}>
          {totalTracks && totalTracks > list.length ? `Preview · first ${list.length} of ${totalTracks}` : 'Tracklist'}
        </div>
        <div style={{ marginTop: 6 }}>
          {list.length === 0 ? (
            <div style={{ fontFamily: t.MONO, fontSize: 10, color: t.INK50, padding: '10px 2px', letterSpacing: '0.03em' }}>Open in {pName} to see the full tracklist.</div>
          ) : list.map((track, i) => (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '10px 2px', borderBottom: i < list.length - 1 ? `1px solid ${t.HAIR}` : 'none' }}>
              <div style={{ width: 16, textAlign: 'right', flexShrink: 0, fontFamily: t.MONO, fontSize: 10, color: t.INK50 }}>{i + 1}</div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontFamily: t.DISPLAY, fontSize: 14, fontWeight: 600, color: t.INK, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{track.a}</div>
                <div style={{ fontFamily: t.MONO, fontSize: 9, color: t.INK50, marginTop: 1, letterSpacing: '0.03em' }}>{track.b}</div>
              </div>
              {track.len && <div style={{ flexShrink: 0, fontFamily: t.MONO, fontSize: 9, color: t.INK50, letterSpacing: '0.03em' }}>{track.len}</div>}
            </div>
          ))}
        </div>
        {canSave && (
          <button onClick={saveToLibrary} disabled={saveState === 'saving'} style={{ width: '100%', marginTop: 16, padding: '13px', borderRadius: 999, border: `1px solid ${color}`, background: saveState === 'saved' ? color : 'transparent', color: saveState === 'saved' ? '#04201d' : color, fontFamily: t.MONO, fontSize: 10.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', cursor: saveState === 'saving' ? 'wait' : 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
            {saveState === 'saved' ? '✓ Saved to ' + pName : saveState === 'saving' ? 'Saving…' : saveState === 'error' ? 'Try again' : '♡ Save to my ' + pName}
          </button>
        )}
        {canSave && saveState === 'error' && (
          // Most failures here mean the member hasn't linked the service (or
          // isn't signed in) — point them to where they connect it instead of
          // the raw error. Other errors (e.g. network) still show their message.
          /sign ?in|connect (spotify|apple)|authentic|log ?in|unauthor|reconnect|before saving|not connected|not configured|not available/i.test(saveMsg) ? (
            <button
              onClick={() => { setOpen(false); try { window.dispatchEvent(new CustomEvent('shape:openIntegrations')); } catch (e) {} }}
              style={{ width: '100%', marginTop: 8, padding: '11px 12px', borderRadius: t.RADIUS_SM, border: `1px dashed ${color}`, background: 'transparent', cursor: 'pointer', display: 'block', textAlign: 'center' }}
            >
              <div style={{ fontFamily: t.MONO, fontSize: 10, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color }}>Connect {pName} to save →</div>
              <div style={{ marginTop: 3, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.08em', textTransform: 'uppercase', color: t.INK50 }}>Settings · Connected apps</div>
            </button>
          ) : (
            <div style={{ marginTop: 6, fontFamily: t.MONO, fontSize: 9, color: t.RUST, letterSpacing: '0.02em', lineHeight: 1.4, textAlign: 'center' }}>{saveMsg}</div>
          )
        )}
        <button onClick={openProvider} style={{ width: '100%', marginTop: canSave ? 8 : 16, padding: '13px', borderRadius: 999, border: 0, background: color, color: '#04201d', fontFamily: t.MONO, fontSize: 10.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
          {glyph(15, '#04201d')} Open in {pName}
        </button>
        <button onClick={() => setOpen(false)} style={{ width: '100%', marginTop: 8, padding: '12px', borderRadius: t.RADIUS_SM, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK70, fontFamily: t.MONO, fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', cursor: 'pointer' }}>Close</button>
      </div>
    </div>,
    (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || document.body
  ) : null;

  return (
    <>
      <div role="button" tabIndex={0} aria-label={`Preview ${title}`}
        onClick={() => setOpen(true)}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOpen(true); } }}
        style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '10px 0', border: 0, background: 'transparent', cursor: 'pointer', width: '100%', textAlign: 'left' }}>
        <div style={{ width: 38, height: 38, flexShrink: 0, borderRadius: 10, background: color, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{glyph(22, '#fff')}</div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: t.MONO, fontSize: 8, letterSpacing: '0.14em', textTransform: 'uppercase', color, fontWeight: 700, marginBottom: 2 }}>{kicker}</div>
          <div style={{ fontFamily: t.DISPLAY, fontWeight: 700, fontSize: 15, color: t.INK, letterSpacing: '-0.01em' }}>{title}</div>
          <div style={{ fontFamily: t.MONO, fontSize: 8.5, color: t.INK50, marginTop: 2, letterSpacing: '0.04em', lineHeight: 1.35 }}>{meta}</div>
        </div>
        <button onClick={(e) => { e.stopPropagation(); openProvider(); }} aria-label={`Open in ${pName}`} style={{ width: 32, height: 32, flexShrink: 0, borderRadius: 999, border: `1px solid ${color}`, background: 'transparent', color, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 11 }}>▶</button>
      </div>
      {sheet}
    </>
  );
}

