  const links = (cu.links && typeof cu.links === 'object') ? BS_PROFILE_LINKS.map((l) => [l, cu.links[l.key]]).filter(([, v]) => v && String(v).trim()) : [];
  const pinned = (cu.pinned && cu.pinned.title) ? cu.pinned : null;
