    CLIENT: { color: '#2ee0c4', label: tr('feed:roleTag.client', { defaultValue: 'Client' }) },
    NUTRI: { color: '#e0b15a', label: tr('feed:roleTag.nutritionist', { defaultValue: 'Nutritionist' }) },
