  const [activityFeed, setActivityFeed] = useStateBSC([]);
  // Declared BEFORE the post-loader effect below (its dep array reads feedNonce) —
  // moving it here avoids a temporal-dead-zone ReferenceError when BSClientFeed renders.
  const [feedNonce, setFeedNonce] = useStateBSC(0);
  // Community feed viewing lens — UNIVERSAL (everyone's public activity, the
  // default) vs FOLLOWING (accepted follows + you, incl. their followers-tier
  // posts). Persisted per device; the query + RLS enforce visibility.
  const [feedMode, setFeedMode] = useStateBSC(() => {
    try { return localStorage.getItem('shape.feedMode') === 'following' ? 'following' : 'universal'; } catch (e) { return 'universal'; }
  });
  const switchFeedMode = (m) => { setFeedMode(m); try { localStorage.setItem('shape.feedMode', m); } catch (e) {} };
  // Activity-type filter chips (All / Workouts / Runs / PRs) — session-only on
  // purpose (a sticky filter reads as a broken feed on the next open).
  const [feedType, setFeedType] = useStateBSC('all');
  React.useEffect(() => {
    let active = true;
    (async () => {
      try {
        const res = await window.ShapeCommunity?.listPosts?.(feedMode);
        const rows = Array.isArray(res?.data) ? res.data : [];
        // Universal keeps the old behavior (sample until live rows exist).
        // Following must be allowed to be EMPTY — an honest empty state, never
        // the demo sample presented as your follows' activity.
        if (active && (rows.length || (feedMode === 'following' && res?.stored === 'supabase'))) {
          const mapped = rows.map(mapPost).filter(p => p.body);
          const acts = rows.map(bsActivityFromPost).filter(Boolean);
          setPosts(mapped); setPostsLive(true); setActivityFeed(acts);
          // Batch the authors' all-time points → real tier per user for the bubbles.
          const ids = [...new Set([myUserId, ...mapped.map(p => p.userId), ...acts.map(a => a.userId)].filter(Boolean))];
          if (ids.length && window.ShapeProfiles?.getUserPoints) {
            window.ShapeProfiles.getUserPoints(ids).then(pointsMap => {
              if (!active || !pointsMap) return;
              const tiers = {};
              Object.keys(pointsMap).forEach(uid => { tiers[uid] = bsTierForPoints(pointsMap[uid]); });
              setTierByUser(tiers);
            }).catch(() => {});
          }
          // Members' profile photos → carry into the feed avatars (visibility-gated).
          if (ids.length && window.ShapeProfiles?.getUserAvatars) {
            window.ShapeProfiles.getUserAvatars(ids).then(avs => {
              if (active && avs) setAvatarByUser(avs);
            }).catch(() => {});
          }
        } else if (active && res?.stored === 'supabase') {
          // Universal came back live-but-EMPTY (e.g. escaping an empty Following)
          // — reset to the legacy first-load state so signed-in falls back to the
          // demo cards (postsLive false), instead of leaking Following's live-empty
          // flags across modes. Errors keep the previous state (never downgrade).
          setPosts(SAMPLE); setPostsLive(false); setActivityFeed([]);
        }
      } catch { /* keep sample */ }
    })();
    return () => { active = false; };
  }, [feedNonce, feedMode]);
  const [tierByUser, setTierByUser] = useStateBSC({}); // userId → real tier (from Shape Score)
  const [avatarByUser, setAvatarByUser] = useStateBSC({}); // userId → profile photo (data URL)
  // Each chip is its own channel: SHAPE = individual members, TRAINER/NUTRI/
  // CLIENT = that role's peers only. (COMMUNITY swaps to the activity feed in
  // the render below, so `shown` isn't used for it.)
  const shown = ((loggedIn && !postsLive) ? [] : posts).filter(p => p.kind === filter);

  // Tag members in a post/workout — a searchable picker; tagged people ride on
  // the post (metrics.mentions) and render as tappable "with @Name" chips.
  const [tagged, setTagged] = useStateBSC([]); // [{ id, name }]
  const [tagOpen, setTagOpen] = useStateBSC(false);
  const [tagQuery, setTagQuery] = useStateBSC('');
  const [tagResults, setTagResults] = useStateBSC([]);
  React.useEffect(() => {
    if (!tagOpen || !window.ShapeChannels?.searchMembers) return undefined;
    let active = true;
    window.ShapeChannels.searchMembers(tagQuery).then(r => { if (active) setTagResults(r?.data || []); }).catch(() => {});
    return () => { active = false; };
  }, [tagOpen, tagQuery]);
  const toggleTagged = (m) => {
    const id = m.id || m.user_id || m.name; const nm = m.name || m.full_name || 'Member';
    setTagged(prev => prev.some(x => (x.id || x.name) === id) ? prev.filter(x => (x.id || x.name) !== id) : [...prev, { id: m.id || m.user_id || null, name: nm }]);
  };
  const removeTagged = (id) => setTagged(prev => prev.filter(x => (x.id || x.name) !== id));
  const mentionsPayload = () => tagged.map(x => ({ userId: x.id || null, name: x.name }));

  const post = async () => {
    const body = draft.trim();
    if (!body && tagged.length === 0) return;
    setDraft('');
    // Tag the post with the chip you're posting from (Shape / Community / your
    // role channel) so it lands on that feed — not always the Client feed.
    const kind = (filter && ROLE[filter]) ? filter : myRoleChip;
    const where = ROLE[kind] ? ROLE[kind].label : 'the group';
    const mentions = mentionsPayload();
    setTagged([]);
    setPosts(prev => [{ id: 'tmp-' + Date.now(), who: 'You', mine: true, userId: myUserId, kind, authorKind: myRoleChip, init: bsMyName().trim().charAt(0).toUpperCase(), hue: HUE[kind] || ROLE[kind].color, time: 'now', body, mentions, hearts: 0, replies: 0 }, ...prev]);
    try { await window.ShapeCommunity?.createPost?.({ title: body || 'Tagged', note: body, channel: kind, privacy: 'community', mentions }); window.__bsToast?.(tr('feed:feed.postedTo', { defaultValue: 'Posted to {where}', where }), 'ok'); }
    catch (e) { window.__bsToast?.(e?.message || tr('feed:feed.postError', { defaultValue: 'Could not post.' }), 'err'); }
  };
  // Photo post — upload to community-photos then create a post carrying the URL.
  const feedPhotoRef = React.useRef(null);
  const [photoBusy, setPhotoBusy] = useStateBSC(false);
  const [showLog, setShowLog] = useStateBSC(false);
  const canChatNow = useBSCanChat();
  const [editingPost, setEditingPost] = useStateBSC(null);
  const onFeedPhoto = () => { try { feedPhotoRef.current && feedPhotoRef.current.click(); } catch (e) {} };
  const onFeedPhotoFile = async (e) => {
    const file = e?.target?.files?.[0];
    if (e?.target) e.target.value = '';
    if (!file) return;
    const caption = draft.trim();
    const kind = (filter && ROLE[filter]) ? filter : myRoleChip;
    const where = ROLE[kind] ? ROLE[kind].label : 'the group';
    const mentions = mentionsPayload();
    setPhotoBusy(true);
    try {
      const url = await window.ShapeCommunity?.uploadPhoto?.(file);
      if (!url) throw new Error('Upload failed.');
      setDraft(''); setTagged([]);
      setPosts(prev => [{ id: 'tmp-' + Date.now(), who: 'You', mine: true, userId: myUserId, kind, authorKind: myRoleChip, init: bsMyName().trim().charAt(0).toUpperCase(), hue: HUE[kind] || ROLE[kind].color, time: 'now', body: caption, photo: url, mentions, hearts: 0, replies: 0 }, ...prev]);
      await window.ShapeCommunity?.createPost?.({ title: caption || 'Photo', note: caption, channel: kind, privacy: 'community', photoUrl: url, mentions });
      window.__bsToast?.(tr('feed:feed.photoPostedTo', { defaultValue: 'Photo posted to {where}', where }), 'ok');
    } catch (err) { window.__bsToast?.(err?.message || tr('feed:feed.photoError', { defaultValue: 'Could not post photo.' }), 'err'); }
    finally { setPhotoBusy(false); }
  };
  const like = (p) => {
    setPosts(prev => prev.map(x => x.id === p.id ? { ...x, hearts: (x.hearts || 0) + 1 } : x));
    if (p.id && !String(p.id).startsWith('tmp') && !String(p.id).startsWith('s')) { const lk = window.ShapeCommunity?.toggleLike?.({ postId: p.id }); if (lk && lk.catch) lk.catch(() => {}); }
  };

  // Like + comment on community activity cards (local, demo-side: these Strava-
  // style cards aren't backed by post ids). Keyed by author + timestamp.
  const [actLikes, setActLikes] = useStateBSC({});
  const [actComments, setActComments] = useStateBSC({});
  const [actCmtOpen, setActCmtOpen] = useStateBSC(null);
  const [actDetailsOpen, setActDetailsOpen] = useStateBSC({}); // key → secondary-stat disclosure open
  const [sendPostFor, setSendPostFor] = useStateBSC(null); // ✉ on a feed post → the send-to-DM picker
  const [actCmtDraft, setActCmtDraft] = useStateBSC('');
  // Phase 2 — long-press expressive palette. `actExpr` is MY chosen word per card
  // (key → 'Fire' | 'Props' | …); it re-labels my reaction but stays the SAME
